// 中文内容(简体)。索尼娅至伟强 + 瑞安的完整故事(id 0-12);其余角色的菜单信息已翻译,故事文本待补充。
// 注意:此翻译由 AI 生成,涉及信仰与敏感话题,正式对外使用前建议请母语者校对。
(function () {
  const CHARACTERS = [
    { id: 0, key: 'sonya',  name: '索尼娅', gender: 'ж', theme: '在晚期堕胎中幸存,身有残疾,后被收养', softTheme: "从被拒绝到寻回家庭", color: '#ea8853',
      closingVerse: '"我父母离弃我，耶和华必收留我。"（诗篇 27:10）',
      closingPrayer: '主啊，在别人选择接纳我或拒绝我之前，你已经看见了我。谢谢你是那位永不离弃的父。求你帮助我看自己如你眼中那样宝贵。' },
    { id: 1, key: 'nastya', name: '静雯', gender: 'ж', theme: '在种族屠杀中幸存,饶恕了杀害家人的凶手', softTheme: "失去之后的饶恕", color: '#c2555f',
      closingVerse: '"并要以恩慈相待，存怜悯的心，彼此饶恕，正如神在基督里饶恕了你们一样。"（以弗所书 4:32）',
      closingPrayer: '主啊，你知道这饶恕的代价——你自己在十字架上为此付上了代价。求你赐我力量，照你饶恕我的方式去饶恕：不是因为伤痛不算数，而是因为你比伤痛更强大。' },
    { id: 2, key: 'liza',   name: '丽华',   gender: 'ж', theme: '曾被信任的人虐待;追求正义与饶恕', softTheme: "穿越伤害的路", color: '#397ec6',
      closingVerse: '"耶和华靠近伤心的人，拯救灵性痛悔的人。"（诗篇 34:18）',
      closingPrayer: '主啊，你靠近那些因背叛而心碎的人。饶恕不代表不曾痛过，也不代表要回到不安全的地方。求你按你的时间带领我一步一步走向医治。' },
    { id: 3, key: 'timur',  name: '天宇', gender: 'м', theme: '帮派头目,后成为传道人', softTheme: "从帮派到信仰之路", color: '#e46128',
      closingVerse: '"若有人在基督里，他就是新造的人，旧事已过，都变成新的了。"（哥林多后书 5:17）',
      closingPrayer: '主啊，你带走我的过去，不是要抹去它，而是要它不再决定我是谁。谢谢你让我重新开始。求你帮助我忠于你呼召我成为的那个人。' },
    { id: 4, key: 'sergey', name: '俊杰', gender: 'м', theme: '曾被俘虏和折磨,患有创伤后应激障碍和酗酒,饶恕了折磨他的人', softTheme: "囚禁与饶恕之路", color: '#9ac639',
      closingVerse: '"主耶和华的灵在我身上……差遣我医好伤心的人，报告被掳的得释放。"（以赛亚书 61:1）',
      closingPrayer: '主啊，你正是来到被掳和伤心的人那里——那也包括我。求你不仅释放我脱离别人对我做的事，也释放我脱离它至今仍抓住我内心的部分。在记忆仍然疼痛的地方，赐我平安。' },
    { id: 5, key: 'maksim', name: '明轩', gender: 'м', theme: '涉入腐败入狱,通过一本书归信信仰,如今服侍前囚犯', softTheme: "监狱与新生之路", color: '#7539c6',
      closingVerse: '"耶和华说：我知道我向你们所怀的意念，是赐平安的意念，不是降灾祸的意念，要叫你们末后有指望。"（耶利米书 29:11）',
      closingPrayer: '主啊，即使在铁窗之内，你为我预备的未来也是我看不见的。谢谢你没有放弃我。愿我的第二次生命，成为那些仍在铁窗之内的人的盼望——无论是真正的铁窗，还是他们心里筑起的那道墙。' },
    { id: 6, key: 'kristina', name: '婉清', gender: 'ж', theme: '大学讲师兼活动人士,通过与一位牧师多年的友谊归信', softTheme: "友谊带来的转变", color: '#c68039',
      closingVerse: '"铁磨铁，磨出刃来；朋友相感，也是如此。"（箴言 27:17）',
      closingPrayer: '主啊，谢谢那些没有催促我信主、只是一直陪伴我的人。求你帮助我也成为别人这样的朋友——耐心、真诚，不计较需要多少年。' },
    { id: 7, key: 'polina', name: '佩琳', gender: 'ж', theme: '自杀未遂,身有残疾,成为捍卫生命的倡导者', softTheme: "伤痛化为使命", color: '#ea536e',
      closingVerse: '"赐各样安慰的神。我们在一切患难中，他就安慰我们，叫我们能用神所赐的安慰去安慰那遭各样患难的人。"（哥林多后书 1:3-4）',
      closingPrayer: '主啊，你没有让我的痛白白流逝——你让它变成了能安慰别人的东西。求你继续把我的伤疤变成一个地方，让另一个和我一样痛的人可以走进来。' },
    { id: 8, key: 'marina', name: '玉梅', gender: 'ж', theme: '被人口贩子拐骗为奴,信仰成为支撑', softTheme: "穿越为奴之路", color: '#23dcb7',
      closingVerse: '"住在至高者隐密处的，必住在全能者的荫下。我要论到耶和华说：他是我的避难所，是我的山寨，是我的神，是我所倚靠的。"（诗篇 91:1-2）',
      closingPrayer: '主啊，在那个我被迫带去的最可怕的地方，你是我的避难所，即使我没有别的可以抓住。谢谢你在那看似不可能有你同在的地方仍与我同在。求你继续带领我走向真正的自由——不只是外表上的。' },
    { id: 9, key: 'alina', name: '安琪', gender: 'ж', theme: '毒瘾与街头生活,通过收容所走向康复', softTheme: "街头与回家的路", color: '#de8d24',
      closingVerse: '"相离还远，他父亲看见，就动了慈心，跑去抱着他的颈项，连连与他亲嘴。"（路加福音 15:20）',
      closingPrayer: '主啊，你没有等我先把自己收拾好才接纳我——在我还远的时候，你就跑来迎接我。谢谢我现在拥有的这个家，也谢谢那扇一直敞开的门。' },
    { id: 10, key: 'zara', name: '紫嫣', gender: 'ж', theme: '出身穆斯林家庭后归信基督教,冒着生命危险', softTheme: "冒险的信仰", color: '#c639a0',
      closingVerse: '"得着生命的，将要失丧生命；为我失丧生命的，将要得着生命。"（马太福音 10:39）',
      closingPrayer: '主啊，你知道选择你要付上什么代价。求你赐我勇气，即使代价高昂也持守信心，也求你安慰那些我在这条路上失去的人。' },
    { id: 11, key: 'viktor', name: '伟强', gender: 'м', theme: '无神论记者,通过自己的调查归信', softTheme: "追寻真相", color: '#397fc6',
      closingVerse: '"你们必晓得真理，真理必叫你们得以自由。"（约翰福音 8:32）',
      closingPrayer: '主啊，我本想寻找事实，却找到了你。谢谢你经得起我的调查，也不惧怕我的问题。求你帮助我继续诚实地寻求——在信仰上也一样，不只是在事实上。' },
    { id: 12, key: 'ruslan', name: '瑞安', gender: 'м', theme: '出身宗教家庭,通过与朋友多年的辩论归信', softTheme: "漫长的信仰之路", color: '#accd32',
      closingVerse: '"我们行善，不可丧志；若不灰心，到了时候就要收成。"（加拉太书 6:9）',
      closingPrayer: '主啊，谢谢那位这些年一直没有放弃与我辩论的朋友。愿我也不厌倦在看不见收成的地方撒种，并将我不能选择的时间交托给你。' },
    { id: 13, key: 'roman', name: '罗明', gender: 'м', theme: '毒枭,入狱,成为牧师', softTheme: "监狱与新生", color: '#e3361c',
      closingVerse: '"基督耶稣降世，为要拯救罪人。这话是可信的……在罪人中我是个罪魁……好叫耶稣基督在我这罪魁身上显明他一切的忍耐。"（提摩太前书 1:15-16）',
      closingPrayer: '主啊，如果你能把我变成一个牧师，那么就没有人的故事太黑暗。愿我的生命成为这个真理的见证，给那些仍然以为自己走得太远的人。' },
    { id: 14, key: 'anton', name: '安宁', gender: 'м', theme: '无家可归,海洛因成瘾', softTheme: "街头与毒瘾", color: '#3939c6',
      closingVerse: '"我们不致消灭，是出于耶和华诸般的慈爱；是因他的怜悯不致断绝。每早晨，这都是新的；你的诚实极其广大！"（耶利米哀歌 3:22-23）',
      closingPrayer: '主啊，瘾症夺走了很多，却夺不走你的信实——它每天早晨都是新的，即使是糟糕的一天之后。求你赐我今天，一天一天地过，不要让我忘记，即使在最低谷你也在。' },
    { id: 15, key: 'pavel', name: '博文', gender: 'м', theme: '临床死亡与神迹医治', softTheme: "死亡与神迹", color: '#e9b74a',
      closingVerse: '"我必不致死，仍要存活，并要传扬耶和华的作为。"（诗篇 118:17）',
      closingPrayer: '主啊，你把生命还给我是有原因的。谢谢你多给我一天——又一天，再一天。求你帮助我不要浪费这段时间，而是去述说你所做的事。' },
    { id: 16, key: 'yulia', name: '雨薇', gender: 'ж', theme: '在封闭宗教团体中长大,离开后重建信仰', softTheme: "信仰的重建", color: '#3ac66b',
      closingVerse: '"你们寻求我，若专心寻求我，就必寻见。"（耶利米书 29:13）',
      closingPrayer: '主啊，我不得不拆开别人给我的信仰，重新建立属于我自己的、真实的信仰。谢谢你没有和那些原来是虚假的东西一起消失。求你帮助我信靠你，而不是那个曾以你的名义说话的体系。' },
    { id: 17, key: 'oksana', name: '慧珊', gender: 'ж', theme: '战场创伤后应激障碍,酗酒,服侍其他老兵', softTheme: "战争与疗愈之路", color: '#48ca87',
      closingVerse: '"他医好伤心的人，裹好他们的伤处。"（诗篇 147:3）',
      closingPrayer: '主啊，战争在我心里留下了外表看不见的东西。谢谢你不惧怕我所见过的，也没有转身离开我的痛苦。愿我的医治成为其他和我一起经历过同样事情的人的支持。' },
    { id: 18, key: 'vika', name: '薇琪', gender: 'ж', theme: '家庭暴力,信仰成为尊严之路', softTheme: "伤害与找回的尊严", color: '#de2458',
      closingVerse: '"神就照着自己的形像造人。"（创世记 1:27）',
      closingPrayer: '主啊，曾有人试图让我相信自己一文不值。谢谢你从一开始就用不同的眼光看我——按你的形像所造，带着谁也夺不走的尊严。求你帮助我带着这份认识去生活。' },
    { id: 19, key: 'tanya', name: '婷雅', gender: 'ж', theme: '双相情感障碍伴发精神病,信仰与治疗并行', softTheme: "心灵的风暴,信仰相伴", color: '#b862d2',
      closingVerse: '"我的恩典够你用的，因为我的能力是在人的软弱上显得完全。所以，我更喜欢夸自己的软弱……"（哥林多后书 12:9）',
      closingPrayer: '主啊，在我心智失控的日子里你在，在治疗帮助我重新站起来的日子里你也在。谢谢你赐下医生、药物，也谢谢你的同在——这一切都在一起，而不是彼此替代。求你在艰难的日子里赐我对自己多一点耐心。' },
    { id: 20, key: 'galya', name: '佳丽', gender: 'ж', theme: '破产与贫困,在财务上信靠神', softTheme: "贫困与信靠", color: '#c69139',
      closingVerse: '"你们看那天上的飞鸟，也不种，也不收……你们的天父尚且养活他。你们不比飞鸟贵重得多吗？"（马太福音 6:26）',
      closingPrayer: '主啊，当一切都失去时，我曾害怕你也会随着一切离开。谢谢你没有那样做。求你帮助我把仅剩的、还有那些没有的，都交托给你。' },
    { id: 21, key: 'denis', name: '德明', gender: 'м', theme: '激进民族主义者,通过一位黑人牧师归信', softTheme: "穿越仇恨之路", color: '#644f4f',
      closingVerse: '"人若说我爱神，却恨他的弟兄，就是说谎话的。"（约翰一书 4:20）',
      closingPrayer: '主啊，求你赦免我在你清理之前心里所充满的那些东西。谢谢那位按我曾被教导的一切我本该憎恨、却反而向我显明你的人。求你不要让我回到你把我带出来的地方。' },
    { id: 22, key: 'ignat', name: '一鸣', gender: 'м', theme: '在信仰被禁止的国家秘密牧养教会,身陷囹圄', softTheme: "被禁的信仰", color: '#d12e79',
      closingVerse: '"顺从神，不顺从人，是应当的。"（使徒行传 5:29）',
      closingPrayer: '主啊，你知道我为了在信仰被禁止的地方谈论你付上了怎样的代价。求你让我继续忠心，即使在监狱里，即使在沉默中——你听得见，即使没有人再听见。' },
    { id: 23, key: 'artem', name: '子轩', gender: 'м', theme: '生意崩溃后破产,信仰与财务重建', softTheme: "崩溃与重建", color: '#39c691',
      closingVerse: '"那些年所吃的，我要补还你们。"（约珥书 2:25）',
      closingPrayer: '主啊，当我一生建立的事业崩塌时，我不知道那废墟的另一边是否还有什么。谢谢你不以我失去的来衡量我的价值。求你教导我重新建造，让我的根基立在你身上，而不是那些可能再次失去的东西上。' },
    { id: 24, key: 'grisha', name: '国华', gender: 'м', theme: '少年杀人案,入狱,后成为监狱牧师', softTheme: "监狱与服侍之路", color: '#c66c39',
      closingVerse: '"神啊，求你为我造清洁的心，使我里面重新有正直的灵。"（诗篇 51:10）',
      closingPrayer: '主啊，我少年时所做的事无法挽回——我也不求那个。我求的是你应许要重新创造的那颗心。愿我在铁窗内的生命，成为对那些和我曾经一样的人的服侍。' },
    { id: 25, key: 'stas', name: '思远', gender: 'м', theme: '离婚,通过信仰重建为人父的身份', softTheme: "离婚与回归家庭之路", color: '#395fc6',
      closingVerse: '"你们作父亲的，不要惹儿女的气，只要照着主的教训和警戒养育他们。"（以弗所书 6:4）',
      closingPrayer: '主啊，离婚夺走了我很多，却没有夺走我做父亲的权利。求你帮助我一步一步重建可以重建的部分，成为一个用爱而不是缺席来引导孩子的父亲。' },
    { id: 26, key: 'zhenya', name: '珍怡', gender: 'ж', theme: '饮食失调,通过信仰得医治', softTheme: "身体、心灵与医治", color: '#d36973',
      closingVerse: '"我要称谢你，因我受造，奇妙可畏。"（诗篇 139:14）',
      closingPrayer: '主啊，很长一段时间，我都在与你所造的这个身体争战。求你帮助我像你看我那样看自己——不是一个需要修理的项目，而是你称之为奇妙的作品。求你带领我一步一步走向医治，不要让我孤单一人。' },
    { id: 27, key: 'inna', name: '音妍', gender: 'ж', theme: '流产与不孕,在悲伤中信靠神', softTheme: "失去与信靠", color: '#56a5ce',
      closingVerse: '"我几次流离，你都记数；求你把我眼泪装在你的皮袋里。"（诗篇 56:8）',
      closingPrayer: '主啊，你知道我为那些我没能留住的孩子哭过多少次。谢谢你，没有一滴眼泪被你忽略。求你帮助我把不明白的事交托给你。' },
    { id: 28, key: 'karina', name: '凯琳', gender: 'ж', theme: '性产业,通过不带定罪的事工离开', softTheme: "不被定罪的路", color: '#c63a6b',
      closingVerse: '"我也不定你的罪。去吧，从此不要再犯罪了！"（约翰福音 8:11）',
      closingPrayer: '主啊，谢谢那些没有转身离开我、只是在我寻找回家的路时静静陪伴、不加论断的人。求你帮助我也成为别人这样一个安全的地方。' },
    { id: 29, key: 'darya', name: '黛雅', gender: 'ж', theme: '巅峰时期的运动员,隐藏的羞耻与空虚', softTheme: "荣耀与隐藏的空虚", color: '#7bc639',
      closingVerse: '"人就是赚得全世界，赔上自己的生命，有什么益处呢？"（马可福音 8:36）',
      closingPrayer: '主啊，我拥有别人梦寐以求的一切，内心却依然空虚。谢谢你没有满足于我的成就——你要的是我这个人。求你填满那奖牌和掌声都填不满的地方。' },
    { id: 30, key: 'milana', name: '明兰', gender: 'ж', theme: '癌症诊断,尽管恐惧仍有平安', softTheme: "疾病与内心的平安", color: '#c75538',
      closingVerse: '"我留下平安给你们；我将我的平安赐给你们……你们心里不要忧愁，也不要胆怯。"（约翰福音 14:27）',
      closingPrayer: '主啊，诊断结果没有给我任何保证，但你的平安不依赖保证。谢谢你的平安在等待结果最可怕的日子里也与我同在。求你与每一个像我一样此刻正害怕、正等待结果的人同在。' },
    { id: 31, key: 'egor', name: '家豪', gender: 'м', theme: '巅峰时期的运动员,成功背后的空虚', softTheme: "荣耀与空虚", color: '#3982c6',
      closingVerse: '"后来我察看我手所经营的一切事和我劳碌所成的功……都是虚空，都是捕风，在日光之下毫无益处。"（传道书 2:11）',
      closingPrayer: '主啊，我得到了本该让我快乐的一切，却站在顶峰空虚不堪。谢谢你在为时太晚之前让我看清这一点。求你帮助我去寻求真正能填满我的东西。' },
    { id: 32, key: 'vadim', name: '卫东', gender: 'м', theme: '死刑判决,处决前的悔改', softTheme: "判决与悔改", color: '#c63939',
      closingVerse: '"耶稣对他说：我实在告诉你，今日你要同我在乐园里了。"（路加福音 23:43）',
      closingPrayer: '主啊，你在十字架上，在那罪犯最后的时刻饶恕了他——所以也有饶恕为我存留。谢谢你在我的时间用尽之前给我悔改的机会。求你接纳我现在的样子，而不是我曾经的样子。' },
    { id: 33, key: 'kostya', name: '康泰', gender: 'м', theme: '生来失明,音乐与信仰', softTheme: "黑暗中的音乐", color: '#8748ca',
      closingVerse: '"有一件事我知道：从前我是瞎眼的，如今能看见了。"（约翰福音 9:25）',
      closingPrayer: '主啊，我的眼睛从未见过光——但我用我整个生命听见你、感受你，就像福音书里那个不靠眼睛就认出你的瞎子一样。谢谢你赐给我音乐，让我能借着它向那些看得见却没有留意的人述说你。愿我的黑暗成为一个地方，让人从那里更清楚地看见你的光。' },
    { id: 34, key: 'marat', name: '睿智', gender: 'м', theme: '有组织犯罪,不惜一切代价脱离', softTheme: "脱离犯罪之路", color: '#3939c6',
      closingVerse: '"他从高天伸手抓住我，把我从大水中拉上来。"（诗篇 18:16）',
      closingPrayer: '主啊，脱离那条路几乎让我付上了所有代价。谢谢你把我从一个看似没有出路的地方拉出来。求你在这条新路上保护我，也保护我所爱的人——你知道这一切我付上了什么代价。' },
    { id: 35, key: 'yuriy', name: '宇轩', gender: 'м', theme: '战争难民,在失去一切中持守信仰', softTheme: "失去一切,仍有信仰", color: '#7dc639',
      closingVerse: '"虽然无花果树不发旺……然而，我要因耶和华欢欣，因救我的神喜乐。"（哈巴谷书 3:17-18）',
      closingPrayer: '主啊，我失去了家园、土地，失去了熟悉的生活——但没有失去你。谢谢你即使在我一无所有的地方，也与我同行。求你帮助我在你带领我到的地方重新扎根。' },
    { id: 36, key: 'olya', name: '丽雅', gender: 'ж', theme: '受伤后瘫痪,静止中的信仰', softTheme: "静止中的信仰", color: '#63d29b',
      closingVerse: '"你们要休息，要知道我是神！"（诗篇 46:10）',
      closingPrayer: '主啊，一个曾经不假思索就能行动的身体，如今静止了，我的信心也不得不重新学习站立。谢谢你不要求我用行动来证明你的同在。求你教导我在这从未选择过的静止中寻见你。' },
    { id: 37, key: 'natasha', name: '曼婷', gender: 'ж', theme: '守寡,悲伤与作为祷告的日记', softTheme: "守寡与追忆", color: '#ca4887',
      closingVerse: '"耶和华保护寄居的，扶持孤儿和寡妇……"（诗篇 146:9）',
      closingPrayer: '主啊，早在我成为寡妇之前，你就自称是寡妇的保护者。谢谢你，我写给你的日记的每一页都被你听见了。求你在家中寂静最响的那些夜晚与我同在。' },
    { id: 38, key: 'lena', name: '雅蕾', gender: 'ж', theme: '少女怀孕,选择生命', softTheme: "青春与艰难的抉择", color: '#cdb754',
      closingVerse: '"我的肺腑是你所造的；我在母腹中，你已覆庇我。"（诗篇 139:13）',
      closingPrayer: '主啊，我完全没有准备好去做那个太早就必须做的决定。谢谢你在最深的恐惧中与我同在，没有转身离开一个害怕的孩子。求你赐我智慧，去养育我选择保护的生命。' },
    { id: 39, key: 'vera', name: '信慧', gender: 'ж', theme: '照顾患痴呆症的母亲,不被认出的爱', softTheme: "不被认出的爱", color: '#567dce',
      closingVerse: '"凡事包容……爱是永不止息。"（哥林多前书 13:7-8）',
      closingPrayer: '主啊，母亲已经不再认得我，但我仍然坚持来看她。谢谢你，我的爱不取决于是否被认出——正如你对我的爱也不取决于我是否每天都记得。求你赐我力量再多守护一天。' },
    { id: 40, key: 'alya', name: '雅欣', gender: 'ж', theme: '知名歌手,成功面具下的恐慌', softTheme: "成功背后的焦虑", color: '#c7388e',
      closingVerse: '"应当一无挂虑，只要凡事借着祷告、祈求，和感谢，将你们所要的告诉神……神所赐、出人意外的平安，必在基督耶稣里保守你们的心怀意念。"（腓立比书 4:6-7）',
      closingPrayer: '主啊，后台没有人看得见我的心跳得多厉害。谢谢你不需要我在真正害怕的时候还要微笑。求你赐我你的平安——那种不依赖掌声、也不会在灯光熄灭时消失的平安。' },
    { id: 41, key: 'nina', name: '念慈', gender: 'ж', theme: '隐形的慢性疾病,没有医治的祷告', softTheme: "没有医治的疾病", color: '#48a9ca',
      closingVerse: '"所以，我们不丧胆。外体虽然毁坏，内心却一天新似一天。"（哥林多后书 4:16）',
      closingPrayer: '主啊，我祈求多年的医治至今仍未来到，我不会假装那容易接受。谢谢你即使在祷告的答案不是我所盼望的时候，仍然与我同在。求你更新我的内心，即使身体已经疲惫。' },
    { id: 42, key: 'lyuda', name: '丽蓉', gender: 'ж', theme: '自闭症孩子的母亲,在众目睽睽下的接纳', softTheme: "众目睽睽下的母爱", color: '#c6973a',
      closingVerse: '"他必像牧人牧养自己的羊群，用膀臂聚集羊羔抱在怀中。"（以赛亚书 40:11）',
      closingPrayer: '主啊，商店里陌生人的目光，不知道我和我的孩子每天要付上什么代价。谢谢你不像人那样论断，也谢谢你像牧人抱着羊羔一样把我们俩都抱在怀中。求你赐我在人前人后都有的耐心。' },
    { id: 43, key: 'andrey', name: '志强', gender: 'м', theme: '地下基督徒研经小组,为信仰所付的劳改营代价', softTheme: "为信仰付出的劳改营", color: '#75c639',
      closingVerse: '"是高处的，是低处的，是别的受造之物，都不能叫我们与神的爱隔绝；这爱是在我们的主基督耶稣里的。"（罗马书 8:38-39）',
      closingPrayer: '主啊，他们因为我信你而夺走了我生命中的许多年，却夺不走信仰本身。谢谢你，即使隔着铁丝网，你的爱依然临到我。愿我的故事提醒人：信仰的代价可能很高——而你，是值得的。' },
    { id: 44, key: 'gleb', name: '立群', gender: 'м', theme: '摇滚音乐人,名声与毒瘾', softTheme: "名声与毒瘾", color: '#c6397b',
      closingVerse: '"他从祸坑里，从淤泥中，把我拉上来，使我的脚立在磐石上……他使我口唱新歌。"（诗篇 40:2-3）',
      closingPrayer: '主啊，舞台给了我瘾症，而不是它所许诺的自由。谢谢你把我从自己挖的坑里拉了出来。求你赐我一首新歌——不是为了掌声，而是为了你。' },
    { id: 45, key: 'oleg', name: '皓然', gender: 'м', theme: '三十年婚姻后的丧偶', softTheme: "长久爱情后的丧偶", color: '#32accd',
      closingVerse: '"我虽然行过死荫的幽谷，也不怕遭害，因为你与我同在。"（诗篇 23:4）',
      closingPrayer: '主啊，我们并肩走过三十年，如今我独自前行。谢谢你没有把我留在这幽谷之中。求你帮助我为我们共有的岁月感谢你，即使它们的结束让我心痛。' },
    { id: 46, key: 'kirill', name: '启瑞', gender: 'м', theme: '成功的企业高管,隐藏的酗酒问题', softTheme: "成功背后的挣扎", color: '#683ac6',
      closingVerse: '"神啊，我的心切慕你，如鹿切慕溪水。我的心渴想神，就是永生神。"（诗篇 42:1-2）',
      closingPrayer: '主啊，表面上一切都很成功，内心却在我连最亲近的人都隐瞒的事上快要溺毙。谢谢你看见职位和地位背后真实的我。求你满足那我曾试图用错误方式浇灭的渴望。' },
    { id: 47, key: 'vlad', name: '伟诚', gender: 'м', theme: '冤案入狱,后被平反', softTheme: "冤屈与平反", color: '#c67539',
      closingVerse: '"当将你的事交托耶和华，并倚靠他，他就必成全。他要使你的公义如光发出，使你的公理明如正午。"（诗篇 37:5-6）',
      closingPrayer: '主啊，在人们相信关于我的谎言的那段时间里，你一直知道真相。谢谢你把真相带到光中——即使不如我期望的那么快。求你帮助我不要为那些被不公平夺走的岁月怀恨在心。' },
    { id: 48, key: 'kolya', name: '承恩', gender: 'м', theme: '唯物主义科学家,诚实地探究信仰', softTheme: "科学与诚实的探寻", color: '#1ca0e3',
      closingVerse: '"诸天述说神的荣耀，穹苍传扬他的手段。"（诗篇 19:1）',
      closingPrayer: '主啊，我寻求你的方式，和我寻求其他一切事物的方式一样——诚实、查验、发问。谢谢你经得起最严格的检验。求你帮助我在如今相信之后，仍不失去这份诚实。' },
    { id: 49, key: 'bogdan', name: '天赐', gender: 'м', theme: '被武装团伙劫持的人质,囚禁中的信仰', softTheme: "囚禁中的信仰", color: '#c66839',
      closingVerse: '"他要求告我，我就应允他；他在急难中，我要与他同在；我要搭救他，使他尊贵。"（诗篇 91:15）',
      closingPrayer: '主啊，被囚禁时我不知道自己是否还能再见到自由的一天，但我知道即使在那里你也与我同在。谢谢你按你所应许的那样，在急难中与我同在。求你帮助我永远不要忘记，是谁在我什么都握不住的时候托住了我。' },
  ];

  const STORIES = {
    sonya: {
      start: 'sonya_intro',
      scenes: {
        sonya_intro: { text: '索尼娅本不该活下来,而是应该死去——这是当初的安排。怀孕七个半月时,医生向子宫注入了盐水溶液:目的是从体内和体外烧伤胎儿,并在一天之内引产出一具死婴。但那天早上值班的医生还没到岗。索尼娅活着降生了——带着本不该有任何生命能挺过的烧伤——并且完全靠自己完成了第一次呼吸。', next: 'sonya_childhood' },
        sonya_childhood: { text: '索尼娅最初的几个月辗转于不同的临时收容所,直到一位名叫塔玛拉的女人收养了她——她并不富裕,但信仰坚定。人们告诉塔玛拉:这个女孩十七个月大时体重只有十四公斤的"死重",很可能永远无法独自行走——脑瘫,是出生前那几个小时缺氧造成的脑损伤。"她这辈子不会有出息了,"人们这样警告塔玛拉。她的回应只是每天三次陪女孩练习,风雨无阻。三岁半时,索尼娅迈出了第一步——靠着助行器和腿部支具,但完全是自己走的。', next: 'sonya_choice1' },
        sonya_choice1: { text: '十四岁那年,索尼娅去厨房倒水时,在门口愣住了:大人们正在谈论她,没注意到她就站在旁边。"她本来应该死的,"有人平淡地说,像是在谈论天气。那天晚上,索尼娅辗转难眠,第一次把一切拼在了一起:那些从未被真正解释过的伤疤、跛行、每天三次和塔玛拉的训练——这一切的起点不是疾病,也不是意外,而是别人替她做出的一个决定。', choices: [
          { label: '接受这是上帝计划的一部分,并公开谈论它', effects: { faith: 10 }, next: 'sonya_bridgeA' },
          { label: '把这一切深埋心底,谁也不告诉', effects: { faith: -10 }, next: 'sonya_bridgeB' },
        ] },
        sonya_bridgeA: { text: '索尼娅开始讲述自己的出生经历——先是在教会团契里,声音颤抖得所有人都能听见,后来是在青年聚会上,再后来是在挤满陌生人的大厅里。每一次她都真切地感到恐惧。但每一次讲完之后,那份曾经默默背负的重担都变得轻一些。几年后,她的生母找到了她——迷茫、苍老,艰难地组织着语言,仿佛已经把这次见面演练了上百遍,却还是不知从何说起。', next: 'sonya_choice2' },
        sonya_bridgeB: { text: '索尼娅学会了用一种笑容让人不再追问——学会了一旦话题触及童年或腿上的伤疤就巧妙转移。她把这部分自己藏得如此小心,几乎让自己都相信它并不存在。多年后,当生母找到她时,索尼娅感受到的不是解脱,而是一阵尖锐的恐慌——仿佛有人在她背后挖出了她藏了太久的秘密。', next: 'sonya_choice2' },
        sonya_choice2: { text: '母亲站在她面前——比索尼娅想象中要矮小,双手微微颤抖——轻声说:"你好。我是你的母亲。"她们之间隔着三十多年,和一个谁都没有选择的决定。她必须马上决定,就站在门口,该如何面对这句话。', choices: [
          { label: '无论多难都选择原谅并放下', effects: { faith: 15 }, next: 'sonya_endLight' },
          { label: '转身离开,什么都不想听', effects: { faith: -15 }, next: 'sonya_endDark' },
        ] },
        sonya_endLight: { text: '索尼娅原谅了——不是因为这很容易,也不是因为母亲做了什么特别值得被原谅的事,而是因为她决定不再用余生背负别人的愧疚。如今她走访收容困难青少年的机构,告诉他们那些曾经没人对她说过的话:即使曾经有人做出过相反的决定,他们的生命也不是一个错误。索尼娅的故事到此结束。', next: null, choices: [] },
        sonya_endDark: { text: '那天索尼娅头也不回地离开了,再也没有接听过那个号码打来的电话。多年后,她在别人家孩子的游乐场上听到"妈妈"这个词时仍会一惊,并且和任何试图靠近她的人保持着距离——安全,却彻底孤独,那个未说出口的问题始终没有答案。索尼娅的故事到此结束。', next: null, choices: [] },
      },
    },
    nastya: {
      start: 'nastya_intro',
      scenes: {
        nastya_intro: { text: '静雯在一个小镇长大,那里的一切都简单而温馨:周日的礼拜,热闹的家庭聚餐,一个认识每个邻居名字的父亲。当针对某个族群的屠杀席卷全国时,这一切在一周之内化为乌有,这场屠杀在随后一百天里造成这个国家超过一百万人丧生,静雯的父母和两个兄弟都死于其中,只有一位在国外求学的兄弟幸存。一位本地牧师——正是当年每周日在她儿时教堂讲道的那位——把静雯和另外七名妇女藏进了自己家中衣柜后面一个狭小的空间——那里曾经用来存放床上用品,如今挤着八个人,只要没人呼吸太深、没人动弹。', next: 'nastya_scene2' },
        nastya_scene2: { text: '静雯在那个小房间里度过了九十一天,隔着墙能听到那些搜捕她和像她一样的人的声音——有时近在咫尺,有一次甚至就在衣柜的另一侧。女人们学会了即使睡着也不发出声音,靠牧师一家冒着生命危险偷偷送来的少量食物维生。她躲进去时还是体重超过五十公斤的健康女生,三个月后出来时体重只剩不到一半,她不再数日子,而是反复默念那些从零碎消息中得知一个接一个被杀害的亲人的名字。', next: 'nastya_choice1' },
        nastya_choice1: { text: '屠杀开始前,父亲只来得及叮嘱她一句话:无论发生什么都要念玫瑰经,而这句嘱托后来支撑她度过了整整九十一天。躲藏的第三周,静雯发现自己无法说出那句从小背到大的祷文——"饶恕我们,如同我们饶恕人"——她心里除了对外面杀人者的仇恨,只剩下对这仇恨本身的羞耻。', choices: [
          { label: '继续祷告,即使毫无感觉', effects: { faith: 10 }, next: 'nastya_bridgeA' },
          { label: '停止祷告,只靠仇恨支撑', effects: { faith: -10 }, next: 'nastya_bridgeB' },
        ] },
        nastya_bridgeA: { text: '静雯一口气念完十五端玫瑰经,有时一天重复多达二十七遍,数到自己都数不清——正是在这令人疲惫的重复中,而不是某个灵光乍现的瞬间,她渐渐重新感受到上帝仍与她同在,而不只是手中的念珠。借着烛光读一段不知怎么留在这间小屋里的福音书残页时,她忽然明白:饶恕不是一种自然而来的感觉,而是一个必须每天早晨重新做出的决定。当屠杀结束,女人们终于走到光亮之下时,静雯几乎已没有家人——只剩一栋空房子和一份再也无人可以传承的名单。', next: 'nastya_choice2' },
        nastya_bridgeB: { text: '仇恨支撑着静雯,让她在饥饿、恐惧、绝望本该击垮她的时候仍能站立,尽管牧师一家仍冒险每天送来食物。当屠杀结束时,她几乎已没有家人,心里只剩下那种她误以为是坚强的冰冷、坚硬的感觉。', next: 'nastya_choice2' },
        nastya_choice2: { text: '两年后,静雯在集市上遇见一个她确信曾在她所在街区杀过人的男人——她凭着他眉毛上方的疤痕认出了他,那道疤痕是她当年透过衣柜缝隙深深印在记忆里的。他也认出了她,手里提着一篮蔬菜僵在原地,仿佛这只是集市上普普通通的一天。', choices: [
          { label: '走上前告诉他自己原谅他', effects: { faith: 15 }, next: 'nastya_endLight' },
          { label: '从他身边走过,盼望他有一天也会付出代价', effects: { faith: -15 }, next: 'nastya_endDark' },
        ] },
        nastya_endLight: { text: '静雯走上前说出了饶恕的话,尽管每说一个字喉咙都在收紧,双手抖得她不得不背在身后握紧。这并没有让她的家人复生,也没有抹去那黑暗中的九十一天,但它夺走了仇恨对她自己人生的掌控权。如今她在世界各地讲述这个故事——不是为了被怜悯,而是希望还有人能在自己身上找到同样的力量。静雯的故事到此结束。', next: null, choices: [] },
        nastya_endDark: { text: '静雯一言不发地从他身边走过,拳头里紧紧攥着这些年一直背负的仇恨。她的身体活了下来,但有时半夜醒来,她仍能听见衣柜后面的声音——她知道自己从未真正走出那间小屋。静雯的故事到此结束。', next: null, choices: [] },
      },
    },
    liza: {
      start: 'liza_intro',
      scenes: {
        liza_intro: { text: '从十三岁起,丽华就去看一位全家和整个俱乐部都信任的运动医生——那是一个有名望、办公室墙上挂满奖状、排队等着把孩子送来的家长络绎不绝的男人。在医疗的名义下,他在多次诊疗中一次又一次地对她进行性侵犯,而她始终沉默,因为她不相信有人会相信她而不是他。', next: 'liza_scene2' },
        liza_scene2: { text: '多年后,丽华结束了运动生涯,结了婚,生了孩子——表面上是普通而幸福的生活。但夜里,同样的办公室灯光总在她梦中出现,她发现自己无法再看曾经参与的那项运动的转播。她只对丈夫提起过,声音低得像耳语,而且是在婚后很多年——即便如此,也没有说出全部。', next: 'liza_choice1' },
        liza_choice1: { text: '十六年过去了。一天深夜,丈夫已经睡下,丽华在浏览新闻时看到一篇文章,讲的是其他女孩曾遭受同一个男人相同的伤害——细节几乎和她从未向任何人完整讲过的经历一字不差。她明白了:要么永远沉默,要么第一个用自己的真名把这一切说出来。等到案件开庭时,已有一百五十多名女性站出来讲述同一个男人对她们做过的同样的事。', choices: [
          { label: '公开举报,即使会毁掉她与团契的关系', effects: { faith: 10 }, next: 'liza_bridgeA' },
          { label: '保持沉默,假装什么都没发生过', effects: { faith: -10 }, next: 'liza_bridgeB' },
        ] },
        liza_bridgeA: { text: '丽华用真名第一个提出了举报,明知一旦公开就再无退路——她当年出于完全不同的原因获得的法律学位,如今意外地帮助她自己厘清了案件的细节。部分团契成员因此疏远了她,称这是对一个如此受人尊敬之人的背叛。但她仍在孩子们睡下后的夜里继续准备庭审陈词,告诉自己正义与饶恕并不互相排斥——在她举报后的几周内,鼓起勇气跟随她发声的其他女性人数已经数以十计。', next: 'liza_choice2' },
        liza_bridgeB: { text: '丽华继续像从前一样生活,在团契聚会上微笑,内心却藏着一份随着岁月只增不减的重担。她在新闻里看到他又获得了一个奖项,每一次都感觉自己在自家客厅里喘不过气来——其实早在过去二十年里,已有其他人私下举报过他,但所在机构始终没有采取任何行动。几年后,其他女性终究还是自己站出来说了这件事,没有等她。', next: 'liza_choice2' },
        liza_choice2: { text: '这件案子最终走上法庭——无论是因为她自己的举报,还是因为其他鼓起勇气替她发声的女性——丽华被传唤出庭作证。她几个月前第一个站出来举报,如今却排在证人名单的最后一位,在长达七天的受害者证词中,一百五十多名女性接连站到同一间法庭、同一支话筒前之后,才轮到她。整个法庭——记者、昔日队友、被告本人——都注视着她,等着她说什么。', choices: [
          { label: '既谈正义,也谈她在上帝面前原谅了他', effects: { faith: 15 }, next: 'liza_endLight' },
          { label: '只说她希望他也尝尝她曾经受过的苦', effects: { faith: -15 }, next: 'liza_endDark' },
        ] },
        liza_endLight: { text: '丽华说出的话让整个法庭都感到意外:她要求依法从重处理——同时,在同一口气里,直视着他的眼睛说:"我祈求你承受那种令人窒息的罪疚重担,好让你有一天真正悔改,得到上帝真正的赦免——你需要的是那份赦免,远胜过我的原谅,尽管我也把它给你。"这并没有立刻减轻痛苦,也没有还给她那些被夺走的岁月,但它夺走了过去决定她将成为什么样的人的权力。丽华的故事到此结束。', next: null, choices: [] },
        liza_endDark: { text: '丽华得到了她想要的、依法从重的判决,但她走出法庭时的那股愤怒始终没有放过她。多年后,她仍会在夜里带着宣判那天同样的感觉醒来——胜利远比她想象的要孤独得多,那份她原本准备好在庭上说出的宽恕的话,始终没能说出口。丽华的故事到此结束。', next: null, choices: [] },
      },
    },
    timur: {
      start: 'timur_intro',
      scenes: {
        timur_intro: { text: '十六岁时,天宇已经统领着片区里最危险的帮派之一——人们远远看见他就会绕道走,而这种权力感是唯一能压过他十二岁离家出走时那个家的记忆的东西。对他而言,唯一的法则是暴力,唯一的家人是那些纹着同样纹身的人。', next: 'timur_scene2' },
        timur_scene2: { text: '天宇早就数不清自己参与过多少场斗殴,又把多少人送进了医院。夜里,帮派散去之后,只剩下空荡荡的院子和一片再也无需向谁证明实力的寂静——在这寂静中,有时会涌上一种真实的恐惧,尽管天宇绝不会大声承认这一点。', next: 'timur_choice1' },
        timur_choice1: { text: '有一天,一个陌生的传道人出现在片区里——没有保镖,没有恐惧,仿佛完全不知道自己闯进了什么地方——他当面对天宇说,他觉得上帝亲自把他派到了这个街角,派给这个帮派,而不是城里别的地方。他还说,上帝爱天宇,无论他做什么都不会停止爱他。天宇的回应是打了他一拳,用刀抵住他的喉咙,威胁如果他再来就杀了他。传道人没有挣扎,反而轻声说,就算把他切成一千块,每一块都会喊着同一句话:「耶稣爱你」——挨打的整个过程中,他似乎一直在无声地祷告。', choices: [
          { label: '还是去听听这个传道人要说什么', effects: { faith: 10 }, next: 'timur_bridgeA' },
          { label: '召集帮派,搅黄他下一次聚会', effects: { faith: -10 }, next: 'timur_bridgeB' },
        ] },
        timur_bridgeA: { text: '天宇带着一半帮派成员去了下一次聚会——只是为了显示谁才是老大,或许一句话就能搅黄整场聚会。那是七月一个闷热的夜晚,来自全城的数千人挤满了大厅——比天宇以往在同一个地方见过的人都多。但在陌生人中间听着讲道,他忽然感到的不是愤怒,而是多年来第一次为自己做过的一切感到愧疚。他的双脚不由自主地把他带向前方,走向讲台,尽管脑子里在喊他转身回去。', next: 'timur_choice2' },
        timur_bridgeB: { text: '天宇和手下前去搅局,但拥挤的人群和场内的喊声在他还没来得及行动之前就把帮派冲散到了四面八方。闷热的大厅里挤满了汗流浃背的人群,几乎让人无法呼吸。那个炎热的夏天,来自四面八方的数千人每晚涌入这些聚会,正是这股陌生人的浪潮瞬间把天宇和手下冲散。天宇发现自己独自一人,被挤在一群陌生人中间,听着那个他发誓要杀掉的传道人讲道。', next: 'timur_choice2' },
        timur_choice2: { text: '主持聚会的人问在场是否有人愿意此刻就把生命交托给上帝,不必等到明天。天宇站在那里,感到有比他曾参与过的任何街头冲突都更重大的事情正在被决定。', choices: [
          { label: '走上前,彻底改变一切', effects: { faith: 15 }, next: 'timur_endLight' },
          { label: '转身回到街头', effects: { faith: -15 }, next: 'timur_endDark' },
        ] },
        timur_endLight: { text: '天宇在陌生人的注视下走上前去。那一夜,他和另一名帮派头目一起把刀交给传道人,换来一本圣经——这个举动成了他与过去生活告别的象征。接下来的三年,他在圣经学院读书,并在那里认识了未来的妻子;回到家乡后,他建立了全国第一所专为问题青少年而设的更生中心,正是那位传道人当初开办的。那一夜,一种生活结束了,另一种开始了——腰间不再别刀,身后不再有帮派,但也不再有那种曾藏在权力背后的孤独。多年后,他写了一本书讲述这段经历,并创办了自己的宣教事工,如今在几十个国家而不仅仅是自己曾经的片区,走向像他当年一样的街头少年,把当年有人对他说过的话,一字不差地讲给他们听。天宇的故事到此结束。', next: null, choices: [] },
        timur_endDark: { text: '天宇转身回到街头,回到同一个院子,同一片比任何帮派都更让他害怕的寂静。他常常想起那个死在他怀里的朋友最后说的话,却始终没有勇气改变自己的人生,那把刀始终别在腰间,没有交给任何人。几年后,他的名字再次出现在新闻里——不再是首领的名字,只是片区案件记录里的又一行,没有一个字提到他本可以成为什么样的人,也没有人再记得那个七月闷热的夜晚。天宇的故事到此结束。', next: null, choices: [] },
      },
    },
    sergey: {
      start: 'sergey_intro',
      scenes: {
        sergey_intro: { text: '战争爆发前,俊杰曾作为全国最有前途的短跑选手之一参加过大型国际赛事。战争降临时他不是在陆地上,而是在天上——一次战斗任务中飞机坠入海洋,机组人员中只有他和另一名同伴幸存。他们在一只小筏子上漂流了四十七天,顶着烈日,徒手与鲨鱼搏斗,靠生鱼和偶尔落下的海鸟充饥,才终于获救——却立刻被俘。在关押他两年多、对他施以折磨的战俘营里,有一个看守被俘虏们私下称作"鸟",专门挑他下手。俊杰回到了家——身体的愈合比心灵更快。等着他的是一个已经认不出眼前这个男人的妻子——她送走的是另一个人,回来的却是这个;还有那些一夜都不曾放过他的噩梦。', next: 'sergey_scene2' },
        sergey_scene2: { text: '白天,俊杰看起来几乎和从前一样——开玩笑,去上班,对邻居微笑。但灯一熄灭,他就又回到了那座营地:同样的看守声音,同样的气味,同样的无助感。他开始比在囚禁中更害怕黑暗,却不曾向任何人坦白,包括他自己。有时深夜醒着,他试着祷告——就像在筏子上许下的承诺那样——可话语总是说不出第一句,仿佛上帝也留在了那只筏子上。', next: 'sergey_choice1' },
        sergey_choice1: { text: '俊杰开始喝酒,只为了能不做那些关于营地的梦睡上一会儿,而每个月他需要的酒量都在增加。一天夜里,他惊醒时发现双手正掐在自己妻子的脖子上——他梦见自己在掐那个他私下称作"鸟"的看守。妻子含着泪默默收拾行李准备离开,一句责备的话都没有说,这比任何叫喊都更令人恐惧。', choices: [
          { label: '恳求她留下,并承诺戒酒', effects: { faith: 0 }, next: 'sergey_bridgeCommon' },
          { label: '一言不发地放她走,认为自己活该孤独', effects: { faith: -5 }, next: 'sergey_bridgeCommon' },
        ] },
        sergey_bridgeCommon: { text: '妻子还是去参加了一场帐篷布道会,与其说出于信仰,不如说出于绝望——回到家时她变了一个人:平静,几乎容光焕发,仿佛终于找到了她多年来寻找的东西。她告诉他,这是她这辈子第一次真正用自己的话祷告,而不是照着念——某种东西在她心里发生了改变。她没有对俊杰提出任何要求,只是邀请他,如果愿意,下次一起去。', choices: [
          { label: '和她一起去听听', effects: { faith: 10 }, next: 'sergey_choice2' },
          { label: '独自留在家里喝酒', effects: { faith: -10 }, next: 'sergey_endDark' },
        ] },
        sergey_choice2: { text: '传道人讲到战争、苦难,以及上帝向人所求的不是力量而是信心——这些简单的话语不知为何触及了多年治疗都未能触及的地方。俊杰忽然想起自己在大洋中央那只筏子上、以为活不到天亮时许下的誓言:"如果你救我,我这辈子都要侍奉你。"一个他许下、却几乎在双脚重新踏上陆地那一刻就忘记的誓言。', choices: [
          { label: '多年来第一次真心祷告,并饶恕折磨他的人', effects: { faith: 15 }, next: 'sergey_endLight' },
          { label: '起身默默走出大厅,还没准备好原谅', effects: { faith: -15 }, next: 'sergey_endDark' },
        ] },
        sergey_endLight: { text: '那天夜里,俊杰多年来第一次没有做噩梦——没有看守的声音,没有气味,没有无助感。他给那个他称作"鸟"的人写了一封信——不是为了替他开脱,而是为了终于卸下一份比囚禁本身还要沉重、背负更久的重担。几年后,他专程飞回曾经关押他的国家,走进关押那些前看守的监狱,当面对每一个人说:我原谅你。妻子留了下来,噩梦再也没有回来。俊杰的故事到此结束。', next: null, choices: [] },
        sergey_endDark: { text: '噩梦始终没有放过俊杰。渐渐地,身边不再有妻子,也没有独自对抗噩梦的力气,看守的声音变得越来越轻——只是因为俊杰已经彻底停止了抗争。那只筏子、那片汪洋、他曾许下又几乎遗忘的誓言,还有那位一直为他祷告的妻子,渐渐都成了他绝口不提的往事。俊杰的故事到此结束。', next: null, choices: [] },
      },
    },
    maksim: {
      start: 'maksim_intro',
      scenes: {
        maksim_intro: { text: '明轩是一位有影响力的政客的得力助手——一名处理竞选和权力斗争中最肮脏事务、从不多问的顾问,曾在小圈子里夸口说,如果需要,他愿意不惜一切代价为自己的靠山铺路。他为自己能做到这一点而自豪。他早就不再问自己强硬的政治手段止于何处、直接的渎职犯罪又从何处开始,因为如果认真去想这个问题,他将无法安睡。记者后来把这句"不惜一切代价铺路"的话到处传播,尽管明轩始终坚称自己的话被断章取义、夸大其词,但那时"为权力不择手段之人"的名声已经牢牢贴在他身上。', next: 'maksim_scene2' },
        maksim_scene2: { text: '事业巅峰时,明轩的办公室与国家高层仅一步之遥,曾经令他畏惧的人如今对他心怀敬意,而他也绝对相信自己参与的那套掩盖机制永远不会曝光。这份自信在一个普通的星期二,随着自己律师的一通电话轰然崩塌。', next: 'maksim_choice1' },
        maksim_choice1: { text: '明轩参与的那套机制暴露的速度比他能想出辩护方案还要快。记者已经把他的名字印上头版,调查一天比一天深入,昔日的合作伙伴一个接一个作证指控他,以自己的自由为代价换取脱身,没有一个人愿意为他扛下责任。', choices: [
          { label: '承认罪行,承担责任', effects: { faith: 10 }, next: 'maksim_bridgeA' },
          { label: '把责任推给下属,坚持到最后', effects: { faith: -10 }, next: 'maksim_bridgeB' },
        ] },
        maksim_bridgeA: { text: '明轩亲自去找了调查人员,承认了部分确实属实的指控——他的律师称这是自杀式的决定。这让他失去了名誉,也让共谋罪名的刑期加重,但多年来第一次卸下了他连自己都不愿承认的重担。那七个多月的牢狱生活,身处其中时感觉比他之前整个跌宕起伏的仕途还要漫长。', next: 'maksim_choice2' },
        maksim_bridgeB: { text: '明轩坚持到底,把责任推给链条中比自己地位低的人,雇佣越来越昂贵的律师。判决还是找上了他——只是如今又多了一个污点:出卖了自己人来自保,却连自己也没能保住。', next: 'maksim_choice2' },
        maksim_choice2: { text: '在监狱里,在一间关着四个人的牢房里,明轩收到了一个包裹,寄件人是他前半生一位老朋友——判决之后他最没想到会听到消息的人。里面是一本破旧的信仰书籍,还有一封手写的短信。开头几页显得沉闷而天真——正是他对这类书的预期。寄书的朋友自己也是不久前才归信,此前同样经历了多年同样冷酷的商界生涯,信中坦承自己过去也觉得这类书幼稚。最让明轩触动的正是讲骄傲的那一章——读起来就像是专门写给他看的。', choices: [
          { label: '把书读完,让自己有所改变', effects: { faith: 15 }, next: 'maksim_endLight' },
          { label: '把书扔在一边,数着日子等待出狱', effects: { faith: -15 }, next: 'maksim_endDark' },
        ] },
        maksim_endLight: { text: '明轩在一个不眠之夜读完了这本书——到天亮时,他已经认不出自己昨天还是的那个人了。出狱后,他没有回到权力场,而是创办了一个囚犯服侍机构,此后几十年间扩展到世界几十个国家——这比他做过的任何交易都更艰难,也更重要。他后来把自己的故事写成一本忏悔录,取名《重生》,正是这本书第一次让千百万读者关注到他祖国监狱高墙之内真正发生的事。明轩的故事到此结束。', next: null, choices: [] },
        maksim_endDark: { text: '明轩服满了刑期,出狱时和多年前踏入权力场时几乎是同一个人——也许更谨慎了一些,对昔日伙伴的怨恨也更深了一些。几年后,他的名字又一次出现在新闻里,这次是一桩新案子,而那本书始终原封未动地放在出租屋的书架上,落满厚厚一层灰尘,书页从未被翻开过一次。明轩的故事到此结束。', next: null, choices: [] },
      },
    },
    kristina: {
      start: 'kristina_intro',
      scenes: {
        kristina_intro: { text: '婉清是一名拥有终身教职的大学讲师,也是她所在城市女同性恋群体中受人尊敬的声音——多年来她的公开专栏塑造了整整一批志同道合读者的观点。她写了一篇言辞犀利的文章,批评一个正逐渐流行的基督教男性运动——她没想到,在成百上千的回复中,有欣喜的也有愤怒的,竟会有一封来自当地一位牧师的信,彻底颠覆了她所相信的一切。她的专长正是酷儿理论,以及用弗洛伊德、马克思和达尔文的视角解读十九世纪文学,而那封信到来前不过两年,她刚拿到同一领域的博士学位便获得了终身教职。', next: 'kristina_scene2' },
        kristina_scene2: { text: '那封信既没有攻击,也没有说教——牧师只是真诚地问她是怎样形成这些观点的,并提议找机会当面聊聊。婉清本打算把它和其他邮件一起扔掉,却不知为何坐下来写了回信——依旧言辞犀利,以为这场通信到此就会结束。', next: 'kristina_choice1' },
        kristina_choice1: { text: '回复只是牧师和他妻子一次简单的晚餐邀请——没有附带任何论点,也没有丝毫想说服她的意图,仿佛他们对这场争论根本不感兴趣。婉清手里拿着邀请函,必须决定是否要去和这些她刚刚在文章里公开嘲讽过其信仰的人共进晚餐。', choices: [
          { label: '出于好奇赴约,尽管这很奇怪', effects: { faith: 10 }, next: 'kristina_bridgeA' },
          { label: '把信扔掉,写一篇言辞犀利的文章', effects: { faith: -10 }, next: 'kristina_bridgeB' },
        ] },
        kristina_bridgeA: { text: '婉清去赴了那次晚餐——然后又一次,又一次,直到这些夜晚在将近两年里变成了一种稳定、不带任何条件的习惯。牧师和他的妻子从未试图说服她——他们只是倾听,并不断邀请她再来,即使婉清故意用尖锐的问题在他们自己的餐桌上挑起争论。出于纯粹的固执,她开始像学者研读原始文献那样自己读圣经——为了将来那篇彻底驳倒他们的文章寻找矛盾之处。', next: 'kristina_choice2' },
        kristina_bridgeB: { text: '婉清没有赴约,而是就这封信为她的读者写了一篇言辞犀利的专栏,收获了不少志同道合者的赞同回应。但牧师信中一句简短、毫无要求的话——"也许我们可以就这样聊聊"——在文章发表后很久仍萦绕在她心头,她瞒着同事,自己第一次在多年后打开了圣经。除了专栏之外,她多年来还在同一个酷儿研究领域发表学术论文,在本市的维权圈子里也是知名人物——她最不愿意的就是为了一个素不相识的牧师的来信,拿这份名声去冒险。', next: 'kristina_choice2' },
        kristina_choice2: { text: '将近两年的阅读之后——无论是在这个分支中共享的餐桌上,还是在另一个分支中独自度过的夜晚里——婉清在一堂课讲到一半时忽然发现,自己已经无法再向学生诚实地捍卫从前的观点了。接受新的观点意味着失去终身教职、失去她二十年来坚定不移的斗士声誉,以及她二十年来称之为自己团体的大部分朋友。', choices: [
          { label: '即使知道代价,仍接受信仰', effects: { faith: 15 }, next: 'kristina_endLight' },
          { label: '把圣经放到一边,回到从前的生活', effects: { faith: -15 }, next: 'kristina_endDark' },
        ] },
        kristina_endLight: { text: '婉清接受了信仰——正如她所担心的那样,她失去了终身教职,也失去了二十年来称之为自己团体的大部分朋友。她后来把这一切称为不是一段优雅的属灵旅程,而是一场"火车出轨"——即使多年后也从未找到更温和的说法——而正是在那之后,她终于得以从零开始建立起真正属于自己的东西。她后来把这段经历写成一本书,毫无保留,包括这个决定让她付出的一切代价。婉清的故事到此结束。', next: null, choices: [] },
        kristina_endDark: { text: '婉清没有读完圣经就把它放到了一边,回到了从前的专栏和从前对自己的笃定。她偶尔仍会给牧师和他的妻子写几封简短的信——只是她自己也无法解释,为什么始终无法彻底斩断这段对她别无所求的、奇怪的友谊。婉清的故事到此结束。', next: null, choices: [] },
      },
    },
    polina: {
      start: 'polina_intro',
      scenes: {
        polina_intro: { text: '十六岁那年,佩琳试图结束自己的生命——这并非一时冲动,而是经过了几个月身边人都毫无察觉的、安静而有条理的绝望。在那晚之前,她只是校队里一个普普通通的啦啦队员,有疼爱她的家人和一大群朋友,而他们之中没有一个人察觉到她内心正在发生什么。她活了下来,却坐上了轮椅:那具她一生唯一能完全支配的身体,这一次同样没有听她的话,让她活了下来,却也瘫痪了。', next: 'polina_scene2' },
        polina_scene2: { text: '住院最初的几周,佩琳几乎不说话——不跟医生说,也不跟每天带着同样无助表情前来的父母说。她盯着天花板,等待疼痛过去,无论是身体上的,还是那另一种把她带到这里的疼痛,但两者都没有离开。医生谨慎地谈起数年的康复治疗,不敢承诺她还能重新行走,佩琳则重新学着使用那双如今只是偶尔听使唤的手。', next: 'polina_choice1' },
        polina_choice1: { text: '在医院一动不动地躺了几周后,佩琳听见同病房的室友——一位刚做完手术的普通老年妇女——每晚睡前都轻声祷告,不是做给谁看,只是一生的习惯。有一天,她被邀请一同祷告,没有丝毫强迫,就像有人递给她一杯水那样自然。', choices: [
          { label: '听着,并有一天试着自己祷告', effects: { faith: 10 }, next: 'polina_bridgeA' },
          { label: '无视它,对这个世界更加愤怒', effects: { faith: -10 }, next: 'polina_bridgeB' },
        ] },
        polina_bridgeA: { text: '佩琳笨拙地开始祷告,不知道该用什么词,只是把痛苦用自己能想到的方式说出来,晚上还断断续续地读经,向每个愿意谈这个话题的人打听关于神的事——以前她对这类问题既没时间也没什么兴趣。很久以来第一次,内心变得稍微安静了一些,尽管身体再也没能像从前那样听使唤,轮椅也从此成了她生活的一部分。那晚过后大约一年,她清醒而不再笨拙地把生命交托给了基督——她说,正是从那时起,她对幸福的整个理解彻底改变了:幸福不再是终将抵达的目标,而是此刻就能拥有的平安,哪怕身体从未完全康复。', next: 'polina_choice2' },
        polina_bridgeB: { text: '佩琳对室友生气,对医生生气,对自己那具拒绝按她计划的方式死去的身体生气。愤怒没有消退——它只是在四面相同的医院墙壁之间,一天天不断累积,而这些年来身边为何没有一个人察觉的问题,始终没有答案。', next: 'polina_choice2' },
        polina_choice2: { text: '出院两年后,已经习惯了轮椅生活的佩琳,受邀在一个州立法委员会前发言,该委员会正在研究青少年危机援助的可及性问题——要求她原原本本地讲出一切,包括她曾企图对自己做什么、以及为什么,面对的是那些有能力为成千上万个十六岁孩子改变真实规则的人。', choices: [
          { label: '同意,原原本本地讲出一切', effects: { faith: 15 }, next: 'polina_endLight' },
          { label: '拒绝——不让任何人知道', effects: { faith: -15 }, next: 'polina_endDark' },
        ] },
        polina_endLight: { text: '佩琳坐着轮椅来到讲台前,毫不修饰地讲出了一切,依次直视每一位议员的眼睛。她的话被记录进了听证会的正式记录,之后一个和她年纪相仿的女孩颤抖着走过来,说自己上周也想过同样的事——听了她的讲述之后改变了主意。后来还有人以她的经历拍了一部纪录片,如今佩琳走遍全国,在青年和立法者的聚会上发言,努力让其他正处于危机中的青少年,像她十六岁时那样,能及时得到帮助。佩琳的故事到此结束。', next: null, choices: [] },
        polina_endDark: { text: '佩琳拒绝在委员会前发言,继续生活,把伤疤藏在衣服下面,把这段经历藏在一贯的沉默之下。听证会在没有她证词的情况下进行,那一年提议的措施最终也没有通过。她有时会在新闻里读到别的州开办的同伴互助项目,里面从未提起过像她这样的故事,她常常想,如果当初自己敢开口,本可以帮到多少和她一样的十六岁女孩。佩琳的故事到此结束。', next: null, choices: [] },
      },
    },
    marina: {
      start: 'marina_intro',
      scenes: {
        marina_intro: { text: '玉梅二十一岁时被拐骗,在人口贩子手中被囚禁了近二十年——挨打、被辗转倒卖、几次拼死逃跑又同样多次被抓回,辗转于不同城市甚至不同国家,由一个又一个"主人"转手带走。她只靠着一个简单的念头支撑,像祷告一样反复默念:总有一天她会再见到自己的孩子——那些在她被带走的那晚留在家中的孩子。贫困山村中饱受匮乏的童年,早在被拐之前就已教会她默默忍受痛苦——这种本领后来在远比她想象更可怕的处境中,苦涩地派上了用场。', next: 'marina_scene2' },
        marina_scene2: { text: '这些年里,玉梅数不清自己经过了多少座城市、多少个国家、多少个"主人"——名字不断变换,恐惧却始终如一。唯一不变的是一张孩子们的照片,她把它缝在自己仅剩的一件衣服的衬里里,只有在深夜最黑暗的时刻才展开它,那时她确信没有人能看见,也没有人能夺走她这最后一样东西。这些年她曾被辗转运送,单程常常超过一整天,每到一个新地方都会发现和自己一样的女性——几十个同样被囚禁在这场人口贩卖噩梦中的人。', next: 'marina_choice1' },
        marina_choice1: { text: '又一次因试图联系家人而遭受残酷惩罚之后,玉梅独自留在一间黑暗的棚屋里,想起了祖母儿时教她的一段祷告——那些简单的话语,她早已觉得属于另一个如今已不可能的人生。', choices: [
          { label: '轻声念出那段祷告,即使不相信会有人听见', effects: { faith: 10 }, next: 'marina_bridgeA' },
          { label: '认定既然上帝允许这一切,那么上帝并不存在', effects: { faith: -10 }, next: 'marina_bridgeB' },
        ] },
        marina_bridgeA: { text: '玉梅开始每晚重复那段祷告——不是因为相信,而是因为除了那些话语和衬里里的照片,她一无所有。渐渐地,祷告成了她唯一能感觉自己是一个有名字的人、而不是一件货物的地方。后来她说,正是这份信仰让她没有彻底崩溃——相信有一天能再见到孩子,有一天能重新做回一个普通、自由的女人。', next: 'marina_choice2' },
        marina_bridgeB: { text: '玉梅停止了祷告,只靠着愤怒和对孩子的思念支撑,把它当作最后的燃料。愤怒给了她继续前行、活下去的力气,但也烧尽了她内心除纯粹生存之外的一切——同情、眼泪,乃至感受愤怒以外任何情绪的能力。这层盔甲一月比一月厚重,而那些关于复仇与生存之外的希望的微光,变得越来越短暂、越来越稀少。', next: 'marina_choice2' },
        marina_choice2: { text: '她的获释几乎是偶然的——是一次突袭行动的结果,而她直到已经被带出去时才知情——一位社工,自己也是一位虔诚的信徒,提出邀请玉梅和她一起去教会。只是试试看,没有人强迫,也不求任何回报。她的自由其实始于一名拒绝伤害她、反而秘密报警的客人——正是这一善举,多年后引发了突袭行动和多名人贩子的落网。', choices: [
          { label: '去,并让自己再次学着信任', effects: { faith: 15 }, next: 'marina_endLight' },
          { label: '拒绝——上一次信任的代价太大了', effects: { faith: -15 }, next: 'marina_endDark' },
        ] },
        marina_endLight: { text: '玉梅去了。那份始于棚屋黑暗中一声耳语的信仰,成了她自由后新生活的支柱——如今她在一条反人口贩卖热线工作,帮助通过电话识别出当年没人在她身上察觉到的那些被囚禁的迹象,还前往学校和警察局教人及早识别这些迹象,并再次拥抱了她那几乎不敢奢望能再见到的、如今已经长大成人的孩子们。后来她在法庭上指证人贩子,尽管因此遭到杀害威胁,她也没有退缩。她还创办了一个帮助性奴役幸存女性的小型基金会,常在那里说一句话:信仰总能让她不倒下,即使已经无处可倒。玉梅的故事到此结束。', next: null, choices: [] },
        marina_endDark: { text: '玉梅拒绝了,独自一人建立起新的生活,再也没有完全信任过任何人,即使是自己已经长大的孩子。她的身体是自由的,但夜里她仍然会把家里所有能锁上的东西都锁上,不只是公寓的门。她始终没有向任何人完整讲述过自己的故事,无论是孩子还是新认识的人,宁愿让往事被埋葬,而不是说出口。玉梅的故事到此结束。', next: null, choices: [] },
      },
    },
    alina: {
      start: 'alina_intro',
      scenes: {
        alina_intro: { text: '安琪在一个信仰家庭长大,父母曾多年担任宣教士,但从十二岁起,她心里就对教会和神有关的一切积攒起一种沉默的怨恨。多年来,安琪辗转于毒品、酒精和街头之间,靠出卖自己换取下一次的毒资——这条路始于十六岁的一场派对,不知不觉间变成了她记忆中唯一的生活,而那份童年的怨恨也只是不断加深。她早已不再相信自己还能拥有别的人生,也数不清有多少次是那些麻木疲惫、漠不关心的医生在医院把她从吸毒过量中救回来。', next: 'alina_scene2' },
        alina_scene2: { text: '冬夜里,安琪有时会想自己还能活多久——不是带着恐惧,而是带着一种早已不再对下一次吸毒之后的事做任何打算的疲惫的漠然。唯一还能让她想起另一种可能人生的,是一张她高中毕业那年的旧照片,她不知为何一直把它揣在外套口袋里——尽管照片里的那个女孩,如今在她看来已经是一个完全陌生的、属于别人命运的人。', next: 'alina_choice1' },
        alina_choice1: { text: '一位街头传道机构的女士不止一次地走近安琪,端着热咖啡,没有一句评判的话——只是像对待一个人那样每周和她聊天,尽管安琪之前对她说过很难听的话。', choices: [
          { label: '同意去传道机构的收容所待哪怕一晚', effects: { faith: 10 }, next: 'alina_bridgeA' },
          { label: '不予理会——她早就听过那些一文不值的承诺', effects: { faith: -10 }, next: 'alina_bridgeB' },
        ] },
        alina_bridgeA: { text: '安琪同意去收容所待一晚,结果一待就是一个月。在收容所里,很久以来第一次,没有人向她索求任何回报——只是提供了一个住处、一份饭菜,以及重新开始的时间,如果她愿意的话。正是收容所里那些从不求任何回报的女性所给予的这份无条件的关怀,安琪后来称之为她第一次真真切切感受到神的爱,而不仅仅是听人说起。最初几周的戒断比她想象中要难得多——戒断反应在夜里一波接一波袭来,好几次她几乎要走回从前的街头。就在那几周里,她发现自己怀孕了,并做出了她一生中也许最艰难的决定——把孩子生下来,交给一个充满爱的家庭收养,而不是像从前那样用同样的一剂毒品解决一切。', next: 'alina_choice2' },
        alina_bridgeB: { text: '安琪没有理会她,当晚就回到了自己熟悉的街头。那份最初一切开始的童年怨恨,对神和教会的怨恨,并没有消失——每一次她转身离开,怨恨反而更深一分。几周后,同一位女士又在同一个街角找到了她,端着同样的热咖啡,对她的拒绝没有一句责备。', next: 'alina_choice2' },
        alina_choice2: { text: '无论是熬过了收容所里最初残酷的戒断几周,还是又一次听到那位送咖啡的女士发出同样的邀请——她在无数次被拒绝后依然没有放弃——安琪都面临一个选择:终于去参加一个小组聚会,在陌生人面前大声讲出自己的故事,还是回到那个没有人会追问、也没有人会评判的地方。', choices: [
          { label: '去,原原本本地讲出一切', effects: { faith: 15 }, next: 'alina_endLight' },
          { label: '回到街头——至少那里不用解释任何事', effects: { faith: -15 }, next: 'alina_endDark' },
        ] },
        alina_endLight: { text: '安琪在一群和她一样的女性面前讲出了自己的故事,多年来第一次没有感到羞耻——只有巨大的释然。戒毒几年后,她考取了护士资格,如今就在当年抢救过她自己的那个医院科室工作,周末则在她曾经站过的同一条街道上,为其他女性煮着同样的热咖啡——手里拿的不是宣传册,而是当年别人曾给予她的那份耐心——她会诚实地告诉每一个人,让她摆脱毒瘾的正是耶稣,而不是意志力,因为那些年她自己根本就没有意志力。她仍然给送去收养的孩子写信,盼着有一天孩子能读到。安琪的故事到此结束。', next: null, choices: [] },
        alina_endDark: { text: '那天晚上,安琪像往常一样回到了街头。端咖啡的那位女士至今仍每周寻找她,虽然一直没有结果,而外套口袋里的那张旧照片早已不知去向。那份最初一切开始的童年怨恨,一直伴随她到最后——而她曾在宣教士父母身上见过的那份爱,她再也没有在别处找到过。安琪的故事到此结束。', next: null, choices: [] },
      },
    },
    zara: {
      start: 'zara_intro',
      scenes: {
        zara_intro: { text: '紫嫣出生在一个有影响力的穆斯林家庭,家族世代守着山脚下一片庞大的祖传庄园,还在欧洲两座首都拥有住宅,亲戚们每年都会过去小住。一切在一年之内崩塌:父母相继去世,婚姻也随之破裂——紫嫣被彻底孤立在仆人和远亲之中,独自留在一座充满陌生人声音、内心一片空虚的巨大宅邸里。', next: 'zara_scene2' },
        zara_scene2: { text: '独自一人后,紫嫣开始以从未有过的方式祷告——用简单、近乎绝望的话语对着房间的空虚说:"如果你真的存在,让我知道你是谁。"她开始反复做一些异常清晰、与寻常梦境不同的梦,当地一位基督徒悄悄给她带来一本圣经,紫嫣每晚阅读,把书藏在枕头下以躲过仆人——在这个国家,这在法律上并不算违法,但在现实中,从伊斯兰教皈依基督教往往会遭到比任何法庭审判都更快、更严厉的惩罚。书中用来称呼上帝的"父"这个词,让她心中泛起一种格外强烈、近乎大胆的感受——她刚刚埋葬了自己的父亲,最没想到自己还能再向谁说出这个字。她不愿只依赖梦境,又同样用心重读自幼能背诵的《古兰经》,在熟悉的经文中寻找答案,回应她每晚对空房间低声发出的同一个问题。', next: 'zara_choice1' },
        zara_choice1: { text: '一位前来庄园探望她的亲戚,偶然注意到床头柜上一本陌生的书,皱着眉头直接问那是什么,为什么紫嫣要读这种东西,而不是《古兰经》。', choices: [
          { label: '说出真相,无论代价是什么', effects: { faith: 10 }, next: 'zara_bridgeA' },
          { label: '撒谎,把一切继续完全保密', effects: { faith: -10 }, next: 'zara_bridgeB' },
        ] },
        zara_bridgeA: { text: '紫嫣就在床边说出了真相,预料到会有一场风波——风波确实没有让她等太久。谣言几周之内就传遍了亲戚和庄园的邻居,一路上还添油加醋地加上了许多根本没有发生过的细节。', next: 'zara_choice2' },
        zara_bridgeB: { text: '紫嫣撒了谎,当场编造说那本书是某位外国客人落下的,继续在夜里偷偷阅读,只要卧室门外地板稍有响动就立刻熄灯。', next: 'zara_choice2' },
        zara_choice2: { text: '无论她是自己坦白了信仰,还是把它小心翼翼地藏在深夜里,有关她信仰的传言终究还是迟早传遍了整个地区,不久后有人在夜里试图纵火烧毁她的房子,幸好只烧毁了门廊,但留下了一个再明白不过的警告。通过一个帮助像她这样的人的基督教慈善机构,紫嫣得到了立即离开这个国家的机会,代价是放弃祖传庄园、欧洲的住宅,以及她一生所熟悉的一切。', choices: [
          { label: '就在那个秋天离开,无论前方等待着什么', effects: { faith: 15 }, next: 'zara_endLight' },
          { label: '留下来——害怕失去唯一的家的心情更强烈', effects: { faith: -15 }, next: 'zara_endDark' },
        ] },
        zara_endLight: { text: '紫嫣只带着一只行李箱远渡重洋,把家族世代成长的房子留在了身后。在新的家园,她把自己的经历写成了一本书,以多种语言售出了数十万册,几十年来一直帮助其他人走过类似的道路。紫嫣的故事到此结束。', next: null, choices: [] },
        zara_endDark: { text: '紫嫣留了下来,选择把自己的信仰深埋心底,深到有时连她自己都怀疑那一切是否真的发生过。房子保住了,但她再也没有在白天打开过圣经,把那个冬天当作仿佛发生在别人身上的一件事,永远留在了记忆里。紫嫣的故事到此结束。', next: null, choices: [] },
      },
    },
    viktor: {
      start: 'viktor_intro',
      scenes: {
        viktor_intro: { text: '伟强负责一家大城市报纸的法律版块,拥有新闻学和法学双学位,他以从不轻信任何未经证据和交叉信源核实的事实为傲——这种不可动摇的怀疑论者名声,对他而言比几乎任何一段关系都更重要。当妻子在婚姻经历几年艰难之后忽然信了教,伟强的第一反应是觉得自己被骗了,仿佛妻子被另一个人偷换掉了,他甚至认真考虑过离婚,后来才决定要用多年来在法庭上盘问证人的同一套方法,轻松用事实证明她错了。', next: 'viktor_scene2' },
        viktor_scene2: { text: '伟强自称是坚定的无神论者,不止一次对同事说自己只相信有至少两个独立信源证实的事实。早已习惯多年从法庭上冷酷罪犯口中套出口供的他,一开始把这当作一次轻松的热身——快速梳理一遍他在记者聚会上听过几十次的、反对复活的种种说法。但每一条他真正认真核实、而不只是凭记忆重复的常见反驳,一遇到严肃的原始资料就站不住脚,这让他远比自己愿意承认的更加恼火。', next: 'viktor_choice1' },
        viktor_choice1: { text: '伟强决定动用自己全部的新闻从业技能,用证据有条不紊、真正地击溃妻子的信仰,而不只是在晚饭时随口打发过去。', choices: [
          { label: '展开一场真正诚实的调查,无论它通向何方', effects: { faith: 10 }, next: 'viktor_bridgeA' },
          { label: '只收集那些早已能证明自己正确的事实', effects: { faith: -10 }, next: 'viktor_bridgeB' },
        ] },
        viktor_bridgeA: { text: '近两年时间里,伟强系统地研究历史文献,采访专家、历史学家、考古学家和法律学者,试图在复活的记载中找出哪怕一个薄弱环节——利用晚上编辑部工作之余的零碎时间,因为他已经无法真正放下这场调查。而他挖得越深、越专业,就越难以按照自己这个行业的标准去驳倒它。作为律师,他首先寻找的是证人撒谎的动机——却怎么也找不到:几乎每一个宣称复活的人,都为这句话付出了监禁、酷刑甚至处死的代价,而在他多年的司法生涯中,他从未见过一个愿意为自己编造的谎言而死的证人。更难解释的是空坟墓:如果尸体还在原处,当局只需把它拿出来示众,就能一劳永逸地终结这个问题——可无论是罗马人还是最有动机这么做的犹太长老,却始终从未这样做过。', next: 'viktor_choice2' },
        viktor_bridgeB: { text: '伟强匆忙拼凑了一份让自己在早餐桌上感到满意的反对意见清单,但一遇到真正花了多年研究这个问题、而不是只会重复陈词滥调的人认真交谈,它就站不住脚了。他坚信多年的职业经验足以让他抄捷径,相信第一个顺手的反驳,甚至懒得用他自己多年来要求手下记者遵守的双独立信源标准去核实它。', next: 'viktor_choice2' },
        viktor_choice2: { text: '在一场始于攻击妻子信仰的调查进行了两年之后,伟强坐在一个与两年前起点完全相反的结论面前——这个发现让他感到的恐惧,超过了他调查过的任何一条新闻。', choices: [
          { label: '接受自己这场调查的结论,拥抱信仰', effects: { faith: 15 }, next: 'viktor_endLight' },
          { label: '因为改变想法太过难堪而抛弃自己的结论', effects: { faith: -15 }, next: 'viktor_endDark' },
        ] },
        viktor_endLight: { text: '伟强承认:经历了这样一场调查之后继续做无神论者,所需要的盲目信心反而比成为基督徒更多——而他的职业操守已经不允许他这样做了。他离开了新闻业,把时间用来向他人讲述这场彻底改变了自己人生的调查,并把这两年的研究写成了一本书,用的正是他从前写报道时那种法庭证据般的语言。后来他成了自己教会的教导牧师,而那本他从未打算写的书,在全世界卖出了数百万册,还被改编成了一部讲述他自己这场调查的电影。伟强的故事到此结束。', next: null, choices: [] },
        viktor_endDark: { text: '伟强把装着自己那些结论的文件夹锁进了书桌抽屉,继续维持从前的公开立场——只是为了不向同事承认自己整整两年都是错的。他依然自豪地向所有人展示自己的法学和新闻学学位,证明自己分得清事实与虚构——但那份记录着自己调查结果的文件夹,他再也没有打开过。妻子再也没有在晚饭时提起过这个话题。伟强的故事到此结束。', next: null, choices: [] },
      },
    },
    ruslan: {
      start: 'ruslan_intro',
      scenes: {
        ruslan_intro: { text: '瑞安从小就能背诵经典经文,一生都在为捍卫自己的信仰做准备——这是全家人对他的期望,他们为这个从小就如此认真的孩子感到骄傲。考入医学院后,他和一位基督徒同学成了朋友——他们的第一次争论始于瑞安看见对方房间里摊开的一本圣经,自信能轻松取胜,便主动挑起了话题——这段友谊很快变成了一场持续多年、却始终彼此尊重的辩论,与他们的医学课程并行展开,而两人都习惯了在相信任何事之前先要求证据。', next: 'ruslan_scene2' },
        ruslan_scene2: { text: '这场辩论持续了很多年,常常是在课后喝茶时进行,却从未演变成争吵——他们太尊重彼此,不会人身攻击,尽管两人从一开始就坦诚地互相提醒过,他们都愿意追随真相,哪怕它会推翻自己从小笃信的一切。瑞安早已准备好各种标准问题的标准答案,但朋友总是固执地不问标准问题,挖掘的深度远超瑞安习惯回答的范围。', next: 'ruslan_choice1' },
        ruslan_choice1: { text: '又一次这样的谈话之后,朋友提出了一个基于原始文献的严肃历史论点,而瑞安——尽管做足了准备——却找不到令人信服的回答,这比以往任何论点都更让他害怕。', choices: [
          { label: '把这个问题彻底弄清楚,哪怕不喜欢答案', effects: { faith: 10 }, next: 'ruslan_bridgeA' },
          { label: '就此打住,再也不跟朋友提起', effects: { faith: -10 }, next: 'ruslan_bridgeB' },
        ] },
        ruslan_bridgeA: { text: '瑞安花了三年半的时间,在夜里研究两种信仰的资料,瞒着大多数熟人,把每一次发现都像写病历一样有条理地记录下来,而不是当作私人的疑虑日记——这个习惯正是医学训练教给他的。在某个时刻,一件他这辈子从未有过的事发生了:他开始直接向神祷告,祈求一个属于他个人的记号,而不只是书本上的答案——就在这样一个夜晚之后不久,他做了一个梦,他认定这是对自己祈求的直接回应。这不是为了在下一次喝茶时的辩论中获胜,而是为了终于、彻底地弄清真相,无论它多么令人不安。', next: 'ruslan_choice2' },
        ruslan_bridgeB: { text: '瑞安有好几个月都在回避这个话题,不断找新的借口推迟和朋友的见面。他不断告诉自己答案早就知道了——只是需要把那段经文再仔细读一遍——可每一次,他合上书时都没能找到自己想找的东西。那个没有得到答案的问题,每次他睡前打开自己惯常的书时,都会在脑海中回响。', next: 'ruslan_choice2' },
        ruslan_choice2: { text: '多年秘密研究之后,瑞安得出了一个让自己害怕的结论:他再也无法在自己面前诚实地为从前的信仰辩护,更别说在别人面前——而公开归信将让他失去几乎所有的关系,包括家人。', choices: [
          { label: '接受自己认定的真理,不计代价', effects: { faith: 15 }, next: 'ruslan_endLight' },
          { label: '为了家人和朋友留在从前的信仰中', effects: { faith: -15 }, next: 'ruslan_endDark' },
        ] },
        ruslan_endLight: { text: '瑞安做出了他称之为一生中最痛苦的决定——正如他所担心的,他在一年之内几乎失去了所有他爱的人,包括始终没有完全原谅他的父亲。他放弃了行医,转而站上讲台,在成千上万的听众面前进行同样诚实的辩论,加入了一个国际基督教护教事工,并写完了一本讲述自己心路历程的书,后来在多种语言中都成了畅销书。三十三岁那年他被诊断出胃癌晚期,但即便如此他也没有停下——在病床上继续为听众录制视频,诚实地讲述自己走过的怀疑与失去之路,而不只是最终抵达了哪里——直到疾病过早地夺走了他的生命。瑞安的故事,到此结束。', next: null, choices: [] },
        ruslan_endDark: { text: '瑞安留在了从前的信仰里,保住了家人和熟悉的朋友圈,但朋友提出的问题始终没有得到诚实的回答——只是被埋得足够深,不至于在夜里搅扰他的睡眠。他后来如全家所愿成了一名执业医生,但偶尔,尤其是在值夜班的时候,他会不由自主地想起那场没有了结的对话,想着如果多年后的今天鼓起勇气再问一次,自己会怎么回答朋友。瑞安的故事,到此结束。', next: null, choices: [] },
      },
    },
    roman: {
      start: 'roman_intro',
      scenes: {
        roman_intro: { text: '罗明在皇后区建立了自己的网络,和几个哥哥一起直接与哥伦比亚贩毒集团合作,把可卡因贩卖到整个东海岸——金钱、风险、他人赤裸裸的恐惧,对他而言就像别人每天早上喝咖啡一样平常,直到自己的一个同伙被联邦探员抓获,同意做污点证人,把他供了出来。早在和哥哥们一起建立起这张网络之前,罗明十二岁就染上了大麻,十三岁加入了街头帮派,一开始在皇后区贩卖小批可卡因只是为了付自己越来越重的毒瘾账单——后来才发展成整个东海岸的供货网络。他是家中五兄弟之一,父母是多米尼加移民,六十年代初几乎身无分文来到纽约,只为给孩子们一个更好的未来。', next: 'roman_scene2' },
        roman_scene2: { text: '罗明和其中一个哥哥在把货送往曼哈顿客户的路上被拦下——两人当场试图逃跑,但都被抓获,车里搜出了将近四百万美元的可卡因。罗明早就预感到这一天迟早会来,被捕的那一刻,他感到的与其说是恐惧,不如说是一种奇怪的、近乎解脱的感觉:终于不用再等了。', next: 'roman_choice1' },
        roman_choice1: { text: '检察官一开始就要求判罗明二十五年,把所有罪名一并计入。他的律师避开他的目光说,如果罗明能在庭审之前——而不是之后——让法庭确信自己真的在改变,或许有机会大幅减刑。', choices: [
          { label: '第一次诚实地审视自己变成了什么样的人', effects: { faith: 10 }, next: 'roman_bridgeA' },
          { label: '只把这当作换取更短刑期的手段', effects: { faith: -10 }, next: 'roman_bridgeB' },
        ] },
        roman_bridgeA: { text: '早在庭审之前,不久前刚信主的哥哥开始定期到拘留中心探望罗明,有一天,没有任何说教,只是像家人一样,向他讲起了耶稣的故事。哥哥当时对他说:"哈利路亚,感谢主——你知道神爱你",罗明起初只是不耐烦地摆摆手,以为牢狱生活把哥哥逼疯了。罗明开始参加监狱礼拜——起初只是为了在审讯之间打发时间,但在一次聚会上,一位同为囚犯的讲道人说了一句话,比任何华丽的言辞都更深地扎进了他心里——神所赐的平安超乎人所能理解——就在那一刻,出乎所有人的意料,他生平第一次感受到一种真实、可触摸的平安,而不只是暂时的平静。他开始在晚上写一本简短的日记,生平第一次尝试老老实实地一天天算清楚,自己为了赚钱建立起来的一切,到底伤害了多少人和多少个家庭。几个月后,他自己也开始主持部分监狱礼拜——为新来的囚犯朗读圣经段落,那些人和当年的他一样,只是为了在审讯之间打发时间才走进小教堂。', next: 'roman_choice2' },
        roman_bridgeB: { text: '罗明一丝不苟地出席礼拜,只是做做样子,在牢房的镜子前排练着给未来法官听的悔过之词,但内心什么都没有真正改变——只是对不得不假装这件事的厌烦与日俱增。同一个哥哥在一次难得的探视中,盯着他的眼睛平静地说:"你知道神爱你",罗明只是摇了摇头,把话题转向庭审辩护的细节,没有正面回应一个字。', next: 'roman_choice2' },
        roman_choice2: { text: '法官宣读了减刑后的判决——三年,而不是最初的二十五年,法庭里传来压低的窃窃私语,旁听席上既有从前的顾客,也有那些被卷入他关系网的人的父母。罗明如今有了这几年具体的时间,可以用行动而非在法官面前的言辞,来决定出狱后自己会成为什么样的人。', choices: [
          { label: '用这几年真正让自己脱胎换骨', effects: { faith: 15 }, next: 'roman_endLight' },
          { label: '熬完刑期,回到从前的关系网', effects: { faith: -15 }, next: 'roman_endDark' },
        ] },
        roman_endLight: { text: '罗明服满了减刑后的刑期,一天不多不少,出狱时已是完全不同的人,回到了同一座城市——不再是毒贩,而是那个他曾在此贩卖死亡的街区里,一间小教会的牧师。如今,他的教会里坐满了曾经整个街区都惧怕的人,包括从前的他自己,一些会众还认出他就是当年在这些街道上人人避之不及的那个人。出狱后,罗明写了一本讲述这段经历的书——《移动的阴影:一个纽约毒枭在最不抱希望之处找到了自由》——除了牧养自己的教会,他还专门为当年招募像他十三岁时那样的少年入伙的那片街区,开展了一项青少年事工。罗明的故事,到此结束。', next: null, choices: [] },
        roman_endDark: { text: '罗明准时出狱,几乎立刻恢复了从前的关系网,仿佛那些铁窗岁月从未发生过。它们几乎什么都没有改变,除了如今新案子的传票寄往的地址。换个境遇本可能由他自己写下的那本书,他始终没有动笔;曾经只是做做样子走进去的那间小教堂,他也再没想起过。罗明的故事,到此结束。', next: null, choices: [] },
      },
    },
    anton: {
      start: 'anton_intro',
      scenes: {
        anton_intro: { text: '二十五岁那年,安宁沦落街头,无家可归,还染上了海洛因毒瘾——这份毒瘾并非始于什么惨剧,而是始于无聊:十二岁那年,他因为无聊、渴望刺激而尝试了药片和酒精,这是他后来自己说的。十三岁他就为了兜风偷车,十四岁离家出走,一路搭便车穿越了大半个国家。他曾发誓绝不碰海洛因,可十七岁那年打破了誓言,从此再没停下,不知不觉间这成了他唯一记得的生活,最终一无所有,连安身之处都没有。', next: 'anton_scene2' },
        anton_scene2: { text: '冬天,安宁学会了寻找地铁通风口取暖的位置,也学会了辨认哪些院子可以过夜而不会被赶走或被自己人抢劫。他早已不再计算日子,几乎也不再把自己看作一个还能拥有别种人生的人。快三十岁时,他辗转好几家诊所,用假证件领取足以致普通人于死地剂量的美沙酮——每一次都只是为了撑到第二天,而不是为了戒掉。他早已数不清有多少次因吸毒过量,被那些早已麻木的急救医生从鬼门关拉回来。', next: 'anton_choice1' },
        anton_choice1: { text: '一个安宁只是为了取暖才走进的流浪者收容所里,有人向他提出一个简单的建议:来参加晚上的聚会,听一听——没有条件,不必强迫加入任何项目,只是来一次而已,这样的邀请已经重复了好几个星期。', choices: [
          { label: '去,因为确实没什么可失去的了', effects: { faith: 10 }, next: 'anton_bridgeA' },
          { label: '拒绝——他已经不再相信任何人任何事', effects: { faith: -10 }, next: 'anton_bridgeB' },
        ] },
        anton_bridgeA: { text: '安宁出于纯粹的好奇心去了,结果听得比原计划久得多。最后,有人告诉他,就在这里、此刻把生命交给神——他并不真正明白这意味着什么,却还是这样做了,与其说出于信仰,不如说出于疲惫。后来他才知道,那个大厅里的人早在他答应去之前,已经连续三个月每天为他祷告,直到那晚才告诉他。集体祷告时,安宁的身体突然颤抖,冒出冷汗,而那颗多年沉浸在毒品迷雾中的心,二十年来第一次感到清醒。', next: 'anton_choice2' },
        anton_bridgeB: { text: '安宁拒绝了,那天夜里他仍在老地方过夜——地铁通风口上,吸着一如既往的毒品,远远听着那场邀请他参加、如今正在举行的聚会。这已不是他第一次得到这样的机会:多年来一次次被捕,不止一个同室的犯人跟他提过真正能帮助这类人的地方——但每次听起来都像又一个空话,他每次都回到了原来的地方,继续用假证件在诊所之间辗转。', next: 'anton_choice2' },
        anton_choice2: { text: '第二天早晨,安宁的身体像多年来的每个早晨一样,渴求着惯常的那剂海洛因——但内心有种他自己都无法完全解释的东西,第一次让他停在原地,而不是驱使他出去寻找。', choices: [
          { label: '不去找那剂毒品,留在收容所里', effects: { faith: 15 }, next: 'anton_endLight' },
          { label: '像每天早晨一样,去找惯常的那剂毒品', effects: { faith: -15 }, next: 'anton_endDark' },
        ] },
        anton_endLight: { text: '安宁没有去找那剂毒品——与他过去对戒断反应的所有认知相反,他的身体没有出现惯常的剧痛。他说,这不是意志力,他从来没有过意志力,而是那一天,有别人替他扛下了这一切。戒瘾几个月后,他终于又能给家人打电话,多年来第一次大声说出自己的全名,而不是街头绰号。他开始带领的小型查经班,多年后发展成了流浪者食堂旁的一个团契,后来又成了他自己的教会,设有监狱事工和前科人员住房项目——正是当年一个陌生人随口一句建议,把他带到的那种地方。安宁的故事,到此结束。', next: null, choices: [] },
        anton_endDark: { text: '安宁像任何一个早晨一样,去找了那剂惯常的毒品。流浪者收容所依旧只是他日常路线上的一站,他有时冬天会进去取暖,仅此而已。多年后,他仍时常回到同样的拘留室,又有人试图向他讲述神——每一次都以同样冷漠的耸肩收场,而他十七岁那年打破的那个誓言,始终没有一次真正被收回。安宁的故事,到此结束。', next: null, choices: [] },
      },
    },
    pavel: {
      start: 'pavel_intro',
      scenes: {
        pavel_intro: { text: '博文在一座热带岛屿附近潜水捕龙虾时,接连被五只致命水母蜇伤——这是一种罕见、近乎不可能发生的巧合。那毒液足以在四分钟内杀死一个普通人,而那一刻,他既不信神,也不信死后有任何生命。', next: 'pavel_scene2' },
        pavel_scene2: { text: '船上的朋友们把已经开始抽搐的博文拉出水面,触手接触过的皮肤已被灼伤发黑。在等待救援船的过程中,他的身体从脚开始逐渐麻木,意识也在缓慢而沉重的浪潮中渐渐熄灭,仿佛有人正一间接一间地把同一栋房子里的灯关掉。', next: 'pavel_choice1' },
        pavel_choice1: { text: '当身体麻木、意识完全熄灭之际,博文忽然异常清晰地想起了家中唯一的基督徒——他的母亲,她记忆中每一天都在为他祷告,即便他从不信这一套——以及她多年前说过的话:即使在最后一秒,只要真心愿意,也可以呼求神——这句话他曾经嘲笑过,此刻却异常清晰地回响在脑海中。', choices: [
          { label: '从内心深处呼求神,尽管并不真正相信', effects: { faith: 10 }, next: 'pavel_bridgeA' },
          { label: '把这个念头当作濒死的胡思乱想抛开', effects: { faith: -10 }, next: 'pavel_bridgeB' },
        ] },
        pavel_bridgeA: { text: '博文呼求了——不是按规矩来的祷告,他其实也不太懂规矩,而只是从残存意识深处发出的一声绝望呼喊。起初,一片彻底、冰冷的黑暗将他吞没——那种孤独如此彻底,以至于他后来称之为自己唯一真正经历过的死亡。接着光出现了,在那光中他看见自己一生的全部,每一件做错的事都清清楚楚,却没有一句指责,他感受到的不是审判,而是一个问题:知道这一切之后,是否愿意重新开始。就在那同一片光中,他清楚地感受到的不是空无,也不是某种无形的力量,而是一个位格——爱得如此毫无条件,以至于他对自己一生的羞愧开始自行消融,仿佛迎接他的不是审判者,而是一位在家中等了他多年的人。哪怕没有一句话被说出口,他也明白了最关键的一点:这光是有名字的,而这个名字不属于某个抽象的概念,而属于那位曾亲自经历真正死亡的那一位,只为了让此刻还能有另一种结局。片刻之后,救护车上的医生正式宣告他死亡。', next: 'pavel_choice2' },
        pavel_bridgeB: { text: '博文把神的念头当作垂死大脑产生的荒诞想法抛开,只是等待一切结束——没有一句祷告,没有一个字投向自己正在熄灭的意识之外的任何存在,只有沉默和越来越深的黑暗,没有一丝光亮出现。救护车上的医生很快宣告他死亡,一如所有迹象所显示的那样。', next: 'pavel_choice2' },
        pavel_choice2: { text: '二十分钟后,已经躺在医院太平间盖着白布的金属尸台上,博文出人意料、无法解释地恢复了意识——活着,完全瘫痪,连一根手指都动不了,但活着,让推门进来的护工手中的病历板都掉在了地上。', choices: [
          { label: '把这当作一次有意义的第二次机会来接受', effects: { faith: 15 }, next: 'pavel_endLight' },
          { label: '归结为一次罕见的医学巧合,然后忘掉它', effects: { faith: -15 }, next: 'pavel_endDark' },
        ] },
        pavel_endLight: { text: '瘫痪躺着的博文听见医生低声说他恐怕撑不过去,整夜不停地只求一件事:让中毒的每一个细胞在天亮前痊愈。天亮时他能动一根手指,接着是一只手,到中午已靠自己的双腿走出了医院,尽管所有医学预测都说他即便活下来也应该永远瘫痪。他把经历写成了一本书,从那以后走遍几大洲数十个国家,在座无虚席的大厅里讲述自己在那条界线之外所见到的一切——黑暗、光、审判与抉择,而不只是一个在温暖热带海水中被水母毒液蜇伤又奇迹生还的故事。博文的故事,到此结束。', next: null, choices: [] },
        pavel_endDark: { text: '博文把发生的一切归结为一次罕见、无法解释的医学奇迹,尽快把它忘掉,回到了从前潜水员的生活——同一艘船,同样的夜潜捕龙虾,同一群下班后在酒吧碰面的朋友。出院前给他检查的医生只是摇头,既解释不了那些愈合得比正常快得多的灼伤,也解释不了自己消退的瘫痪——但对博文来说,这始终只是一件医学上的怪事,从未成为他深入追问自己的理由。有时夜里,他仍会想起那条光的隧道,还有它之前的黑暗,还有那个关于是否愿意重新开始的问题——却始终没有决定该拿这段记忆怎么办,一次又一次把这场与自己的对话推到一个始终不会真正到来的明天,而母亲每天不间断的祷告,他也始终没有回应过一次,仿佛那不过是背景里的噪音。博文的故事,到此结束。', next: null, choices: [] },
      },
    },
    yulia: {
      start: 'yulia_intro',
      scenes: {
        yulia_intro: { text: '雨薇出生在一个跨越几大洲、以公社形式辗转迁徙的封闭传教团体里,一切都由唯一的运动领袖定夺——穿什么、和谁做朋友、能翻开哪些书。那里没有人真正在意团体外同龄人视为理所当然的学历,唯一重要的功课是无条件的顺从。因为不断搬迁,雨薇在好几大洲的六个国家长大,还没真正学会用任一种语言读写之前,就已经能凭耳朵讲三种语言。', next: 'yulia_scene2' },
        yulia_scene2: { text: '雨薇真心相信,服从组织本身就是信仰,在公社里生活的二十三年间,她几乎没见过外面的世界。到了这个年纪,她做出了一个连她自小认识的几乎所有人都无法想象的决定:独自一人离开,没有正常的学历证明,外面也没有一个熟人。她唯一会的祷告,是全团体每天早上应领袖号令齐声背诵的集体祷词——她从来没有找到过属于自己、用来对神说话的话语。', next: 'yulia_choice1' },
        yulia_choice1: { text: '雨薇同时打几份零工,租住在青年旅舍的一张床位,给自己定下了一个近乎不可能的目标——通过考试,考进一所真正的大学。面试时,招生负责人直截了当地问,为什么她的档案里没有正常的中学经历,显然在等一个完整的解释。', choices: [
          { label: '说出自己从小成长的邪教真相', effects: { faith: 10 }, next: 'yulia_bridgeA' },
          { label: '撒谎,编一个体面的童年故事', effects: { faith: -10 }, next: 'yulia_bridgeB' },
        ] },
        yulia_bridgeA: { text: '雨薇说出了真相,原以为会被拒绝——招生负责人却反而为她安排了家教,帮她用两年时间补完通常要五年的中学课程。得知雨薇曾在六个国家长大、凭耳朵学会三种语言,负责人竟为她争取到了全额奖学金——那段曾让她感到羞耻的漂泊童年,在纸面上意外成了优势。她白天工作,夜里读书,同时读着那本她在团体里只被允许通过传道人转述、从未亲眼完整读过的圣经。就在那年冬天,她生平第一次尝试用自己的话祷告,而不是齐声跟念——却发现没人带头时,自己竟不知从何说起。', next: 'yulia_choice2' },
        yulia_bridgeB: { text: '雨薇撒了谎,编造了一个只字不提团体的美满家庭故事,负责人没有再追问。谎言让她躲开了同学异样的目光,但每一次讲述"正常童年",都变得更加沉重,她渐渐开始回避所有私人话题。她始终没有勇气告诉招生负责人那六个国家和三种语言——那才是真正塑造了她的东西,远胜过任何学校——与此同时,她也从自己的新履历里,抹去了那唯一一次真正尝试用自己的话说出口的祷告。', next: 'yulia_choice2' },
        yulia_choice2: { text: '多年以后,雨薇已经拿到正式的法律学位,在一家大公司工作,一位出版商找上门来——邀请她用真名写一本书,讲讲自己长大的那个团体里到底发生过什么。出版就意味着要向那些至今以为她只是普通人、有着普通过去的律师同事们,坦白一切。', choices: [
          { label: '用真名写下这本书,毫不隐瞒', effects: { faith: 15 }, next: 'yulia_endLight' },
          { label: '拒绝邀约,把过去永远埋藏', effects: { faith: -15 }, next: 'yulia_endDark' },
        ] },
        yulia_endLight: { text: '雨薇用真名写下了这本书,没有为了照顾团体旧识的感受而软化任何一句话。书传到了成千上万读者手中,许多人也曾在类似的封闭团体中长大,第一次知道自己并不是唯一背负这种经历的人。读者最常写给她的一句话是:读完她的书后,自己第一次尝试不照着别人的祷词,而是用自己的话祷告,就像她当年那样。她的一部分家人后来也离开了团体,在这本书出版后,多年来第一次重新联系上了她。雨薇的故事,到此结束。', next: null, choices: [] },
        yulia_endDark: { text: '雨薇拒绝了这次邀约,认定一个没有过去的律师形象,比任何坦白都更安全。她此后的整个职业生涯,都活在一种随时可能被人识破真相的隐隐不安中。童年背熟的那段集体祷词,始终是她唯一会说的祷告——这么多年过去,她也始终没能找到属于自己的话语,来对神说话。雨薇的故事,到此结束。', next: null, choices: [] },
      },
    },
    oksana: {
      start: 'oksana_intro',
      scenes: {
        oksana_intro: { text: '慧珊在战区服役十个月后回到家中——在那里,她和部队里的男兵一起执行战斗任务,不止一次在炮火下救治伤员时默默重复着一句短短的、绝望的祈祷:"神啊,让我活着回家。"回家后,她已经认不出镜子里的自己——任何关门声都会让她猛地一惊,连续睡眠从未超过两小时,每天晚上都要多倒一点酒,好让大脑暂时停下来。慧珊先在国民警卫队服役,后来转入陆军预备役,她在战地的任务不是在前线端枪,而是把伤员从炮火中运出来就地救治,每次担架旁都再低声祷告一句:"神啊,别让这个人死",然后才等来撤离。', next: 'oksana_scene2' },
        oksana_scene2: { text: '在家里,女儿用一张"欢迎回家"的画迎接她,那画在冰箱上只挂了一周,慧珊就已完全不再注意到它。邻居们都认识她是个安静、有礼貌的女人——除了女儿,没有人看见她夜里双手颤抖的样子,那时酒瓶总是比睡意先见底。她在部队心理医生那里只去了两次,就说"还没准备好谈这些"。一位为军人服务的基督教机构的女士,在她回家后头几个月就主动伸出援手,但慧珊当时断然拒绝交谈,直接关上了门。', next: 'oksana_choice1' },
        oksana_choice1: { text: '每当母亲夜里醉醺醺地回家,刚满十岁的女儿就越来越多地躲进自己房间,关上门。楼里一位安静的信徒邻居,她们平时几乎只是打个招呼,有一天毫无压力地对她说:"来参加我们的复活节礼拜吧,就是坐一坐,没别的。"', choices: [
          { label: '至少去一次,因为已经没什么可失去的了', effects: { faith: 10 }, next: 'oksana_bridgeA' },
          { label: '拒绝——她不需要任何人的怜悯', effects: { faith: -10 }, next: 'oksana_bridgeB' },
        ] },
        oksana_bridgeA: { text: '慧珊去了那次复活节礼拜,令自己都意外的是,一周后她又去了一次。那天的讲道正好讲的是基督作为元帅——用的是她在前线服役将近一年后才能真正听懂的语言——散会后,牧师对她说了一句她会记很多年的话:"现在,你有了新的总司令。"往后的日子里,教会里的人只是默默地、善意地陪伴着她,不追问,不逼她说什么。几个月这样持之以恒的关心之后,她这些年在军中筑起的那层盔甲开始出现裂缝,她自己第一次主动开口,说出了那些从未对军队心理医生说过的事。那些日子里,她重新看了一部关于战斗创伤后应激障碍的短片——后来她自己也参与了制作——十五分钟朴素的人生故事,让她第一次说出了连自己都不曾承认的痛苦。回家后的第一句祷告"神啊,我愿意跟随你的带领",她第一次是大声说出来的,而不只是嘴唇动了动。', next: 'oksana_choice2' },
        oksana_bridgeB: { text: '慧珊拒绝了,继续像服役时学会的那样独自应付一切。酒瓶渐渐变得比自己那个安静坐在紧闭房门后面的女儿更加熟悉,也更容易理解。那位第一时间伸出援手的基督教军人机构的女士,后来几个月里又打过几次电话,但慧珊每次都匆匆挂断。', next: 'oksana_choice2' },
        oksana_choice2: { text: '定期参加聚会几个月后,一位曾经同部队的相识介绍慧珊在同一支部队的老兵面前发言,他们和她一样,回家后变成截然不同的人,多年来一直沉默,把同样的伤痛藏在同样礼貌、平静的面具后面。', choices: [
          { label: '如实讲述一切,包括酒瓶和羞耻', effects: { faith: 15 }, next: 'oksana_endLight' },
          { label: '拒绝——这太私人了,不能跟陌生人分享', effects: { faith: -15 }, next: 'oksana_endDark' },
        ] },
        oksana_endLight: { text: '慧珊如实讲述了一切,包括酒瓶和在女儿面前的羞耻。如今她正是与这样的老兵一起工作,帮助他们走过自己曾走过的路——从每晚一瓶酒,到女儿终于不再在她回家时躲起来。她还在那家曾拒绝交谈的基督教军人机构义务参与同一个创伤后应激障碍小组,并帮忙拍摄那些曾帮助她第一次说出真相的短片。慧珊的故事,到此结束。', next: null, choices: [] },
        oksana_endDark: { text: '慧珊拒绝分享,继续独自撑到最后。女儿长大后,记忆里的母亲身体总是在场,内心却很少真正在场。那家曾主动提供帮助的基督教军人机构,后来几年里又给她写过几次信,但始终没有收到过哪怕一次回复。慧珊的故事,到此结束。', next: null, choices: [] },
      },
    },
    vika: {
      start: 'vika_intro',
      scenes: {
        vika_intro: { text: '薇琪是一位牧师的妻子,多年来一直把身上的淤青解释为自己笨手笨脚——先是对自己,后来是对体检时的医生,再后来是对开始追问的年幼孩子们。从结婚那天起,她就被教导妻子顺服丈夫是顺服上帝的一部分,她也真心相信这一点——意味着无论如何都该忍耐,而她自己的痛苦不是拆毁本该神圣之事的理由。离开一位在教会服事的丈夫,不只是意味着离婚,更意味着摧毁整个会众的名声——正是这一点,比任何淤青都更牢牢地把她留在原地。', next: 'vika_scene2' },
        vika_scene2: { text: '岁月在同一个循环里流转:争吵、叫喊、一记耳光、眼泪、道歉,平静几周,然后一切重新开始。此后每晚,薇琪都念着同一个祷告——不是求一条出路,而是求丈夫改变,求自己有力气再撑一段时间。面对会众,甚至面对自己的部分家人,她早已练就了同一套关于自己笨手笨脚的说辞,她清楚,一位牧师的妻子若抱怨挨打,毁掉的会远不止她自己的婚姻。', next: 'vika_choice1' },
        vika_choice1: { text: '一个格外残暴的夜晚之后,当她不得不向自己的孩子——而不再是向会众——解释颧骨上的淤青时,一位偶然瞥见她挂彩面容的朋友,默默递给她一张求助中心的电话号码,说:"先带着就好。今天不必打。"', choices: [
          { label: '留下那个号码,等真正害怕的时候再打', effects: { faith: 10 }, next: 'vika_bridgeA' },
          { label: '扔掉号码——她不想毁掉丈夫的名声', effects: { faith: -10 }, next: 'vika_bridgeB' },
        ] },
        vika_bridgeA: { text: '薇琪把号码藏进钱包的夹层里。拨号之前,她多年来第一次翻开圣经,不是为了给自己的忍耐找理由,而是带着一个真实的问题:难道神真的要她留在一个让她担心自己性命的地方吗?那天晚上她找到的答案,不是关于顺服丈夫,而是关于她的身体和生命本身在神眼中就是宝贵的。当晚,她终于鼓起勇气拨通电话,带着孩子们离开了家——她知道这必然意味着漫长的监护权诉讼,比她还身处婚姻之中时所能想象的,要漫长和煎熬得多。', next: 'vika_choice2' },
        vika_bridgeB: { text: '薇琪当晚就把号码扔掉,选择留下,认定丈夫和整个会众的名声比自己的安全更重要。那晚她祷告的还是老一套——求力气再多撑一阵,而不是求一条出路。朋友得知后,一句责备的话都没说——只是几周后,又默默把同一个号码,抄在另一张卡片上,再次递给她。', next: 'vika_choice2' },
        vika_choice2: { text: '在一场明显要拖上好几年、令人心力交瘁的子女监护权诉讼中,薇琪每次开庭前都祷告同样的话——不是求打赢官司,而是求自己不要在这场抗争中迷失自己。她必须决定:是继续在法庭上为孩子和真相抗争,还是选择退让,好让一切早点结束。', choices: [
          { label: '不管要花多少年,都继续为孩子和真相抗争', effects: { faith: 15 }, next: 'vika_endLight' },
          { label: '退让,只求一切早点结束', effects: { faith: -15 }, next: 'vika_endDark' },
        ] },
        vika_endLight: { text: '薇琪经历了一场几乎长达十年的监护权诉讼,整个过程中,她一直紧紧抓住一种对她而言和这场令人筋疲力尽的抗争同样真实的信仰。曾经只求撑下去的祷告,变成了别的东西——感恩神一直都站在她的安全这一边,而不是站在她的沉默这一边。如今,她和其他有相似经历的女性一起,为离开这类婚姻后正经历离婚的信徒母亲们运作一项支持事工——提供现成的资料,帮助她们准备监护权听证会,更重要的是告诉她们:神从未要求她们留在伤害自己的地方。薇琪的故事,到此结束。', next: null, choices: [] },
        vika_endDark: { text: '薇琪在监护权诉讼结束前就提前退让,只求一切早点结束——此后多年,她一直后悔自己当初没有足够的力量,把为孩子和真相抗争到底。她仍然每晚祷告,却始终没能把那个问题问出口:神要她忍耐的,到底是这样的伤害,还是别的什么——这个问题一年年悬在那里,始终没有答案。薇琪的故事,到此结束。', next: null, choices: [] },
      },
    },
    tanya: {
      start: 'tanya_intro',
      scenes: {
        tanya_intro: { text: '婷雅拥有神学博士学位,在大学担任助理牧师——按照职责安慰、支持着别人——就在这时,她第一次听见了声音,起初轻柔,几乎带着几分温柔,后来变得苛刻而残忍。医生称之为双相情感障碍伴发的精神病;婷雅本人是受过训练的神学博士,好几个月都无法在自己的书里找到答案:疾病在哪里结束,又是什么没有医学名称的东西在哪里开始。她第一次真正的崩溃发生在孩子出生后不久——当时医生诊断为产后抑郁症,直到后来又经历了几次发作,她才被确诊为更严重的病症。', next: 'tanya_scene2' },
        tanya_scene2: { text: '几次住院中的第一次格外难熬——教会里的同工们不知道该如何面对一位突然自己成了精神科病人的牧师。团契里许多人习惯了把婷雅看作给予安慰的人,而不是需要安慰的人,其中一些人干脆从她的生活中消失了,仿佛这个诊断会传染。就连她自己神学系的学生,都不知道她这几周究竟去了哪里。除了教学和牧师工作之外,她多年来一直是当地一个精神疾病患者家庭互助组织理事会的成员,也是大学精神病院顾问委员会的一员——早在她自己公开承认之前,她就已经从两个角度都深谙这个领域。', next: 'tanya_choice1' },
        tanya_choice1: { text: '在那一年第三次住院期间,一位相识多年的系里同事向婷雅提议,诚实地、不用安慰性的神学套话,聊聊她此刻真正的感受——不是牧师对牧师,只是一个受苦的人对另一个受苦的人。', choices: [
          { label: '答应,第一次不再躲在职业角色背后', effects: { faith: 10 }, next: 'tanya_bridgeA' },
          { label: '拒绝——自己突然站到另一边,实在太奇怪了', effects: { faith: -10 }, next: 'tanya_bridgeB' },
        ] },
        tanya_bridgeA: { text: '令自己都意外的是,婷雅答应了,而这次谈话完全不是要用信仰来解释疾病,也不是用疾病为信仰开脱——只是很久以来第一次,有人把她当作一个人,而不是一个必须自己扛下去的牧师来倾听。她回到了那套固定的祷告时刻——正是她自己多年来教给学生的古老修道院式作息,而她自己却早已不再真正践行——那些古老的诗篇,带着向神发出的诚实抱怨,对她而言听起来与教科书上的文字完全不同。', next: 'tanya_choice2' },
        tanya_bridgeB: { text: '婷雅拒绝了,那几周她在病房里几乎完全沉默,出于习惯继续用自己已经无法用在自己身上的话安慰同病房的病友,独自面对那些声音——药物把它们压低成了耳语,却始终无法彻底消除。', next: 'tanya_choice2' },
        tanya_choice2: { text: '多年以后,又经历了几次住院,有人邀请婷雅以第一人称写一本关于信仰与精神疾病的诚实之书——不是给别人危机用的神学论著,而是坦白说出:身为一个被人信任来安慰他人的人,她自己多年来正是在与这个搏斗。出版商直接要求她不要回避最艰难的章节——轻生的念头、精神病房本身、她不得不接受的电休克治疗——这些都是教会内部通常绝口不提的事。', choices: [
          { label: '诚实地写,包括那些信仰并没有立刻拯救她的时刻', effects: { faith: 15 }, next: 'tanya_endLight' },
          { label: '拒绝——在全体会众面前承认这份软弱风险太大', effects: { faith: -15 }, next: 'tanya_endDark' },
        ] },
        tanya_endLight: { text: '婷雅毫无粉饰地写下了这本书,诚实地描述了那些声音、那些绝望的发作,以及教会有时如何用空洞的安慰而不是真正的陪伴来回应她的痛苦。她直言不讳地写道:双相情感障碍并没有消失,住院有时还会再次发生——信仰没有取代药物和精神科医生,而是与治疗并肩同行,而不是取而代之。这本书传到了成千上万信徒手中,他们第一次诚实地听到:精神疾病与深厚的信仰,可以同时存在于同一个人身上,彼此并不互相取消。多年后这本书再版,还加上了国内一位最知名教会领袖撰写的序言,让读者范围进一步扩大。婷雅的故事,到此结束。', next: null, choices: [] },
        tanya_endDark: { text: '婷雅拒绝出版这本书,认定承认这一具体的软弱,会让她作为牧师的职业声誉付出太大代价。她继续按计划安慰别人,甚至向系里最亲近的同事都隐瞒了自己住院的经历。婷雅的故事,到此结束。', next: null, choices: [] },
      },
    },
    galya: {
      start: 'galya_intro',
      scenes: {
        galya_intro: { text: '佳丽和丈夫经营的小型家族企业,因一笔失败的交易在一年之内彻底垮掉,两人因此宣告破产。情况严重到家里连冰箱都没有了,食物只能放在一个普通的野营冰桶里,每天到超市重新装冰。在企业本来的债务之上,又叠加了一笔多年来悄悄累积的税务欠款——两者加在一起,成了一堵再也无法靠新贷款绕过去的墙。', next: 'galya_scene2' },
        galya_scene2: { text: '破产后的最初几个月,佳丽努力不让孩子们察觉到差别——用做游戏代替往常的购物,把没钱吃一顿像样的晚饭说成是"露营",而不是承认现实。夜里,等所有人都睡了,她常常长时间盯着那摞未付的账单,不知从何处理起。那些日子里,晚上常常开着一个基督教电视频道——佳丽听着节目里说,神很在意基督徒如何使用金钱,尽管她和丈夫当时根本没有一分积蓄可以真正拿来实践听到的道理。', next: 'galya_choice1' },
        galya_choice1: { text: '一位教会里的姐妹,偶然从共同的熟人那里得知了她们的真实处境,没有提出借钱——反正那也是迟早要还的——只是简单地说:"明天一早过来吧,我们一起看看,按神的方式,不慌不忙,一步一步理清你们的财务。"', choices: [
          { label: '去,尽管承认情况有多糟很丢脸', effects: { faith: 10 }, next: 'galya_bridgeA' },
          { label: '拒绝——自尊不允许在外人面前显露贫困', effects: { faith: -10 }, next: 'galya_bridgeB' },
        ] },
        galya_bridgeA: { text: '佳丽去了,整整第一个小时都羞愧得脸发烫。每次聚会都以祷告开始,整个计划本身也建立在一条具体的圣经原则上——"你们要给人,就必有给你们的"——佳丽一遍又一遍地读着这句话,起初完全不明白,当自己似乎已经一无所有可给时,要怎样按这条原则去生活。渐渐地,羞愧让位给了意想不到的宽慰——原来不止她一家熟人正经历这样的处境,而且真的存在一个可以实实在在照着走下去的计划,而不只是硬撑。对方提议的不是借钱,而是另一件事——给出她们没有的东西之外的东西,也就是时间:佳丽开始在一个救济食品发放点帮忙,照顾有需要的家庭,丈夫则开始给附近独居的老人送饭,尽管他们自己当时也几乎难以维持生计。也正是从那时起,他们生平第一次开始拿出十分之一奉献给教会,哪怕只是靠零星打零工挣来的一点钱——不是因为多出了闲钱,而是在完全没有闲钱的情况下依然这样做。', next: 'galya_choice2' },
        galya_bridgeB: { text: '佳丽出于自尊拒绝了帮助,继续独自默默应付,把丈夫和孩子的欠款通知藏在抽屉深处,直到那摞信件厚得再也藏不住。教会提议的那种帮助——不是借钱,而是和同样有需要的家庭一起在救济食品发放点做事——佳丽始终没有去尝试,她认为站在那些需要帮助的人中间,会比把账单藏在抽屉里更加羞辱。', next: 'galya_choice2' },
        galya_choice2: { text: '两年过去了——不管是靠着教会的计划,还是在长久沉默之后独自一人——变卖了家当、精心处理债务、重新学习量入为出的生活之后,佳丽被邀请在教会一次大型团契聚会上,向处于同样境况的其他家庭讲述自己的故事。', choices: [
          { label: '如实讲述一切,包括那个装冰的冰桶', effects: { faith: 15 }, next: 'galya_endLight' },
          { label: '拒绝——过去最好留在过去', effects: { faith: -15 }, next: 'galya_endDark' },
        ] },
        galya_endLight: { text: '佳丽如实讲述了一切,从那个代替冰箱的野营冰桶讲起。如今,她和丈夫一起为经历过同样处境的家庭主持同一门课程,每次聚会都以那句"我们当年也没有冰箱"开场,最后总会说,哪怕从彻底的零开始,家也是能重新建立起来的。他们从那间租来的公寓里重新起步的小生意,几年后已经在为大型全国性企业提供服务,甚至有一次还承接了白宫的订单——曾经连一台新冰箱都买不起的营收,多年后已接近每年一亿美元。佳丽的丈夫如今在每次这样的聚会上都会重复同一句话:问题从来不在于钱,而在于你手里那一点点真正拥有的东西,是由谁的手在打理。佳丽的故事,到此结束。', next: null, choices: [] },
        galya_endDark: { text: '佳丽拒绝讲述自己的故事,尽管债务最终还清了,那些年的羞愧仍是一个家庭秘密,即便在紧闭的房门后,他们两人之间也从未真正谈起过。那个曾邀请她去帮忙而不是去借钱的食品发放点,始终只是佳丽偶尔开车经过、却从未走进去过的一个地方。佳丽的故事,到此结束。', next: null, choices: [] },
      },
    },
    denis: {
      start: 'denis_intro',
      scenes: {
        denis_intro: { text: '德明在一个激进民族主义团伙中一路晋升,成为了其中一名区域头目,负责在和自己当年一样愤懑的青少年中招募新成员——仇恨对他而言不是一种信念,而是他每天重新选择的一种生活方式,从年轻时起,他就把它当作证明自己存在价值的唯一途径。三十岁时,他已经做到了3K党里"大巫师"这个最高级别之一;而当连3K党在他看来都不够激进时,他又加入了一个新纳粹团体,和他们一起参加了一场后来全国都在议论的游行。', next: 'denis_scene2' },
        denis_scene2: { text: '德明过着两副面孔的生活:一份用来应付各种证件的正常工作,另一份则是他真正为之而活的、有旗帜和游行的夜生活。他早就不再注意自己在集会上冲着喊叫的那些人的脸——对他来说,那些不是人,而是他所反对的一切的象征。', next: 'denis_choice1' },
        denis_choice1: { text: '城市另一端一间黑人教会的牧师听说了德明的事,没有回避他——反而想办法给他捎去了一份一对一谈话的邀请,没有摄像机,没有旁人,这在德明看来要么是疯了,要么是个陷阱。', choices: [
          { label: '还是去赴约,哪怕只是出于好奇,想知道牧师为什么要这样做', effects: { faith: 10 }, next: 'denis_bridgeA' },
          { label: '无视这份邀请,当作陷阱或软弱的表现', effects: { faith: -10 }, next: 'denis_bridgeB' },
        ] },
        denis_bridgeA: { text: '德明赴约时预备着争论、说教或陷阱,但牧师只是在自己家里,像对待一个普通人那样和他喝茶聊天——并一次又一次地邀请他,一个月接一个月,从不率先提起那个话题,也从未提过他手臂上的纹身。几个月后,牧师邀请他参加复活节礼拜,德明带着未婚妻一起去了,在那个七十人的会众里,他是仅有的三个白人之一。听着信众现场的歌声,而不是自己习惯的那种进行曲式的口号,他多年来第一次感受到的不是仇恨,而是一种沉默、难以解释的羞愧。', next: 'denis_choice2' },
        denis_bridgeB: { text: '德明无视了这份邀请,以为事情就此结束。但牧师并没有放弃,又通过一位共同的熟人转达了另一次见面的请求——只是聊聊,没有任何条件,也不录音。最终,与其说是出于真正的兴趣,不如说是拒绝得太累了,德明还是答应了,哪怕只去一次。他带着半个团伙的人赴约,心里仍然认定,一场和平的布道不过是软弱的另一种形式,而自己手臂上的纹身,比任何陌生牧师的话都更诚实地告诉路人他是什么样的人。', next: 'denis_choice2' },
        denis_choice2: { text: '几个月里瞒着团伙里的同伙秘密交谈之后,德明站在牧师的会众面前——这是他曾经想都不用想就会蔑视、且从未觉得有任何矛盾的一群人——他必须决定,自己是否准备好公开与那段他付出多年岁月和名声的生活告别。', choices: [
          { label: '站出来,当众如实讲述一切', effects: { faith: 15 }, next: 'denis_endLight' },
          { label: '离开,还没准备好如此公开地与过去决裂', effects: { faith: -15 }, next: 'denis_endDark' },
        ] },
        denis_endLight: { text: '德明站了出来,讲述了一切——他曾是谁,如今又是什么感受,毫不掩饰,也没有把纹身藏进袖子里。"我曾是三K党的大巫师,后来连三K党在我看来都不够仇恨,于是我决定成为一名纳粹",他在会众面前大声说出这句话——据他自己后来说,在场一半人当场目瞪口呆,但礼拜结束后没有一个人对他说过一句难听话。他在那同一个会众的歌声中受洗于大西洋,而昔日的战友从此把他从所有名单上划掉,当作叛徒。如今他就在那间教会聚会——那里的会众,曾经仅仅因为出身,就是他眼中的敌人——他也在一点点淡去那些已经不再代表他是谁的纹身。德明的故事,到此结束。', next: null, choices: [] },
        denis_endDark: { text: '德明那天离开了,还没准备好当着证人的面与过去决裂,也不愿失去在这个赋予自己意义的团伙中的位置。牧师依然在他身边,继续邀请他,但德明本人始终徘徊在两个世界之间,从未彻底做出选择——与此同时,他曾献出青春的那个团体,在一次次类似他当年参加过的游行之后频频登上新闻,成员却一个接一个地流失,再也不复当年声势。德明的故事,到此结束。', next: null, choices: [] },
      },
    },
    ignat: {
      start: 'ignat_intro',
      scenes: {
        ignat_intro: { text: '一鸣在一个信仰被禁止的国家里,秘密带领着一个小型家庭教会——在那里,仅仅在外人面前提到基督的名字,就可能换来劳改营的终身刑期。他自己的母亲几年前也曾因同样的事被捕,至今未归,官方记录中她被捕后的下落始终是「下落不明」,即使对家人也是如此。一鸣每次聚会开始和结束时,都用几乎听不见的低语念诵同一段主祷文——这是唯一一样,即便突击搜查也无法找到、没收或记录在案的东西。', next: 'ignat_scene2' },
        ignat_scene2: { text: '聚会每周一次,轮流在不同的家里进行,深夜,窗帘紧闭,连一支多余的蜡烛都不点。一鸣不仅能背诵他朗读的经文,还记得每一个冒险前来参加的人的面孔——他知道,一旦被捕,这些面孔就会是调查名单上的第一批人。多年来,他甚至没有告诉自己的孩子,晚上到底在做什么。除了聚会本身,他还秘密把手抄的圣经页面和小包属灵读物,以普通礼物的名义送给邻村的信徒——单凭这一项,当局就足以另立罪名,哪怕一次聚会都没有。', next: 'ignat_choice1' },
        ignat_choice1: { text: '邻居们开始询问那些偶尔在夜里进出一鸣家的人——太过频繁,不像是偶然的访客,其中一人甚至向片警投诉说这是个「奇怪的教派」。后来才知道,参加聚会的人中有一个是告密者,详细上报每次聚会,包括在场者的姓名和面孔。', choices: [
          { label: '继续聚会,信靠神而非自己的安全', effects: { faith: 10 }, next: 'ignat_bridgeA' },
          { label: '停止聚会,躲藏起来以保护教会', effects: { faith: -10 }, next: 'ignat_bridgeB' },
        ] },
        ignat_bridgeA: { text: '一鸣继续聚会,只是更加小心——每次人数更少,时间不定,用暗语代替直接的名字,聚会伪装成生日会,还备好真正的蛋糕以防突击检查。教会的处境变得更艰难,但依然在生存和成长,只是比从前更慢、更安静。认识他的邻居后来说,他有钢铁般的性格:曾有一名地方官员暗示只要收下贿赂就对聚会保持沉默,他当面拒绝,尽管这一次拒绝本可能让他早在任何搜查之前就失去自由。', next: 'ignat_choice2' },
        ignat_bridgeB: { text: '一鸣停止了聚会数月,给所有人发出了同样简短的警告。会众们各自散去,独自在家祷告,但那份多年来维系着他们的联结,却在一周又一周的沉默中悄悄削弱。聚会最终恢复时,可信赖的核心圈子缩小了一半,那份多年来凝聚教会的旧日温暖,再也无法完全找回。', next: 'ignat_choice2' },
        ignat_choice2: { text: '一鸣还是在夜里被捕了,一场持续数小时的搜查,在惊恐的孩子们眼前把整个家翻了个底朝天。官方罪名听起来生硬而公式化:组织未登记的宗教团体,意图针对国家——只因在自己家中祷告、分发圣经。审讯中,调查员用相当友善的语气,提出用几个名字换取他的自由——那些晚上到他家来的人的名字。', choices: [
          { label: '保持沉默,不论后果如何', effects: { faith: 15 }, next: 'ignat_endLight' },
          { label: '说出名字,换取自由', effects: { faith: -15 }, next: 'ignat_endDark' },
        ] },
        ignat_endLight: { text: '一鸣在所有审讯中都保持了沉默,不管调查员如何软硬兼施,最终他被转往一处特殊的政治劳改营——就像多年前他的母亲一样,从此再也没能回来。和母亲一样,他的下落对家人来说,正式记录始终是"下落不明"。但幸存下来的教会成员和邻居们,几十年来一直在暗中把这个故事传下去,记得他是这样一个人:从未说出过一个名字,也从未向任何人低过头——哪怕是在自己生命的尽头。一鸣的故事,到此结束。', next: null, choices: [] },
        ignat_endDark: { text: '一鸣说出了名字,一周之内重获自由——但他在压力下说出的每一个名字,都是一个曾经比世上任何人都更信任他的人。自由的代价很高昂,只是这代价并非只有他一人承担,那些被他说出名字的人也一同付出了代价。其中一些人在再次搜查前及时躲了起来,但并非所有人都逃过一劫,自那一周起,这一带的信仰声音明显变得更加低沉。一鸣的故事,到此结束。', next: null, choices: [] },
      },
    },
    artem: {
      start: 'artem_intro',
      scenes: {
        artem_intro: { text: '子轩靠房地产贷款做起生意,几年之内变得真正富有——新房子、豪车、在城市商界的名声——直到市场在一年之内崩溃,带走了他建立的一切,只留下带着利息的债务。到二十六岁时,他和妻子已经拥有一份价值数百万美元的房地产组合,全靠借来的钱撑起——市场一出现裂缝,银行便同时要求提前偿还所有短期贷款,这样的要求几乎没有哪个同类组合能扛得住。', next: 'artem_scene2' },
        artem_scene2: { text: '崩溃之后的最初几个月,子轩仍试图挽救部分资产,一件件卖掉车和手表,只为拖延向银行摊牌的那一刻。夜里,他反复在纸上核算着同样的数字,仿佛这样就能改变那早已显而易见的结局。子轩和妻子在九月的最后几天签署了个人破产文件——这个日期他记了一辈子,因为按他后来的话说,正是从那一天起,开始的是一段完全不同的故事,而不仅仅是旧故事的结束。他后来在采访中不止一次说,自己在不到一年的时间里从百万富翁变成了破产者——正是那种坠落的速度,让他开始怀疑钱是否还能用他从前那一套方法重新建立起来。', next: 'artem_choice1' },
        artem_choice1: { text: '银行要求归还子轩已经不再拥有的钱,以任何形式都拿不出来。妻子看着厨房桌上那堆文件,轻声问道,没有责备:"如果我们从真正属于我们的东西开始,而不是从钱开始,会怎么样?"', choices: [
          { label: '第一次诚实地审视自己没有金钱作为成功标准的人生', effects: { faith: 10 }, next: 'artem_bridgeA' },
          { label: '继续想方设法不惜一切代价把钱要回来', effects: { faith: -10 }, next: 'artem_bridgeB' },
        ] },
        artem_bridgeA: { text: '子轩开始和妻子一起参加教会里一个小组的聚会——这是他以前绝不会踏足的地方,曾经他还自认为高人一等——那里谈论的不是投资,也不是如何挽回损失,而是当再也没有什么、没有任何人可以信靠时,信靠神意味着什么。到了晚上,他生平第一次开始自己读圣经寻找答案,把经文里关于金钱的教导,和自己多年商学院学到的东西相比较——他那套极其简单、由几个具体步骤组成的计划,正是从这种比较中渐渐成形的,而不是又一套新的理财理论。他要找的不是又一个快速翻本的办法,而是关于金钱的简单、诚实的真相——他正是在那些夜晚写在纸上的记录里找到了它,那些纸曾经只记录着绝望的数字,如今渐渐变成了几堂简单课程组成的小课程,他先是自费印刷,没有找任何出版社,后来又开始在自己家里亲自教给几个家庭。', next: 'artem_choice2' },
        artem_bridgeB: { text: '子轩继续追逐一笔又一笔风险越来越高的生意,想靠一次幸运的操作扳回损失。每一次新的尝试都以同样的结局收场——债务更深,下一步的选择更少。', next: 'artem_choice2' },
        artem_choice2: { text: '多年一步步耐心重建财务、不再拥有从前的光鲜、却也不再背负旧日债务之后,有人邀请子轩开始教导别人,讲述他从自己惨痛经历中最终明白的、关于金钱与信仰的道理。', choices: [
          { label: '开始教导,从讲述自己跌倒的故事开始', effects: { faith: 15 }, next: 'artem_endLight' },
          { label: '拒绝——过去的破产太丢脸,不愿提起', effects: { faith: -15 }, next: 'artem_endDark' },
        ] },
        artem_endLight: { text: '子轩开始教导别人,他在每一次聚会上最先讲述的故事,始终是银行夺走他所有,只留下真正重要之物的那一天。他创办了一门以圣经原则为基础的理财课程,渐渐地有成千上万个家庭学过这门课——如今,成千上万的人在听过这个故事后走出了债务。这门课最初只在他家里教几个家庭,不久后就把他带到了一家当时自己也濒临破产的地方电台——那点微不足道的播出时段,渐渐成长为一档如今有数百万人收听的日播节目,而他创办的公司,称自己唯一的宗旨是基于圣经原则的诚实理财教育,而不是快速致富。子轩的故事,到此结束。', next: null, choices: [] },
        artem_endDark: { text: '子轩靠多年苦干重建了财务,但从未向最亲近的人大声提起过那次破产——这成了他家中一个原则上不去谈论的唯一话题。那门他本可以自己创办、教给其他家庭的课程,始终只是别人的主意,他不过是在别人的书里读到过,自己则继续独自在厨房桌前整理着同样一堆数字。子轩的故事,到此结束。', next: null, choices: [] },
      },
    },
    grisha: {
      start: 'grisha_intro',
      scenes: {
        grisha_intro: { text: '十六岁时,国华已经背负着街区里最危险少年的名声——他曾卷入一场街头斗殴中的杀人事件,因此在成人监狱服刑十年以上,尽管在那里他看起来比所有人都年轻。案子还在调查期间,他保释出狱,仅仅四个月后又卷入一场斗殴,杀死了另一个年轻人——正是这第二起杀人案,最终决定了他的最终刑期。', next: 'grisha_scene2' },
        grisha_scene2: { text: '国华在监狱的最初几年,都在向周围所有人证明年纪小并不意味着软弱——这份证明让他吃了好几次拳头,也进过几次禁闭室。他不让任何人靠近自己,包括按日程派来的心理医生和教育人员,在他眼里,他们不过是又一份案卷。在监狱里,他很快成了最年轻的帮派头目之一,后来又被一些年长狱友宣扬的共产主义思想吸引——只要是能许诺一点意义和权力的体系,国华都会紧紧抓住。', next: 'grisha_choice1' },
        grisha_choice1: { text: '监狱里,一位牧师几乎整整两年,每周都来,从未缺席,来到同一排牢房,包括国华的牢房,每次都隔着铁栏大声读几句圣经,得到的都是同样冰冷的沉默,但离开前,他总还是把那本已经翻旧了的圣经留在牢房地板上,不管其他狱警怎么说这些探访毫无意义,他依然一次又一次地回来。', choices: [
          { label: '有一天终于回应他的问题', effects: { faith: 10 }, next: 'grisha_bridgeA' },
          { label: '继续像往常一样保持沉默', effects: { faith: -10 }, next: 'grisha_bridgeB' },
        ] },
        grisha_bridgeA: { text: '国华开口了——先是隔着铁栏说了一个简短的词,后来是一句话,再后来是关于完全无关话题的整段对话。到了夜里,同室的犯人都睡着后,他会偷偷翻开牧师留下的那本圣经,借着走廊透进来的光读上几行,然后,生平第一次,他试着小声地、笨拙地念出一段类似祷告的话。几个月后,他多年来第一次开口谈起了那场打斗本身,谈起了那个被他一拳夺去性命的人的面容。牧师对这变化既不惊讶也不评判,只是继续像从前一样每周前来,仿佛这一切本就是计划好的。一天夜里,牢房里只剩他一个人,国华忽然想起小时候祖父跟他说过的话:总有一天,除了耶稣基督,没有人能帮得了他。就在那一刻,他生平第一次不是照着书本,而是用自己的话,大声向神呼喊。', next: 'grisha_choice2' },
        grisha_bridgeB: { text: '国华一连数月保持沉默,但他自己也注意到,尽管一直沉默,牧师却从未停止前来——这份坚持本身,比任何言语都更让他深思。', next: 'grisha_choice2' },
        grisha_choice2: { text: '接下来的几年里——他辗转全国四所不同的监狱,在铁窗后度过了将近十二年——国华几乎把圣经背了下来,不止一次亲自坐到铁栏边,陪着那些刚入狱、同样惊恐的年轻犯人,用当年牧师对他说过的话,原样讲给他们听。这将近十二年里,他几乎全程都在几所重刑监狱服刑,包括全国最大的一所,最终是一纸总统特赦令还了他自由。即将获释之前,有人提议国华留在监狱教会做义工——回到他自己曾服刑的地方,如今站在铁栏的另一侧,出于自愿,而非判决,而且这份工作没有一分钱报酬。', choices: [
          { label: '留下来,把余生献给走过他这条路的人', effects: { faith: 15 }, next: 'grisha_endLight' },
          { label: '尽可能远离,永不再回头看这座监狱', effects: { faith: -15 }, next: 'grisha_endDark' },
        ] },
        grisha_endLight: { text: '国华留了下来。四十多年后,他依然会去那同一排牢房——当年牧师就是来那里探望还是少年的他——只是如今站在需要他的那一侧铁栏,每周从不缺席,几十年如一日,如今全国各地数十名曾经的服刑人员都称他为那个唯一一个、在所有人早已放弃他们时依然没有先转身离开的人。国华的故事,到此结束。', next: null, choices: [] },
        grisha_endDark: { text: '国华离开了,在能力所及范围内尽可能远离一切让他想起监狱的东西,包括旧日的名字和地址。他此后再也没有对任何人大声提起过去,包括睡前的自己。国华的故事,到此结束。', next: null, choices: [] },
      },
    },
    stas: {
      start: 'stas_intro',
      scenes: {
        stas_intro: { text: '思远曾在选秀大会上以状元身份被选中,职业生涯前几年一路顺风顺水,眼看就要跻身体坛巨星之列,直到伤病和持续的疼痛让他开始服用止痛药,再从止痛药走向酒精和毒品。短短几年内,他失去了合同、名声,几乎失去了整个家庭,妻子也已被无数次的复吸拖垮,认真考虑提出离婚。', next: 'stas_scene2' },
        stas_scene2: { text: '谷底降临在一个具体的夜晚——凌晨两点,嗑了一堆毒品的思远出现在自己祖母家门口,瘦了差不多二十斤,眼神涣散,双手颤抖。他至今还记得祖母站在门口时脸上的表情——不是愤怒,而是一种更可怕的东西:混合着恐惧与怜悯,望着这个她几乎认不出来的人。祖母名叫玛丽,接下来的几周里,她亲自照顾这个瘦得脱了形的孙子,几乎寸步不离,但同时也当场立下了一条不容商量的条件:立刻戒毒,否则就自己另找地方住。', next: 'stas_choice1' },
        stas_choice1: { text: '几天后,在祖母家稍微恢复了一点元气的思远还是又一次复吸了——就在她家里。祖母默默等他从房间里出来,只说了一句话:"我再也受不了了。"然后向他提出了一个挑战:不是再去参加一个康复项目,而是直接向神投降。', choices: [
          { label: '接受这个挑战,不管听起来有多奇怪', effects: { faith: 10 }, next: 'stas_bridgeA' },
          { label: '不理会——像往常一样自己去解决', effects: { faith: -10 }, next: 'stas_bridgeB' },
        ] },
        stas_bridgeA: { text: '思远接受了祖母的挑战,就在那天夜里,又羞愧又绝望的他生平第一次认真地向神祈求,求神把这瘾彻底拿走。他做好了准备,要熬过自己凭以往经验几乎能背出来的戒断反应——但那反应始终没有出现,那一夜没有,第二天没有,一周后也没有,这种"没有"带给他的震惊和恐惧,几乎超过了瘾本身曾经带给他的恐惧。就在那天早上,他随手翻开祖母的圣经,正好翻到这几句话:"务要顺服神。务要抵挡魔鬼,魔鬼就必离开你们逃跑了。"他就是从这节经文开始,数起了自己戒瘾的天数。从那天起,他再也没有碰过毒品,每天早上开始和祖母一起,一天接一天地读圣经,尽管多年后重返职业赛场,他还是有几次在酒精上复发——但每一次,他都选择向媒体坦白承认,而不是隐瞒。', next: 'stas_choice2' },
        stas_bridgeB: { text: '思远没把祖母的挑战当回事,继续像多年来一样自己扛着,只是一次比一次更糟——妻子带着女儿们越来越频繁地回娘家过夜,厌倦了等待他承诺过却始终没有兑现的改变。其中一次复吸就发生在球队春训期间,思远整整消失了好几天,最后被发现是在一家纹身店里,和一群同样迷失的人混在一起——教练组几乎是最后才知道他的下落。', next: 'stas_choice2' },
        stas_choice2: { text: '经过几个月的戒断,加上每周去教会一个小型互助小组——同一位祖母每个周日都开车送他去——妻子同意和他一起接受一系列家庭心理咨询,这不是离婚前走个过场,而是最后一次真正的机会,看思远是否真的愿意在日常生活里一天天地改变,而不只是在祷告聚会那一时的感动里。', choices: [
          { label: '诚实地完成咨询,承认自己的全部过错', effects: { faith: 15 }, next: 'stas_endLight' },
          { label: '表面配合,内心却毫无改变', effects: { faith: -15 }, next: 'stas_endDark' },
        ] },
        stas_endLight: { text: '思远诚实地完成了咨询,第一次在妻子面前坦白承认了自己给这个家造成的全部伤害的深度——在第一次咨询时,他就直接告诉心理咨询师,他的戒瘾靠的不是意志力,而是每天祷告和读圣经的习惯,即便在复发之后也从未间断过。婚姻保住了,几年后他重返职业赛场,已是完全不同的一个人,坦诚地向每一个愿意倾听的人讲述自己的瘾与信仰。球队后来还为他安排了一位固定的"问责伙伴",整个赛季的每一次客场之旅都真的和他同吃同住同行,好让他身边随时有人,一旦感到软弱就能立刻向对方坦白。如今他家里有四个女儿,他坦率地说,每一个清醒的日子,都是需要每天早晨重新从祷告开始做出的决定。思远的故事,到此结束。', next: null, choices: [] },
        stas_endDark: { text: '思远表面上完成了咨询,内心却没有真正改变,几个月后旧习惯渐渐又回来了。婚姻还是破裂了,女儿们记住的父亲,是一个在镜头前谈起改变头头是道、却从未在家里真正做到的人。思远的故事,到此结束。', next: null, choices: [] },
      },
    },
    zhenya: {
      start: 'zhenya_intro',
      scenes: {
        zhenya_intro: { text: '青少年时期,在餐桌上一次次的家庭争吵中,珍怡发现自己的身体是唯一完全属于她自己的东西,它能让她感到强大而不可侵犯:她开始把每一卡路里都精确计算到底,不断减重,直到体重低到危险的地步,连父母都被她用宽大的衣服彻底瞒住,谁都没有发现。', next: 'zhenya_scene2' },
        zhenya_scene2: { text: '那次青少年时期的状况似乎自己就过去了:珍怡以优异的成绩考上大学,成了模范学生,父母也松了一口气,以为女儿只是走过了一段叛逆的年纪。可是十年后,当她正在准备成为一间小教会的牧师妻子、快要读完为未来牧师妻子开设的神学课程时,旧日的习惯却以更猛烈的势头卷土重来——用她后来自己的话说,她从未感到如此被奴役,却又与此同时,从未如此确信自己的力量。', next: 'zhenya_choice1' },
        zhenya_choice1: { text: '一位医生在她于协助丈夫准备主日讲道时突然晕倒、被紧急送院后,直言不讳地告诉她:如果不治疗,心脏可能在任何一个夜晚停止跳动。在医院里辗转难眠的那些时刻,珍怡终于翻开了自己的圣经——那本她在神学课程的两年里一直带在身边、却始终没有读完的圣经——从《启示录》开始读起,病房外的走廊灯光整夜都没有熄灭。', choices: [
          { label: '继续读下去,尽管那些关于食物的念头一刻也没有放过她', effects: { faith: 10 }, next: 'zhenya_bridgeA' },
          { label: '合上圣经——信仰肯定解决不了体重秤的问题', effects: { faith: -10 }, next: 'zhenya_bridgeB' },
        ] },
        zhenya_bridgeA: { text: '当晚,珍怡就读完了整卷《启示录》,内心深处有什么东西松动了:她忽然看清,这些年来她一直把对自己身体的掌控当作力量的最后证明,而这其实一直都是一种奴役,她只是用"力量"这个词,来避免连自己都不敢承认这一点。在那些描写基督站在灯台中间、眼睛如同火焰,以及祂既是狮子又是羔羊、世界都在祂手中的经文里,珍怡多年来第一次感受到的不是因没吃完那盘饭而来的定罪,而是仿佛有一句话直接对她说:"我爱现在这样的你,但我不会让你一直如此——我要给你一个新的开始,给你一个新的名字。"关于食物和数字的念头并没有在一夜之间消失,但多年来第一次,珍怡不再把它们当作证明自己是谁的依据。', next: 'zhenya_choice2' },
        zhenya_bridgeB: { text: '珍怡合上了圣经,没有读完,继续在病房里像在家一样仔细计算热量,只是如今瞒着医生和护士,把剩下的食物藏在枕头下的餐巾纸里。那句本可能在那一夜对她说出的、关于新名字和新开始的话,始终停留在她没有翻到的那几页纸背后,再也没被读到。', next: 'zhenya_choice2' },
        zhenya_choice2: { text: '一年的治疗、反复和持续的内心挣扎之后——这一年里,她要么在为有朝一日能坐在餐桌前不再心算热量而祷告,这是这个故事的一条分支,要么完全独自一人面对旧日的习惯,这是另一条分支——有人邀请珍怡参加一个支持小组,在那里她必须诚实地说出脑海中真正发生的事,而不只是向医生展示体重秤上的数字。', choices: [
          { label: '讲出一切,包括那些令她羞愧的想法', effects: { faith: 15 }, next: 'zhenya_endLight' },
          { label: '只说些泛泛的话,不让任何人看出事情有多严重', effects: { faith: -15 }, next: 'zhenya_endDark' },
        ] },
        zhenya_endLight: { text: '珍怡如实讲述了一切,包括她对食物和身体那些从未敢说出口、哪怕对医生也不敢说的最羞于启齿的想法。疾病没有在一天之内消退,多年后的今天,她的身体仍然承受着这些年她对自己所做的一切留下的后果——但她第一次不再独自一人与之抗争,也不再把那其实一直是奴役的东西称作力量。多年后,她以自己的真名写了两本书,毫不避讳地把事情如实说出,如今她和身为牧师的丈夫一起,支持着那些困在她曾经所在之处的女性。她把第一本书取名为《新名字》,呼应病床上读到的《启示录》那几句话;多年后写的第二本书取名《新的一天》,那时她已经能够坦诚写出反复发作的挣扎,而不只是一次性的彻底痊愈。珍怡的故事,到此结束。', next: null, choices: [] },
        zhenya_endDark: { text: '珍怡在聚会上只说了些泛泛之词,出院时体重数据看起来正常,但脑海中那场无声的战争依然如故。那些她本可能有朝一日以真名写下的书,始终只是一段未曾真正活过的往事,连丈夫她都宁愿绝口不提,仿佛那段最艰难的岁月从未真正在她生命里发生过。珍怡的故事,到此结束。', next: null, choices: [] },
      },
    },
    inna: {
      start: 'inna_intro',
      scenes: {
        inna_intro: { text: '音妍和丈夫在几年间经历了五次流产——发生在不同的孕周,换过不同的医生和治疗方案,每一次希望都比上一次更加脆弱、更加痛苦。其中一次失去的孩子,已经到了可以取名字的孕周,她私下给她取名叫斯嘉丽——只是为了让这个孩子在自己生命里,不只是病历本上的一个日期。', next: 'inna_scene2' },
        inna_scene2: { text: '第二次流产后,音妍不再参加朋友孩子的生日聚会——不是出于嫉妒,而是因为在那种场合微笑已变得让她身体上难以承受。她好几次布置好婴儿房,又好几次拆掉,把小衣服叠进阁楼上的一个箱子里,后来开始在网上以真名公开写日记,记录自己正在经历的一切,没有匿名。她每晚都重读同一句诗篇经文——讲上帝收集并保存人眼泪的那一句——在无法用自己的话祷告的夜晚,她回到这句经文的次数比圣经里任何其他地方都多。', next: 'inna_choice1' },
        inna_choice1: { text: '在发表了一篇关于斯嘉丽格外坦诚的日记之后,一位教会里的朋友无需多言就懂得她全部的痛苦,没有说那句惯常的"神掌管一切",而是径直坐到厨房地板上,和她一起默默流泪,不劝她什么,也不用套话安慰她,临走前她轻声问,能不能以后每天晚上过来,只是一起祷告——不是为了新的怀孕,而是为了让音妍能撑过眼前这一夜。', choices: [
          { label: '允许自己真正地悲伤,而不是假装坚强', effects: { faith: 10 }, next: 'inna_bridgeA' },
          { label: '把悲伤藏得更深,装作一切都好', effects: { faith: -10 }, next: 'inna_bridgeB' },
        ] },
        inna_bridgeA: { text: '多年来第一次,音妍允许自己在丈夫和朋友面前公开哭泣,不再为这些眼泪感到羞愧或道歉,并且答应了那些夜晚的祷告——起初只是听朋友祷告,几周后,她开始用自己的话大声祷告,和朋友一起,把斯嘉丽的名字带到神面前。悲伤并没有因此变小,但它不再是必须独自一人背负的秘密——她写的日记,也开始被成百上千素不相识、正经历同样痛苦的女性阅读。', next: 'inna_choice2' },
        inna_bridgeB: { text: '音妍在人前微笑,把痛苦严格地留给自己,不断对周围人说自己"差不多已经放下了",也拒绝了那些夜晚的祷告——尽管到了夜里,那份痛苦总会伴随着阁楼上同样那几个装小衣服的箱子重新袭来,网上的日记也始终只是一份未曾发表的草稿。', next: 'inna_choice2' },
        inna_choice2: { text: '第五次流产和又一次失败的治疗方案之后,医生毫无保留地说:自然怀孕的可能性极低。一位偶然读到她日记的编辑,提议音妍把这些私人记录写成一本书,给成千上万有着同样经历的女性看——但这意味着要把一切都说出来,包括斯嘉丽这个名字,还有那些在厨房地板上的夜晚祷告,不再只讲给几个知心朋友听,而是讲给完全陌生的人听。', choices: [
          { label: '无论未来如何不确定,都信靠神', effects: { faith: 15 }, next: 'inna_endLight' },
          { label: '把自己封闭在苦毒与对这一切不公的怨恨中', effects: { faith: -15 }, next: 'inna_endDark' },
        ] },
        inna_endLight: { text: '音妍同意了,写下了这本书,没有为了照顾读者的感受而软化任何一句话,包括关于斯嘉丽的那一章,以及她如何重新学会在自己家厨房地板上祷告。这本书传到了成千上万女性手中,她们第一次读到,为未出生的孩子悲伤并不是信心不够,而是通往信心的一条诚实道路的一部分。如今她仍然每晚和那位朋友一起祷告,母亲的身份并没有按她多年计划的方式到来,却真真实实地到来了——通过收养一个失去父母的孩子。音妍的故事,到此结束。', next: null, choices: [] },
        inna_endDark: { text: '音妍拒绝了写书的提议,决定让斯嘉丽这个名字和那些年的失去,只留在家人这个小圈子里。日记始终只是旧电脑里一份未曾发表的草稿,而那些年的苦毒,即便面对最亲近的人,她也从未真正让自己走完全程去面对。音妍的故事,到此结束。', next: null, choices: [] },
      },
    },
    karina: {
      start: 'karina_intro',
      scenes: {
        karina_intro: { text: '凯琳从十八岁起就在一家脱衣舞俱乐部工作——收入确实很好,远超她这个年纪任何普通工作,而她早已不再认真问自己,对此到底作何感受。', next: 'karina_scene2' },
        karina_scene2: { text: '班次从深夜开始,直到凌晨才结束,凯琳早已学会关闭自己内心那个可能会感到羞耻的部分——只有在偶尔于白天商场里瞥见昔日同学的目光时,才会短暂地重新打开。', next: 'karina_choice1' },
        karina_choice1: { text: '一群来自本地教会的女性开始定期在夜里来到俱乐部附近——不是带着定罪或关于罪的小册子,而是带着简单的礼物,和一张写着"你值得更好"的纸条,挨个点名送给每一位舞者。带领这群人的女性,自己也曾在类似的俱乐部跳舞六年,从二十一岁起——直到对千禧年末日的恐惧让她生平第一次在祷告中恳求神不要让她死;一年后,她读完课程离开了这个行业,生平第一次走进一间普通教会,在门口就哭了,把自己的一生毫无保留地交给了神,再也没有回头。', choices: [
          { label: '收下礼物,至少读一读那张纸条', effects: { faith: 10 }, next: 'karina_bridgeA' },
          { label: '扔掉礼物——她不需要任何人的怜悯', effects: { faith: -10 }, next: 'karina_bridgeB' },
        ] },
        karina_bridgeA: { text: '那天夜里,凯琳在换场之间把纸条反复读了好几遍,小心不让化妆间里的其他女孩注意到,还在纸条底部发现了一小段圣经经文的链接——下班后,她生平第一次在手机上打开了圣经,只是想看看上面写了什么。就在那天早上,她生平第一次尝试用自己的话祷告——笨拙地、没有任何背好的词句,只是在空荡荡的公寓里大声说出来。几周后,她终于给纸条下方留下的号码发了消息——只是想弄清楚,这些女人到底想从她这里得到什么,为什么她们一周又一周地来俱乐部,自己却什么好处都得不到。对方回复说,这项事工正式成立于那年的耶稣受难日,创始人当时决定以基督之名为其命名,而志愿者有时甚至会自己付钱给俱乐部,只为换来和舞者单独相处的时间——不是为了看表演,只是想不带评判、不慌不忙地聊聊天。', next: 'karina_choice2' },
        karina_bridgeB: { text: '凯琳当着其他女孩的面把礼物扔进了化妆间的垃圾桶,继续像往常一样工作,可那张简短的纸条不知为何,一连好几天都挥之不去。那群事工的女性依旧每周照常来到俱乐部附近,某天晚上,凯琳还是没忍住,主动在后门和其中一人搭话。对方解释说,这项事工正式成立于那年的耶稣受难日,创始人当时决定以基督之名为其命名,志愿者有时会自己付钱给俱乐部,只为换来和舞者单独相处的时间,但从不是为了看表演——只是想不带评判、不慌不忙地聊聊天,仅此而已。', next: 'karina_choice2' },
        karina_choice2: { text: '这项事工向凯琳提供了具体的帮助——新的职业、课程和临时住所,让她能重新站稳脚跟——还有和同一群女性每周的聚会,每次谈工作和钱之前,她们总是先一起读几句圣经、一起祷告——但这意味着她必须立刻离开俱乐部,失去多年来不仅养活自己、也养活部分亲人的那份收入所带来的安全网,从今往后一切都要重新开始。', choices: [
          { label: '现在就离开,相信事情总会有办法', effects: { faith: 15 }, next: 'karina_endLight' },
          { label: '留下来——把稳定的收入换成一堆承诺太冒险了', effects: { faith: -15 }, next: 'karina_endDark' },
        ] },
        karina_endLight: { text: '凯琳当周就离开了,一个晚上收拾好化妆间里的东西,没有向俱乐部里的任何人解释,新生活最初的几个月,经济上比她想的更艰难。即便在经济最紧张的那几个月,她也从未缺席过一次每周的祷告与圣经聚会——如今,她亲自在类似的俱乐部外迎接其他女孩,每一次都用她自己曾经学会的那句、如今已经熟悉的简短祷告,开始那个夜晚,就像当初有人为她做过的那样。凯琳的故事,到此结束。', next: null, choices: [] },
        karina_endDark: { text: '凯琳留了下来,告诉自己改变可以等到一个更方便、风险更小的时机。那个方便的时机从未自己到来——几周不知不觉变成了又几年同样的生活,同样的处境。她把那张纸条留在了钱包夹层里很久,却始终没有再拨打过那个号码哪怕一次。凯琳的故事,到此结束。', next: null, choices: [] },
      },
    },
    darya: {
      start: 'darya_intro',
      scenes: {
        darya_intro: { text: '黛雅是巅峰时期的职业运动员——国际赛事上的奖牌,广告合同,全国体育杂志封面上一张辨识度极高的面孔。在为镜头准备的一贯微笑之下,她背负着一份二十年来从未向任何人完整说出口的羞耻,连那些看似对她了如指掌的教练也不知道。她十几岁时就接受了对基督的信仰,就在从一个州开车前往另一个州的路上——多年来她始终难以接受一个事实:当年跟她谈起基督的那个人,不久后就是侵犯她的人。', next: 'darya_scene2' },
        darya_scene2: { text: '黛雅早已练就完美采访的艺术——回答正是记者和赞助商所期待的内容,一个字都不偏离那位坚不可摧的冠军形象。在家中,关上门后,这个角色让她付出无数个失眠的夜晚,以及每次大型比赛前的恐慌发作——她的身体比她自己愿意承认的更清楚地记得那段久远的侵害,任何训练中的意外触碰,哪怕再普通不过,都可能毫无预兆地把她拉回二十年前那间童年的房间。这一切,只有教练知道一些,却也并非全部。', next: 'darya_choice1' },
        darya_choice1: { text: '又一次被媒体称为"本赛季最大胜利"的引人瞩目的胜利之后,一位记者在新闻发布会上忽然问的不是技术或对手,而是不管成绩如何,她是不是真的幸福。黛雅在几十台镜头前僵住了一秒,不知是该像过去几百次那样撒谎,还是第一次在自己的职业生涯中说出真话。', choices: [
          { label: '开始渐渐地,至少对自己诚实地面对自己的痛苦', effects: { faith: 10 }, next: 'darya_bridgeA' },
          { label: '用一贯的微笑回应', effects: { faith: -10 }, next: 'darya_bridgeB' },
        ] },
        darya_bridgeA: { text: '"没有,"黛雅对着话筒轻声回答,生平第一次在镜头前没有露出那惯常的礼貌微笑,"不完全是。"全场安静了一秒,她随后开始每周与队里的牧师会面——起初只是走个形式,应付教练组,后来越来越诚实,第一次把二十年成功背后隐藏的东西大声说出来,哪怕是在更衣室的每一面镜子前对自己也不曾承认过。牧师在每次见面前都会与她一同祷告,有一次告诉她一句话,此后她在每一次比赛前都会对自己重复:神在她拿到第一块奖牌之前就已经看见她,而且从未停止过看见她,即便在那些无人知晓的、充满羞耻的岁月里。', next: 'darya_choice2' },
        darya_bridgeB: { text: '黛雅用那套经过多年镜头前训练、和她的技术一样娴熟的一贯微笑作答,像往常一样回家,藏起体育馆里没有一个人察觉到的疲惫。黛雅继续依靠着她多年后会称之为"成绩的成瘾力量"的东西——一次又一次地获胜,远比停下哪怕一秒钟、把少女时代发生在自己身上的事说出口要容易得多。', next: 'darya_choice2' },
        darya_choice2: { text: '结束了这段满是奖牌与杂志封面的运动生涯之后,有人提议黛雅写一本书——不是关于胜利、奖牌和纪录,而正是关于这些年里,在那层给媒体看的光鲜和早已准备好的采访套话之下所隐藏的羞耻与空虚。', choices: [
          { label: '如实写出来,不加任何修饰', effects: { faith: 15 }, next: 'darya_endLight' },
          { label: '拒绝——不可战胜的运动员形象比真相更安全', effects: { faith: -15 }, next: 'darya_endDark' },
        ] },
        darya_endLight: { text: '黛雅如实写了出来,没有为了她守护了二十年的那个不可战胜的冠军形象而软化任何内容。这本书在全国其他运动员中流传开来,许多人第一次发现,自己并不是唯一一个在奖牌和代言合同之下,像她曾经那样小心翼翼地藏着同样羞耻的人。她从未缺席过一次与队里牧师的每周祷告聚会——那是她退役之后,唯一从未放弃的"训练"。退役两年后,她终于开始真正面对那个被她用训练和胜利掩盖了二十年的创伤,并把自己的书定名为《属于自己的路:一名职业运动员从伤痛到使命的旅程》。后来她以自己的名字设立了一个基金会,教导教练和各支国家队的牧师不仅从身体上,更要从情感和灵性上理解运动员的创伤。黛雅的故事,到此结束。', next: null, choices: [] },
        darya_endDark: { text: '黛雅拒绝了这本书,那个精心打造的不可战胜的冠军形象,连同教练组之外无人知晓的羞耻,永远留在了她身上。黛雅的故事,到此结束。', next: null, choices: [] },
      },
    },
    milana: {
      start: 'milana_intro',
      scenes: {
        milana_intro: { text: '明兰三十四岁那年,她是一间小教会牧师的妻子,也是四个孩子的母亲,乳腺癌确诊后医生说出"第四期"这几个字——诊室里剩下的谈话,她几乎什么都不记得了,只记得自己盯着医生肩膀后面那盏台灯,数着灯座上的反光。这位连续二十年、几乎每周都为别人家庭大声祷告的女人,那天晚上却发现,无论怎么努力,自己都说不出一句为自己祷告的话。', next: 'milana_scene2' },
        milana_scene2: { text: '明兰像平常一样回家,望着窗外那些熟悉的房子,心想外面的世界看起来和昨天一模一样,尽管她内心刚刚发生了一场地震。经过几个月的治疗,她仍然没能重新找回用自己的话祷告的能力,于是开始在网上以真名公开写一本关于自己病情的日记——不是为了博取同情,而是因为她再也没有力气对着会众微笑,假装一切都好。她把日记取名为《平凡的忠信》,在第一篇里就写道:信仰不是靠罕见的神迹撑起来的,而是靠日复一日的坚持,包括最平常也最难熬的日子。', next: 'milana_choice1' },
        milana_choice1: { text: '一位护士朋友是最先得知诊断结果的人之一,她没有用"保持积极心态"之类空洞的话来安慰,而是直接问道:"要不要我陪你去每一次化疗,就只是坐在你身边?"明兰想起自己二十年来正是这样,不靠现成的安慰话语,只凭单纯的陪伴守在病床边安慰会众,如今轮到她从别人那里接受同样的陪伴。', choices: [
          { label: '答应——独自面对这一切太可怕了', effects: { faith: 10 }, next: 'milana_bridgeA' },
          { label: '拒绝——不想用自己的病拖累任何人', effects: { faith: -10 }, next: 'milana_bridgeB' },
        ] },
        milana_bridgeA: { text: '朋友如约陪着她去了每一次治疗,一次都没有缺席,输液之间,她们一起祷告——有时用朋友自己的话,那是明兰在沉默了那么多周之后,终于在自己心里重新找回的话语;有时只是静静地坐着,在仪器均匀的嗡鸣声中十指相扣。让明兰自己都感到意外的是,全国各地成千上万素不相识的人开始阅读她日记里关于这些时刻的记录。', next: 'milana_choice2' },
        milana_bridgeB: { text: '明兰独自经历了化疗,一小时又一小时,在同样的仪器嗡鸣声中,向所有人,包括她自己,隐藏着每次注射之间她心底真正的恐惧,日记也写得越来越少,发表前总是把最诚实的段落删掉。', next: 'milana_choice2' },
        milana_choice2: { text: '当明兰的日记在全国范围内变得为人所知后,她从新闻里得知,一位和她同龄、身患绝症的女性依照安乐死法律公开为自己定下了结束生命的日期。一位编辑提议明兰给这位素不相识的女性写一封公开信——一封邀请对方喝咖啡的信,而不是一封审判信——他清楚这封信必然会被数百万人读到,而她自己的病情和信仰也将暴露在全国目光之下,包括那些心怀恶意的人。', choices: [
          { label: '写一封诚实的公开信,不管结果如何', effects: { faith: 15 }, next: 'milana_endLight' },
          { label: '不参与——这太私人了,不该公之于众', effects: { faith: -15 }, next: 'milana_endDark' },
        ] },
        milana_endLight: { text: '明兰写了这封信,邀请这位陌生人喝一杯咖啡,而不是审判她,这封信传遍了全国新闻,在全国范围内引发了一场争论。几个月后,病情还是恶化了,但明兰直到生命最后几周仍在坚持写日记,每天晚上仍然用那句她当年在输液间重新找回的短短祷词祷告——在日记里,她写道:纵然恐惧仍在,平安是每天都要做出的选择,而不是一次性的决定。明兰的故事,到此结束。', next: null, choices: [] },
        milana_endDark: { text: '明兰选择不参与,认定个人的疾病不该成为全国性争论的话题。这本日记始终只在她所在教会的小圈子里为人所知,而这个决定也从未给她带来真正的平安——她依然活在一次又一次的检查之间,怀着和确诊那天一样的无声恐惧。明兰的故事,到此结束。', next: null, choices: [] },
      },
    },
    egor: {
      start: 'egor_intro',
      scenes: {
        egor_intro: { text: '家豪实现了每一个运动员梦寐以求的一切——顶级品牌的合同,举国皆知的名声,自己的脸出现在全国每家体育用品店的海报上,正是他从小男孩时代起就梦想的一切。但每一次胜利归来,家里等着他的都是同一片沉闷的空虚,无论是金钱还是山呼他名字的看台都填不满。', next: 'egor_scene2' },
        egor_scene2: { text: '家豪早已习惯了精确到分钟的日程——训练、集训、采访,再训练,连续多年日历上没有一天真正属于自己。空闲时间比任何对手都更让他害怕,因为正是在这些间隙里,那份空虚才格外真切,而他又无从分心。有一位队友,一连四个赛季,每次训练后都裹着毛巾、衣服还没穿好就直接问他同一个问题:"你认识耶稣吗?"——家豪一连几个月都只是敷衍过去,直到那第四个赛季的伤病开始一个接一个地累积起来。', next: 'egor_choice1' },
        egor_choice1: { text: '在赛季最高峰时遭遇一次几乎终结他运动生涯、需要连续做两次手术的严重膝伤之后,家豪多年来第一次没有了体育,没有了日程,没有了他早已习惯的运动员身份——只剩下康复病房四面墙壁之间的自己,再也没有人为他的名字欢呼。', choices: [
          { label: '利用这段空当,诚实地问问自己,离开胜利之后自己是谁', effects: { faith: 10 }, next: 'egor_bridgeA' },
          { label: '拼尽全力想回到赛场,只为不去面对这个问题', effects: { faith: -10 }, next: 'egor_bridgeB' },
        ] },
        egor_bridgeA: { text: '还在病房里时,那位队友来看望家豪,又像从前在更衣室里几十次那样,直接问他:"你认识耶稣吗?"——这一次,没有看台和训练的喧闹,家豪终于没有敷衍过去。他早就注意到这位队友对待自己妻子的方式,和更衣室里大多数人完全不同——正是这一点,不亚于那个问题本身,让他真正开始认真倾听。他开始参加一个由这位已经退役的队友邀请他加入的信徒运动员小组——那里谈论的不是成绩、纪录和合同,而是当成绩连同健康、青春和合同一起终将消失之后,一个人还剩下什么。', next: 'egor_choice2' },
        egor_bridgeB: { text: '家豪把全部力气都投入到强化康复中,只为尽快回到赛场,不给自己留下面对不安问题的时间。关于离开体育后自己是谁的问题,又一次像从前几十次那样被搁置了。这已经不是第一次了——那位更衣室队友一个赛季接一个赛季地提起同样的话题,家豪则一年又一年地敷衍过去,宁愿戴上耳机沉默,也不愿面对这类问题。', next: 'egor_choice2' },
        egor_choice2: { text: '又一次小组聚会之后深夜给妻子打电话时,家豪没有像往常那样汇报训练成绩,而是第一次诚实地对她说,自己害怕运动生涯永远结束、看台归于寂静的那一天,他必须决定该提前用什么去填补这份空虚,而不是等它把自己彻底吞没。', choices: [
          { label: '完全信靠信仰,而不只是体育,作为意义的来源', effects: { faith: 15 }, next: 'egor_endLight' },
          { label: '继续把体育当作唯一的支柱', effects: { faith: -15 }, next: 'egor_endDark' },
        ] },
        egor_endLight: { text: '家豪在信仰中找到了不会随着生涯和合同一同结束的东西。几年后,体育生涯平静而不张扬地结束了,他多年来一直害怕的那份空虚,再也没有回到它惯常的位置——取而代之的是,家豪进了神学院学习,并和妻子一起建立了一个小型教会团体,如今他自己在那里担任牧师,牧养像他从前那样的人。"这好像是我这辈子第一次感到被真正地爱着,"他当时对自己承认道,而这份感觉,比赛场上任何一次胜利都更加牢固。他和妻子一起建立的这个团体,多年后成长为一个有数千信众的教会。家豪的故事,到此结束。', next: null, choices: [] },
        egor_endDark: { text: '家豪一直把体育当作唯一的意义来源,直到生涯的尽头。当它终于结束时,那份他多年不惜一切代价回避的空虚,以全部的力量袭来,让他无从填补。家豪的故事,到此结束。', next: null, choices: [] },
      },
    },
    vadim: {
      start: 'vadim_intro',
      scenes: {
        vadim_intro: { text: '卫东被判处死刑,罪名是一起为钱财而精心策划的杀人案,而不是在神志不清的状态下犯下的——他在死囚牢房的最初几年里,对整个世界的憎恨,丝毫不亚于对自己所做之事的自我憎恨,他拒绝律师和上诉,因为他真心认为自己不配得到任何宽恕。', next: 'vadim_scene2' },
        vadim_scene2: { text: '卫东的牢房位于关押死囚的走廊尽头——所有人都彼此知道姓名和判决书上写定的日期,谈论起来就像外面的人谈论天气一样平常。卫东早就不再把自己看作是完全意义上活着的人,在法庭宣判之前,他早已把自己从"人"的名单上划掉了。', next: 'vadim_choice1' },
        vadim_choice1: { text: '牧师在第一次踏入死囚区之前,曾用整整三个月的时间反复祷告,思量自己究竟该不该去探望一个素未谋面、被判处死刑的陌生人。拿定主意之后,他开始不论刮风下雨,每周雷打不动地探访卫东,一连数年从未间断,尽管他总是故意背对铁栏,整次探访从头到尾都保持沉默,盼着牧师迟早会厌倦而不再来,就像其他所有探访者一样。', choices: [
          { label: '在某一次探访中,终于转身开口', effects: { faith: 10 }, next: 'vadim_bridgeA' },
          { label: '继续无视牧师,直到最后', effects: { faith: -10 }, next: 'vadim_bridgeB' },
        ] },
        vadim_bridgeA: { text: '令自己都意外的是,卫东在一次探访中开口了,连他自己都说不清为什么偏偏是那一次——多年来第一次,他大声说出了自己所杀之人的全名,以及那一夜的细节——这些他从未告诉过任何人,连出庭时的律师都没告诉过。牧师只是静静地听着,不打断,也不退缩,随后提议隔着铁栏一起读圣经,一周又一周。几年后,卫东在监狱里受洗了。他开始和隔壁牢房的另一名囚犯一起背诵诗篇,多年后,没有任何人正式任命,他自己就成了整个死囚区某种意义上的牧者——每逢又一次处决降临在别人身上,大家都会来找他寻求安慰的话语。', next: 'vadim_choice2' },
        vadim_bridgeB: { text: '卫东在每周的探访中始终保持沉默,尽管他自己也无法完全解释,为什么偏偏是这位牧师,不同于监狱里所有其他工作人员,无论刮风下雨、无论发生什么,都从未停止前来,一次都没有缺席过。多年后,他被转到同一条走廊的另一间牢房,那位始终没能得到一句回应、也从未抱怨过一句的牧师,如今只有狱警还记得——把他当作一个几乎难以置信地有耐心的人。', next: 'vadim_choice2' },
        vadim_choice2: { text: '在预定的处决日期前几周,所有上诉都已彻底用尽,卫东获得了正式机会写信——不仅写给受害者家属,还写给他自己的弟弟,那个他十四岁时也牵连进那个致命夜晚的人——说出他早该说、却因恐惧、羞愧以及"根本不可能被原谅"的笃信而拖延了这么多年的话。', choices: [
          { label: '写一封诚实的信,完全坦白并请求宽恕', effects: { faith: 15 }, next: 'vadim_endLight' },
          { label: '完全不写——已经太迟了,也太丢脸了', effects: { faith: -15 }, next: 'vadim_endDark' },
        ] },
        vadim_endLight: { text: '卫东写了这两封信,信里满是毫无辩解的彻底坦白——一封给受害者家属,请求宽恕;一封给自己的弟弟,承担起作为兄长的责任,为自己当年没能拦住弟弟、反而放任那一夜发生而忏悔。在死囚牢房度过近四十年——这是该国历史上最长的死刑等待期之一——处决当天,他请求唱那首多年来牧师一直在铁栏前为他低声吟唱的圣诗。在死前的正式书面声明中,他只写下两个字——"我有罪"——拒绝任何为自己辩解的尝试,而在此之前不久,他还主动为几名他认为被冤判的狱友申请重审。卫东的故事,到此结束。', next: null, choices: [] },
        vadim_endDark: { text: '卫东始终没有写那封信,一直拖延到那个永远没能及时到来的"最后一天"。处决那天,牧师依然静静地陪在他身边,但卫东本人却始终带着几十年前就该说出、却终究未曾说出口的那句话,悄然离开了人世。牢房里的其他人都知道那位多年来风雨无阻、却从未得到一句回应的牧师,却始终不明白卫东心里更害怕的到底是死亡本身,还是如今想要请求原谅却早已太迟。卫东的故事,到此结束。', next: null, choices: [] },
      },
    },
    kostya: {
      start: 'kostya_intro',
      scenes: {
        kostya_intro: { text: '康泰生来视力只能分辨光和影——世界的轮廓,却看不清脸孔和文字。他生在一个信仰家庭,从很小起,每晚都听见母亲朗读圣经、唱诗篇,正是这些旋律,比任何东西都先,他五岁起就能凭听觉在钢琴上摸索出来,比明眼的同龄孩子认谱还快。三年后,他开始学习用凸点印刷的乐谱,靠指尖读懂音乐,比学会读任何别的东西都早。康泰八岁那年,父母为他找到一位老师,这位老师不仅教他读盲文乐谱,还教他凭耳朵摸索每首曲子的风格来即兴演奏——他用这种方式学的第一批曲子,依然是母亲唱过的那些诗篇。从那以后,即兴演奏就成了他的第二语言,像说话一样自然。', next: 'kostya_scene2' },
        kostya_scene2: { text: '在大学学习音乐治疗时,康泰找到了一份与问题少年打交道的工作——凭听觉记下他们的人生故事,并当场,就在治疗环节进行的同时,把听到的内容变成一首歌,凭记忆当场弹奏出来。这些孩子中很多人确实感到轻松了不少,因为有人把他们的痛苦变成了旋律,而不只是听完点点头。这门专业他是在音乐治疗系读的,实习则去了一家真正的精神病院,在那里为病人的故事谱曲,远早于他后来站在大型音乐厅的舞台上。', next: 'kostya_choice1' },
        kostya_choice1: { text: '一次这样的治疗环节之后,一个少年直接问他:"那你自己的事呢?你自己信的东西,你也能这样写吗?"康泰这才意识到,自己一直只是在写别人的故事,却小心翼翼地避免在台上谈及自己的信仰——而恰恰在那几个月里,这份信仰对他而言正变得越来越真实。', choices: [
          { label: '开始诚实地写关于自己信仰的歌,而不只是别人的故事', effects: { faith: 10 }, next: 'kostya_bridgeA' },
          { label: '继续待在旁观音乐治疗师这个安全的角色里', effects: { faith: -10 }, next: 'kostya_bridgeB' },
        ] },
        kostya_bridgeA: { text: '康泰当场就在那次治疗环节里尝试写下了第一首以自己口吻创作的歌,事先没有任何准备,也不知道会写出什么——他在自己的歌声中,听到了和那些少年唱完歌后一样的释然。他养成了一个习惯:每次坐到乐器前,都先默默祷告,好让恰当的词句和音符自己浮现出来,而且他越来越多地选择的主题,不再是抽象的故事,而是他儿时从母亲那里听来的、直接出自圣经的句子。渐渐地,他这些没有计划的即兴演奏,在音乐会上吸引的听众,竟远远超过了那些精心排练过的曲目。', next: 'kostya_choice2' },
        kostya_bridgeB: { text: '康泰礼貌地回避了那个少年的问题,继续留在自己熟悉、安全的角色里——凭听觉记录别人的故事,对自己的事只字不提。多年以后,他有时会带着遗憾想起那一天,后悔自己终究没有鼓起勇气弹一首真正属于自己的曲子。', next: 'kostya_choice2' },
        kostya_choice2: { text: '一场大型巡演的主办方,提议康泰按照惯常的形式签下整份合约——全是事先排练好的曲目,没有一丝一毫的现场即兴——这样票房可期、稳妥安全,却少了那个真正的风险:让观众当场听见他毫无保障地即兴创作音乐与歌词。', choices: [
          { label: '坚持在观众面前即兴演出,冒着在舞台上失败的风险', effects: { faith: 15 }, next: 'kostya_endLight' },
          { label: '接受这种稳妥的、排练好的形式', effects: { faith: -15 }, next: 'kostya_endDark' },
        ] },
        kostya_endLight: { text: '康泰坚持要即兴演出,他登上舞台时没有带一个事先准备好的音符,音乐和歌词都是在演出过程中当场创作出来的,每场音乐会都以排练时同样的那句默祷开场。四十多年来,他一直以这种形式巡回全国——在演出过程中,当场请观众席分享该为什么事祷告,随即毫无准备地,把这些请求变成一首基于圣经经文的歌——他不再是供人怜悯观赏的猎奇"盲人奇迹",而是一位音乐家,对他而言,视力和真正看清眼前这个人,原来是两件不同的事。谢幕加演时,他至今仍会请观众随口喊出三个词和三个音符,当场把它们编织成一首全新的歌,几十年巡演全国、加拿大和欧洲,从未重复过一次。他在上世纪八十年代创办的录音室,以"荆棘"为名,如今已发行了二十多张唱片,而他的妻子这些年来始终陪伴左右,两人一起把孩子们养大。康泰的故事,到此结束。', next: null, choices: [] },
        kostya_endDark: { text: '康泰接受了这种稳妥、没有即兴的形式,音乐会总是一场接一场顺利地按同样的脚本进行,从这座城市到那座城市。他始终不知道,如果当初冒了那个险,结果会是什么样子。康泰的故事,到此结束。', next: null, choices: [] },
      },
    },
    marat: {
      start: 'marat_intro',
      scenes: {
        marat_intro: { text: '睿智曾是一个黑手党家族的头目之一——不是那种可以加入的帮派,而是那种生来就属于、永远无法退出的家族——敲诈勒索、燃油公司的种种手段、别人赤裸裸的恐惧,近二十年来一直是他寻常工作周的一部分,据后来调查人员估算,仅燃油骗局一项的年流水就高达数亿。', next: 'marat_scene2' },
        marat_scene2: { text: '睿智追随了自己父亲的脚步——父亲数十年来一直是同一个组织的核心人物之一,他从小就把这条路当作理所当然的事,就像自己的姓氏一样,而不是一种选择。到三十五岁时,他已经坐过不止一次牢,深知自己这个世界里那条不成文的规矩:没有人能从组织里"退休",离开的唯一方式是双脚朝前被抬出去。铁窗后唯一的亮色,是他在一次电影拍摄现场认识的一个姑娘——一个信徒,和他以前生活里认识的任何人都截然不同。他曾在自己亲自监制的一部电影里,给这位二十岁的舞者提供了一个角色。两人结了婚。几年后,他们有了孩子。后来,睿智被捕了。', next: 'marat_choice1' },
        marat_choice1: { text: '在一间两米乘三米的单人牢房里,睿智一连待了将近两年半。一次,一名看守从猫眼往里看了一眼,问道:"你脸色不太好,还撑得住吗?"睿智没好气地让他走开——可一分钟后,那名看守又回来了,一声不吭地从门缝底下塞进来一本圣经,什么也没要求。睿智后来把那一夜称为自己一生中几乎最糟糕的一夜——他确信自己就要失去所珍视的一切,再也见不到妻子和孩子了。', choices: [
          { label: '拾起圣经,认真翻开它', effects: { faith: 10 }, next: 'marat_bridgeA' },
          { label: '把圣经扔到牢房角落', effects: { faith: -10 }, next: 'marat_bridgeB' },
        ] },
        marat_bridgeA: { text: '睿智一气之下把圣经摔向牢房的墙壁,可在单人牢房里根本无处可去——最终,闲得无聊,他还是把那本书从地上捡了起来,开始阅读。箴言里的一句话——"人所行的若蒙耶和华喜悦,耶和华也使他的仇敌与他和好"——让他停了下来,反复读了一遍又一遍。他在单人牢房里剩下的那些日子里,手中的圣经再也没有放下过,用他自己的话说,走出那间牢房时,他已经是一个坚定的信徒了。', next: 'marat_choice2' },
        marat_bridgeB: { text: '睿智把圣经扔到牢房角落,决定不靠别人施舍。那本书就那样原封不动地躺了将近两年半的单独监禁时间,而一些他以前从未在自己身上察觉过的念头,却开始不请自来,没有翻开过书里的任何一页。', next: 'marat_choice2' },
        marat_choice2: { text: '出狱之后,睿智必须做一个在他那个世界里绝不可能不付代价的决定:正式、公开地与组织决裂,他清楚地知道,那些前搭档——包括他父亲当年信任过的人——会把这样的举动视为背叛,而这种背叛无论过去有多少功劳、多老的交情,通常都只有一个代价。', choices: [
          { label: '不论后果如何,彻底与组织决裂', effects: { faith: 15 }, next: 'marat_endLight' },
          { label: '形式上留在这一行里,选择熟悉的安全', effects: { faith: -15 }, next: 'marat_endDark' },
        ] },
        marat_endLight: { text: '睿智彻底与组织决裂,和那位在他服刑的这些年里从未怀疑过他的信徒妻子留在了一起,并以真名公开写了一本书,讲述自己以前的生活和信仰的转变。直到今天,他仍是那个组织里少有的、能活着靠自己双脚走出来的高层人物之一。睿智的故事,到此结束。', next: null, choices: [] },
        marat_endDark: { text: '睿智在名义上依然和从前的搭档们绑在一起,选择了熟悉、可预测的危险,而不是未知的自由。那本圣经始终没有被翻开,而那个被扔在单人牢房角落里的机会,后来他想起的次数,远比他愿意向自己承认的要多。睿智的故事,到此结束。', next: null, choices: [] },
      },
    },
    yuriy: {
      start: 'yuriy_intro',
      scenes: {
        yuriy_intro: { text: '宇轩在靠近前线的地方主持着一所小型神学院,战争在一夜之间打到了他自己的城市。他多年来一直当作培养未来牧师之地苦心经营的那栋建筑,落入了炮火轰炸的范围,而宇轩本人,和大多数邻居一样,在头几周就失去了自己的家。他和同事们早在九十年代就在一位美国宣教士的支持下创办了这所神学院,多年来一砖一瓦地建起了他们梦寐以求的图书馆——后来得知士兵们洗劫并摧毁了校园里的几栋楼时,他痛心地反复说,他们所珍视的一切,如今不是烧毁,就是散落,或是被劫走。', next: 'yuriy_scene2' },
        yuriy_scene2: { text: '宇轩没有带着家人撤离、躲到安全的地方,而是和几位老师一起,用租来的大巴组织学生及其家属撤离,他自己则几乎每周都返回前线地区运送人道主义援助物资。他为这几个月写下了一本详细的日记——不是为了自己,而是因为他觉得:如果不记下来,发生过的事会比它本该被遗忘的速度更快地被遗忘。电力和通讯常常一连几天中断,一部分记录后来只能在地下室里,借着烛光,凭记忆重新补写——那间地下室同时也是防空洞,和留下的学生们的临时教室。撤离路线绵延近八百公里,穿过这个饱受战火摧残的国家的半壁河山——一直到西部一座相对平静的城市,宇轩不仅把学生,还把他们的家人和几乎整个教职团队都带到了那里。他不断带着援助物资返回的前线地区,当时已被认为是战后世界上雷区密度最高的地方之一,而他每次坐上驾驶座时都清楚这份风险。', next: 'yuriy_choice1' },
        yuriy_choice1: { text: '在一个持续遭受炮击的小镇上,一群失去父母或与父母失散的少年,身边没有一个大人愿意在这种情况下承担起照顾他们的责任。宇轩必须当场做出决定:要不要在激烈的战事中,担起照顾这些不是自己孩子的责任。', choices: [
          { label: '冒着风险,把这些少年收入自己的照顾之下', effects: { faith: 10 }, next: 'yuriy_bridgeA' },
          { label: '把他们转交给下一批志愿者,继续自己的路线', effects: { faith: -10 }, next: 'yuriy_bridgeB' },
        ] },
        yuriy_bridgeA: { text: '宇轩把这些少年带在身边,把其中一部分安置在神学院幸存的那一翼,和自己的家人住在一起。其中五人此后多年一直留在他的照顾下,而他沿着同一条撤离路线,几乎找到并帮助其余所有人与亲人团聚。', next: 'yuriy_choice2' },
        yuriy_bridgeB: { text: '宇轩把这些少年交给了撤离路线上下一批志愿者,自己按原计划继续赶路,尽管这些具体的孩子后来怎样了这个问题,此后很长一段时间里都让他夜不能寐。', next: 'yuriy_choice2' },
        yuriy_choice2: { text: '在近乎不间断的炮击持续了两年之后,宇轩已经失去了自己的家和神学院旧楼的一半,有人向他提供资助和邀请,让他把剩下的学生和整个教学工作彻底迁往国外、迁往安全之地——而不是继续在满目疮痍的故土上,在炮火下教学、服事。可即便如此,神学院当时也并未完全停课:仍有几十名学生在租来的场地里坚持面授课程,另有八十人通过远程方式学习,分布在全国各个角落,其中有些地方仍然十分危险。', choices: [
          { label: '留下来,不顾炮击,继续在原地服事', effects: { faith: 15 }, next: 'yuriy_endLight' },
          { label: '为了所有人的安全,把神学院迁往国外', effects: { faith: -15 }, next: 'yuriy_endDark' },
        ] },
        yuriy_endLight: { text: '宇轩留了下来,继续在那座满目疮痍的城市里主持神学院,在周围的人早已习以为常的炮火声中培养新一代牧师。后来他把这些年的日记整理成了一本书——不是一部胜利的故事,而是一段诚实的哀恸,夹杂着向神提出、却没有现成答案的问题,还有一段讲述:素不相识之人伸出的手,一次又一次,恰恰在他自己的力量耗尽之时出现在他身边。尽管如此,他从未停止过平常的信仰生活——办了女儿的婚礼,去参加牧师聚会和其他传道人一同祷告,傍晚遛着自己的狗——正是在这些简单、平常的事情里,他找到了继续走下去的力量。宇轩的故事,到此结束。', next: null, choices: [] },
        yuriy_endDark: { text: '宇轩把神学院和剩下的学生迁往了国外,选择了安全,而不是继续在炮火下服事。课程在远为平静的环境中恢复了,但他承认,自己有一部分始终留在了那座他最终离开的、满目疮痍的城市里。宇轩的故事,到此结束。', next: null, choices: [] },
      },
    },
    olya: {
      start: 'olya_intro',
      scenes: {
        olya_intro: { text: '丽雅十七岁那年——从小热爱骑马,对即将到来的毕业班生活满怀期待——七月末,在和朋友们一次与骑马毫无关系的普通切萨皮克湾海滩出游中,她从水面上一艘固定的木筏跳入浅水,判断错了水深,头撞上了沙底——就在那一瞬间,她的人生被严格地分成了之前和之后:她从颈部以下瘫痪,甚至无法转头或呼救。是她的亲妹妹把她从水里拖出来的——妹妹手指被螃蟹咬了一口,才让她回头,发现丽雅一直没有浮上来。', next: 'olya_scene2' },
        olya_scene2: { text: '在医院的最初几个月,对丽雅来说融成了一整个无法分辨的日子——输液,仪器,医生们那些关于"漫长康复过程"的例行话语,而这显然意味着别的东西。朋友们来得越来越少,不知道该跟一个连头都无法转向他们、也无法回握伸来的手的人说些什么。在那些最黑暗的日子里,她不止一次真真切切地祈求一场意外或某种奇迹,干脆结束她的生命——多年后,她坦然把这些绝望的话称为自己对神说的第一句真正诚实的祷告,而不是需要藏起来的可耻软弱。', next: 'olya_choice1' },
        olya_choice1: { text: '在医院病房里,在绝望最深的黑暗中,丽雅得出了一个简单而可怕的想法:如果神真的不存在,那么最合乎逻辑的做法就是结束自己的生命。可她连做这件事的体力都没有,只能对着天花板说出一句短促而绝望的祷告:"如果我不能死,就告诉我该怎样活。"正是这个问题,而不是一个现成的答案,成了丽雅一生中第一次与神真正诚实的对话。', choices: [
          { label: '每天继续这句祷告,寻求一个答案', effects: { faith: 10 }, next: 'olya_bridgeA' },
          { label: '把自己封闭在抑郁中,不让任何人靠近', effects: { faith: -10 }, next: 'olya_bridgeB' },
        ] },
        olya_bridgeA: { text: '朋友和家人开始每天为丽雅祷告,聚集在她的病床边,即便她自己也几乎无力相信这有什么意义。朋友们轮流为她朗读诗篇,而她自己也渐渐学会用咬在牙齿间的一根木棍去翻圣经的书页,重新自己阅读。渐渐地,一步一步,黑暗开始退去——不是因为身体忽然痊愈了,而是因为她不再在那片黑暗中孤身一人。渐渐地,她学会了用牙齿咬着画笔作画,一画就是几个小时,画到别的画家的手指早就该累垮的地步。', next: 'olya_choice2' },
        olya_bridgeB: { text: '丽雅把所有试图探望她的人都挡在门外,转身面对墙壁,把日子都留在病房的黑暗中,完全自愿地独自一人,拒绝任何关于这一切意义的谈话。', next: 'olya_choice2' },
        olya_choice2: { text: '多年坚持不懈的康复之后,有人邀请丽雅成为其他残障人士的导师——公开地、坦然地讲述自己的瘫痪,把它当作自己完整人生故事的一部分,而不仅仅是引人同情的悲剧。', choices: [
          { label: '答应,把自己的故事变成对他人的帮助', effects: { faith: 15 }, next: 'olya_endLight' },
          { label: '拒绝——她已经厌倦了做别人的榜样', effects: { faith: -15 }, next: 'olya_endDark' },
        ] },
        olya_endLight: { text: '丽雅答应了。她结了婚,继续用牙齿咬着画笔作画,大约在事故十二年后,她为全世界的残障人士创办了一个事工。其轮椅项目至今已向一百多个国家送出了超过二十万把翻新的轮椅,并附上以接收者母语印制的圣经。她说,瘫痪成了她以从未有过的方式认识神的地方——如果她仍能用双腿行走,恐怕永远不会如此亲近地认识神——如今,她帮助的已不是几十人,而是全世界成千上万的残障人士,找到同样的安慰。丽雅的故事,到此结束。', next: null, choices: [] },
        olya_endDark: { text: '丽雅拒绝了,彻底把自己封闭起来,始终没有找到那个在医院第一个可怕的夜晚提出的问题的真正答案。岁月流逝,内心的黑暗始终没有完全退去。丽雅的故事,到此结束。', next: null, choices: [] },
      },
    },
    natasha: {
      start: 'natasha_intro',
      scenes: {
        natasha_intro: { text: '曼婷和丈夫在癌症缓慢却无情地夺走他力气的整整三年里,一起写着关于他病情的日记——记录好日子和坏日子,药物的剂量,以及治疗间隙里那些短暂的欢笑瞬间。当他最终去世时,她独自留下,面对这本厚厚的日记,以及一个巨大而可怕的问题:该如何度过剩下的人生——一位年轻的寡妇,在这个年纪,她认识的人几乎没有谁真正懂得那是什么滋味。多年后,正是这些日记页,成了一本书的基础,书中每一章都以她当时不敢说出口的一个对神的追问命名,连对最亲近的人也不敢说。', next: 'natasha_scene2' },
        natasha_scene2: { text: '她丧夫时还不到四十岁——大多数朋友那时还在为婴儿夜里不睡觉而抱怨,而不是为床边空出的那一侧。葬礼后的最初几周,曼婷仍机械地做着许多以前为丈夫做的事——买他最爱的茶,把床上他那一侧留着,还没敢改变家里的任何东西。相识的其他寡妇提醒她,这一切会随时间过去,但没有人能说清究竟需要多长时间。', next: 'natasha_choice1' },
        natasha_choice1: { text: '朋友和亲戚们争相提出各种应对悲伤的办法——不要多想不好的事,用工作分散注意力,为了自己好,尽快向前看。曼婷必须自己决定,是听从这些出于好意的建议,还是按照自己的节奏,以自己的方式悲伤。她被建议去做心理治疗、换个环境休假、任何能分散注意力的办法——这些都没有错,却没有一个回答她心里唯一真正的问题:她祈求了整整三年丈夫痊愈的那位神如今在哪里,为什么她苦苦等待的祷告始终没有回音。', choices: [
          { label: '允许自己悲伤,需要多久就多久,不必匆忙', effects: { faith: 10 }, next: 'natasha_bridgeA' },
          { label: '把悲伤压在心底,装作已经挺过来了', effects: { faith: -10 }, next: 'natasha_bridgeB' },
        ] },
        natasha_bridgeA: { text: '曼婷继续写日记,只是如今写的是自己的悲伤,而不再是他的病情。每一篇都以同样的方式开头——"亲爱的神"——她写得毫无保留地诚实,不刻意显得比自己实际感受到的更虔诚,这份坦率的勇气,她说是从大卫的诗篇中借来的,那里赞美与向神的直接质问并存。她每周去一次教会里专为年轻寡妇设立的小组,正是在那里,而不是独自伏案时,悲伤才渐渐变得可以承受。渐渐地,零散的日记汇成了篇章,她给每一章起的名字,不是虔诚的标题,而正是那个她曾不敢说出口的、对神的追问。', next: 'natasha_choice2' },
        natasha_bridgeB: { text: '葬礼刚过一个月,曼婷就已经在人前小心翼翼地微笑,装作自己比实际状况恢复得更好,尽管到了夜里,她哭得如此响亮、如此长久,以至于隔壁的邻居有时会来敲门,以为出了什么新的事。她和丈夫一起开始写的那本日记,始终合着放在床头柜上——她再也无法逼自己在里面添上一行字,哪怕独自一人、没有人看见那张练出来的笑容背后藏着什么的时候。', next: 'natasha_choice2' },
        natasha_choice2: { text: '失去丈夫多年后,有人提议曼婷用自己的真名,把私人日记里的内容整理成一本正式的书——把这份极其私密、只在最黑暗的夜里写给自己看的东西,提供给成千上万正在经历同样处境的其他年轻寡妇。', choices: [
          { label: '全部公开,包括最黑暗的那些篇章', effects: { faith: 15 }, next: 'natasha_endLight' },
          { label: '拒绝——有些东西应该保持私密', effects: { faith: -15 }, next: 'natasha_endDark' },
        ] },
        natasha_endLight: { text: '曼婷把这本书完整地公开了,连关于葬礼后第一年最难以启齿的篇章都一字未删,保留了里面每一句"亲爱的神",没有把它们磨平成更疏离的文字。全国各地成千上万的年轻寡妇写信告诉她,她们第一次感到,自己的悲伤并非需要隐藏的羞耻,而是一段可以不必完全孤独走完的共同旅程的一部分,由那同一份诚实的祷告支撑着。后来她自己成了一名演讲者,并主持一档专为全国年轻寡妇开设的播客,那些人和她当年一样,曾找不到一个能如此坦诚交谈的人。曼婷的故事,到此结束。', next: null, choices: [] },
        natasha_endDark: { text: '曼婷拒绝公开日记,把那几本已经磨损的笔记本留在书桌深处的抽屉里。悲伤始终是她一个人独自背负、未曾与任何人分担的重担,直到她自己生命的尽头。曼婷的故事,到此结束。', next: null, choices: [] },
      },
    },
    lena: {
      start: 'lena_intro',
      scenes: {
        lena_intro: { text: '雅蕾毕业后不久就发现自己怀孕了,还不到二十岁——迎接她的不是成年生活喜悦的开端,而是恐慌,在给诊所打电话之前,她第一个、也是最清晰的念头就是:堕胎是唯一值得考虑的现实出路。在确认怀孕的那次问诊中,医生当场就用红色大字在她的病历卡上写下"堕胎"两个字,仿佛这个决定早已由别人替她做好了。', next: 'lena_scene2' },
        lena_scene2: { text: '雅蕾已经预约好了诊所的手术,但日子一天天过去,独自扛着这个决定让她越来越喘不过气——她还没告诉父母,害怕他们的反应,而每次在脑海里演练那场谈话,她都更清楚地意识到自己没准备好独自承担这一切。手术前一夜她几乎没睡,脑海里反复推演各种可能的结局,却没有一个能让她安心下来,有一次她在黑暗的房间里试着轻声祷告,可话说到一半就不好意思地停住了。', next: 'lena_choice1' },
        lena_choice1: { text: '手术当天,雅蕾在诊所里和其他同样沉默的女性一起等着轮到自己,忽然发现自己在想:是该此时此刻向神祷告,尽管不知道神是否真的会听像她这样的人,还是干脆按原计划坐等排到自己、把这事了结。', choices: [
          { label: '不再拖延,就在候诊室里向神祷告', effects: { faith: 10 }, next: 'lena_bridgeA' },
          { label: '不分心,按原计划继续', effects: { faith: -10 }, next: 'lena_bridgeB' },
        ] },
        lena_bridgeA: { text: '雅蕾没有从候诊室的椅子上站起来,只是嘴唇微动,默默说道:"主啊,我不想堕胎……我快绝望了。"她忽然感到一种如此清晰、几乎能触摸到的同在,立刻站起身,对自己大声说:"我选择盼望。"她转身走出了门,始终没有等到轮到自己。', next: 'lena_choice2' },
        lena_bridgeB: { text: '雅蕾把那一闪而过的祷告念头甩开,一直坐到排队结束,已经准备好走进诊室,可就在最后一刻,站在门前时,某种东西让她猛地转身离开,始终没有做她一路上都在坚持要做的事。', next: 'lena_choice2' },
        lena_choice2: { text: '当晚回到家,父母得知真相后,出乎她意料的是,没有一句责备,反而给予她毫无保留的支持,答应从第一天起就陪她走过整个为人母的路。可当消息传到他们教会的团契后,雅蕾必须决定,是否要把这些其实并不太熟的人的关心,引入自己生命中最脆弱的部分,把她曾在诊所候诊室对神说出的那份绝望也一并交托给他们,还是礼貌地与他们保持距离,像往常一样独自应付。', choices: [
          { label: '接受团契的关心,哪怕对方并不熟悉', effects: { faith: 15 }, next: 'lena_endLight' },
          { label: '独自一人,靠自己的力量应付', effects: { faith: -15 }, next: 'lena_endDark' },
        ] },
        lena_endLight: { text: '雅蕾接受了团契的关心——那些她连名字都叫不全的教会姐妹们,一次又一次为她筹办迎婴聚会,把她的儿子当作一个大家庭的一份子来欢迎,而不是闲言碎语的话题。雅蕾说,正是在那几个月里,身边的人对她而言真正成了"看得见的耶稣"——不是讲台上一个抽象的道理,而是那位她曾在诊所候诊室、在人生最绝望的时刻求告过的神,活生生、摸得着的同在。多年后,她亲自为一本基督教女性杂志写了一篇文章,好让面临同样抉择的其他女孩知道,她们不必独自走过这条路。雅蕾的故事,到此结束。', next: null, choices: [] },
        lena_endDark: { text: '雅蕾选择靠自己的力量应付,礼貌但坚决地拒绝了团契介入她的生活。原本可以得到的关心,始终只是一个没有兑现的可能,而她在为人母最初的那几个月里,过得比本可以的样子孤独得多。雅蕾的故事,到此结束。', next: null, choices: [] },
      },
    },
    vera: {
      start: 'vera_intro',
      scenes: {
        vera_intro: { text: '早在痴呆症最终得到正式确诊之前很久,信慧就开始注意到母亲在日期上令人担忧的混乱,以及不断重复的问题——光是拿到一个准确的诊断,就花了将近三年时间。诊断终于确定后,信慧辞去了工作,成了母亲的主要照顾者。', next: 'vera_scene2' },
        vera_scene2: { text: '起初,一处带护理的独立居所对母亲来说就够了——信慧原以为这样能维持很长一段时间。但仅仅半年后,母亲就需要更多照顾:先是转入全天候护理病区,后来又转进一个专门病区,那里住的都是连普通护理人员的照看都已应付不了的人。就在同一年,信慧自己也因为长期搬扶母亲而血压骤升、膝盖疼痛,不久后医生又诊断出她丈夫患上了帕金森病,于是她一下子要同时照顾两位至亲。', next: 'vera_choice1' },
        vera_choice1: { text: '这些年来,信慧每天晚上都跪在母亲床边,用同样的话祈求同一件事——求神干脆让这病停下来。当终于清楚地看出这个祷告注定得不到回应时,她必须自己决定,往后该拿祷告怎么办。', choices: [
          { label: '继续祷告,但不再求痊愈', effects: { faith: 10 }, next: 'vera_bridgeA' },
          { label: '干脆不再祷告了——反正显然不管用', effects: { faith: -10 }, next: 'vera_bridgeB' },
        ] },
        vera_bridgeA: { text: '信慧开始每周二参加圣经查经班,还加入了教会里为夫妻设立的一个互助小组——只是为了不独自一人熬过这一切。在那里,她渐渐学会留意她自己称之为"恩典时刻"的东西:哪怕几乎失去了其他一切,母亲却始终没有失去她原本的幽默感——信慧开始把这些小事,看作和她最初祈求的痊愈同样真实的神的回应。其中一次这样的时刻发生在一位远亲的葬礼上:母亲先是把信慧错认成表姐,过了一分钟又忽然仔细看了看她,说道:"真高兴知道你是我女儿——我一直都很喜欢你。"', next: 'vera_choice2' },
        vera_bridgeB: { text: '信慧干脆不再祷告了,她认定既然最主要的祈求都得不到回应,继续这场对话根本毫无意义。母亲的照护并没有因此变得轻松——信仰恰恰在最需要支撑的那几个月里,不再能提供任何支撑,如今她在全天候护理病区值的那些漫长班次里,常常整段时间一言不发,连对自己都找不出话来说。', next: 'vera_choice2' },
        vera_choice2: { text: '在整理母亲的旧物时——那时母亲偶尔还能写下只言片语——信慧发现了一张写了一半、却始终没有寄出的贺卡,上面用已经不太稳的笔迹写着几句话:"你是个特别的女儿。我非常爱你。感谢神把你赐给我"——这是在她几乎忘掉所有其他词语之前写下的。她必须决定,是把这个发现留给自己,还是告诉正经历同样处境的其他照顾者。', choices: [
          { label: '把这个发现告诉其他照顾者', effects: { faith: 15 }, next: 'vera_endLight' },
          { label: '把这个发现只留给自己', effects: { faith: -15 }, next: 'vera_endDark' },
        ] },
        vera_endLight: { text: '信慧在自己的互助小组里讲述了那张找到的贺卡,后来又把自己完整的经历发布在一个分享真实见证的基督教平台上——诚实地讲出一切,包括那些年从未得到回应、始终没有发生的痊愈祷告。其他照顾着痴呆症父母的人后来写信告诉她,正是她那句"恩典时刻",第一次帮助他们不再把眼前的一切当作被神遗弃。她至今仍对自己也对别人说:她始终没弄明白神为什么没有让这病停下来,但她确信,这整个故事完完全全都在神的手中。信慧的故事,到此结束。', next: null, choices: [] },
        vera_endDark: { text: '信慧把这个发现只留给了自己,没有和任何人分享。多年后回想起那段时光,她后悔的不是照顾母亲这件事本身,而恰恰是那段沉默——那时她独自一人,守着自己失落的信仰,此后再也没有踏进过教会的互助小组。信慧的故事,到此结束。', next: null, choices: [] },
      },
    },
    alya: {
      start: 'alya_intro',
      scenes: {
        alya_intro: { text: '雅欣从十三岁起,没有任何一个说得清楚的明确原因,就时常被极其严重的惊恐发作击中,好几次她躲进学校洗手间的隔间里,生怕有人听见自己发抖的声音。多年后,她已成为拥有数百万播放量的知名歌手,却仍然对身边几乎所有人隐瞒着这些发作——十三岁那年的同一种惊恐,依然在每一场演唱会的后台等着她。那时候,还是少女的她,发作时不只是恐惧,还伴随着实实在在的身体疼痛——下腹绞痛,恶心想吐——也正是在那间学校隔间里,她第一次不只是躲藏,而是低声地、几乎连自己都听不见地,开始向神求助。', next: 'alya_scene2' },
        alya_scene2: { text: '团队和经纪人眼中的雅欣,是一个沉稳、状态稳定、能在任何镜头前保持从容的艺人——只有极少数人知道,那种有时会在她登台前一刻彻底把她击垮的惊恐。让雅欣害怕的与其说是这种状态本身,不如说是"一旦公开承认,多年建立起来的形象就会崩塌"这个念头。就连最亲近的人起初也不知道,每场演唱会前,她都会在化妆间里闭上眼睛片刻,不只是呼吸,而是真正地祷告,然后才以大家习惯看到的那个自信艺人的样子走向观众。', next: 'alya_choice1' },
        alya_choice1: { text: '有一天,在演出前一次格外严重的发作之后,雅欣试着把自己当下的感受直接写进一首新歌的歌词里,一句都没有修饰或软化——她必须决定,是把这份草稿留在抽屉里,还是真的把它交给制作人,放进新专辑。', choices: [
          { label: '把这首歌原样交出去,什么都不美化', effects: { faith: 10 }, next: 'alya_bridgeA' },
          { label: '把草稿藏起来,另写一首更安全的歌', effects: { faith: -10 }, next: 'alya_bridgeB' },
        ] },
        alya_bridgeA: { text: '雅欣把这首歌原样交给了制作人,一字未改地保留了那个惊恐时刻写下的内容——歌词讲的是她此刻就需要神,而不是等以后情况好转了再说。这首歌作为单曲发行,登上了排行榜首位,卖出了二十五万张——随之,人们第一次公开知道,雅欣这十多年在后台真正经历着什么。她后来说,对她而言这首歌不是抱怨,而几乎是一句大声喊出来的祷告——一种在危机中重新与神直接联系的方式,她相信这样的危机迟早会降临到每个人身上。这首歌后来获得了年度最佳基督教歌曲提名。', next: 'alya_choice2' },
        alya_bridgeB: { text: '雅欣把那份诚实的草稿藏进了抽屉,转而为专辑写了一首更安全、更可预料的歌,里面没有一丝一毫关于那种至今仍在每场演唱会前袭击她的惊恐的暗示。', next: 'alya_choice2' },
        alya_choice2: { text: '几年后——在这个故事的一条分支里,是因为那首极度诚实的歌意外成功,成了单曲;在另一条分支里,则仅仅是因为后台的惊恐始终没有放过她,尽管此后写的歌词都更加安全,它最终还是在她本人意愿之外为人所知——记者们开始一个接一个地直接问雅欣,她究竟只靠祷告应付,还是也看过医生,这是她此前从未在公开场合回答过的问题。', choices: [
          { label: '诚实回答:祷告、心理治疗和药物,三者一起', effects: { faith: 15 }, next: 'alya_endLight' },
          { label: '回避这个问题,让一切维持原样,只以信仰作为唯一说法', effects: { faith: -15 }, next: 'alya_endDark' },
        ] },
        alya_endLight: { text: '雅欣诚实地回答了:祷告和信仰给了她一个群体和一个意义的框架,但真正帮她撑过来的,还有心理治疗和医生开的药物——这一个不能替代那一个。这次坦白,并没有像她担心的那样毁掉她的形象,反而让她成了成千上万粉丝的代言人——他们第一次从一位名人口中听到,一个人可以真心相信神,同时又诚实地接受治疗。后来她写了一本回忆录,讲述自己的心路历程——关于惊恐,关于信仰,也关于一段几乎破裂却又重新修复的婚姻——书名就取自那首诚实的歌里的同一句歌词。雅欣的故事,到此结束。', next: null, choices: [] },
        alya_endDark: { text: '雅欣回避了这个直接的问题,选择让公众形象维持原样——信仰是唯一的解释,只字未提医生或药物。多年来,惊恐发作从未真正消失,而那场原本可以坦诚展开的谈话,也始终没有发生。雅欣的故事,到此结束。', next: null, choices: [] },
      },
    },
    nina: {
      start: 'nina_intro',
      scenes: {
        nina_intro: { text: '念慈还在襁褓中时就得了小儿麻痹症,医生起初未能正确诊断,她童年里前前后后大约有十年时间不是在病房就是在家里,重新学习走路——但令医生自己都惊讶的是,她恢复得非常好,以至于几十年来几乎不再想起这件事——直到成年后,同一批肌肉的疼痛和无力感又开始回来,这一次已经没有再次康复的希望。医生最终把这称为"脊髓灰质炎后综合征",意味着一个曾经赢过这场战役的身体,如今正一点点重新输掉它——医生们直言警告她,随着时间推移,她有完全瘫痪的风险。', next: 'nina_scene2' },
        nina_scene2: { text: '多年来,念慈外表几乎没有变化,这反而让她越来越难向熟人和同事解释自己与日俱增的疲惫和疼痛——在外人看来她完全健康,所以对许多人来说,她的诉苦听起来像是夸大其词。夜里,当肌肉的疼痛让她无法入睡时,她常常梦见一个完全健康的身体,而每天早晨醒来,又重新把她带回原来的疲惫之中。', next: 'nina_choice1' },
        nina_choice1: { text: '多年来,念慈一直恳求神延长并增添自己所剩不多的力气,祷告求神阻止、或至少减缓病情恶化——可她一次又一次醒来,身体依旧,并未痊愈。她必须自己决定,既然答案显然没有按她所求的方式到来,这祷告接下来该怎么继续。', choices: [
          { label: '继续祷告,即使身体没有任何变化', effects: { faith: 10 }, next: 'nina_bridgeA' },
          { label: '因得不到回应而失望,停止祷告', effects: { faith: -10 }, next: 'nina_bridgeB' },
        ] },
        nina_bridgeA: { text: '念慈继续祷告,尽管身体年复一年都没有变化。渐渐地,祷告不再是求医治的请求,而只是变成了与神的一场对话——谈的是如何"带着"疼痛、而不是"战胜"疼痛再多活一天——她说,改变的不是身体,而是"为什么"这个问题本身。', next: 'nina_choice2' },
        nina_bridgeB: { text: '念慈彻底停止了祷告,厌倦了一年又一年重复一个得不到回应的请求。疼痛本身既没有变得更强,也没有变得更弱——只是现在,连在心里,她都没有人可以分担这份疼痛了,医生警告过的那种日益加重的肌肉无力,如今每天清晨都在完全的沉默中等着她,没有一句话是朝天说出的。', next: 'nina_choice2' },
        nina_choice2: { text: '在与这种渐进性疾病共处多年之后,有人邀请念慈写一本书——不是关于那从未发生的医治,而正是关于在长期受苦中,那些诚实的、得不到答案的、向神提出的问题——用她自己的真名,不加任何美化,从童年第一次发病一直写到今天。', choices: [
          { label: '答应下来,写这本书,尽管身体始终没有痊愈', effects: { faith: 15 }, next: 'nina_endLight' },
          { label: '拒绝——她自己都快撑不住了,更别提照顾别人', effects: { faith: -15 }, next: 'nina_endDark' },
        ] },
        nina_endLight: { text: '念慈答应了,写下了这本关于长期患病中那些得不到答案的问题的回忆录,取名《穿越烈火而行》。身体依然带病,疼痛和无力感从未消失,但她说,自己找到了一件比医治本身更重要的东西——一个基督徒的盼望,并不建立在祷告必然带来的结果上,而是建立在她所祷告的那一位的性情之上。后来,成千上万患有隐形慢性疾病的读者写信告诉她,这是他们第一次在自己的疼痛中不再感到孤单。念慈的故事,到此结束。', next: null, choices: [] },
        nina_endDark: { text: '念慈拒绝了,认定自己连照顾自己的力气都快没有了。她继续独自应付,坚信那些这么多年都得不到回应的祷告,不值得再重复一次。念慈的故事,到此结束。', next: null, choices: [] },
      },
    },
    lyuda: {
      start: 'lyuda_intro',
      scenes: {
        lyuda_intro: { text: '丽蓉在两个男孩还很小的时候就收养了这对双胞胎——文浩和文瑞,三岁时才得知两人都患有自闭症,那时他们还从没叫过她一声"妈妈"——语言治疗师用平静的语气,一并说出了两兄弟的诊断,丽蓉望着诊室角落里两把一模一样的儿童椅,感觉自己当初把两个孩子接回家时想象的那幅家庭未来的画面正在崩塌。后来,两个儿子又添了第二个诊断——胎儿酒精谱系障碍,是收养之前就已造成的后果——于是丽蓉要同时在两个小小的身体里,抚养两种叠加在一起的诊断。医生一开始就提醒她:两兄弟的发展可能会走向完全不同的方向,对一个孩子有效的方法,未必对另一个也有效。', next: 'lyuda_scene2' },
        lyuda_scene2: { text: '双重诊断后的第一年,丽蓉跑遍了七位专家,希望至少有一位说他们至少有一个孩子诊断错了,她还专门为两个儿子准备了一本厚厚的本子,把他们俩说出的每一个新词都记下来——她害怕自己会忘记,而两人加起来会说的词实在太少了,少到一个都不能忘。', next: 'lyuda_choice1' },
        lyuda_choice1: { text: '在公园的游乐场上,只要一个兄弟开始摇晃身体、在崩溃中尖叫,另一个也随即跟着回声般地尖叫起来,别的妈妈就会移开目光,悄悄把自己的孩子带到一边——真正懂得如何应对的,只有丽蓉自己,而且连她也不是每次都能应付。', choices: [
          { label: '不顾旁人的目光,继续带孩子去游乐场', effects: { faith: 10 }, next: 'lyuda_bridgeA' },
          { label: '为了避免被评判,不再出门', effects: { faith: -10 }, next: 'lyuda_bridgeB' },
        ] },
        lyuda_bridgeA: { text: '丽蓉继续每天带孩子去同一个游乐场,每次打开单元门之前都会先默默祷告片刻——分别为两个儿子各自的名字祷告,而不是笼统地为两人一起祷告,先为一个,再回头为另一个,因为同时在人前照顾两个孩子实在更难。在最艰难的那些夜晚,她一遍遍对自己重复同一句诗篇经文——不管医生用什么词来形容,两个孩子都是神在母腹中就奇妙创造的。半年后,她遇到了一位妈妈,叫苏珊,她没有像别人那样移开目光,而是走近来,只是问了一句:"我现在能帮你什么,两个孩子一起的话?"', next: 'lyuda_choice2' },
        lyuda_bridgeB: { text: '丽蓉几乎有一整年没有出过门,只在深夜、游乐场早已空无一人时,开车带两个孩子出去透透气。那几个月的孤独,比诊断本身更沉重,也比她一直躲避的任何目光都更沉重,那些偶尔冒出的祷告念头也始终没能说完,因为即便只是在心里,把关着大门独自一人的自己,连一句话都说完的力气也没有了。', next: 'lyuda_choice2' },
        lyuda_choice2: { text: '他们教会的牧师提议帮丽蓉筹办一场特别的主日礼拜,专为有特殊发展需要的孩子的家庭举办——灯光调暗,音乐轻柔,让她的两个儿子都能以本来的样子,在全体会众面前前来参加。', choices: [
          { label: '答应,把自己的故事带到阳光之下', effects: { faith: 15 }, next: 'lyuda_endLight' },
          { label: '拒绝——藏了儿子这么久,不能突然公开示人', effects: { faith: -15 }, next: 'lyuda_endDark' },
        ] },
        lyuda_endLight: { text: '丽蓉答应了。她帮忙创办的这场礼拜,第一年就聚集了三十多个家庭,每一个都曾像她当年带着文浩和文瑞那样,多年躲在家里不出门。多年后,长大成人的两个儿子都在同一个教会团契里找到了自己固定的位置——一个在礼拜前在门口迎接会众,另一个负责音响——两人各自以不同的方式,成了教会远比任何人在他们三岁时那间语言治疗室里所能想象的更加需要的人。丽蓉的故事,到此结束。', next: null, choices: [] },
        lyuda_endDark: { text: '丽蓉拒绝了,害怕在全体会众面前展示自己的儿子。她继续把两个孩子隔绝在众人之外抚养长大,那本记录着他们最初说出的词语的本子,始终留在书桌抽屉里,没有写完——多年后她承认,自己至今后悔的不是儿子们的双重诊断本身,而是那些把他们俩藏起来、不让本可能接纳他们本来面目的人看见的岁月。丽蓉的故事,到此结束。', next: null, choices: [] },
      },
    },
    andrey: {
      start: 'andrey_intro',
      scenes: {
        andrey_intro: { text: '志强在一个信仰被禁止的国家里,创办并带领着一个地下的基督徒青年研经小组——这样一个团体的存在本身,就足以让人被判处劳改营的实刑,可他觉得这件事太重要了,明知有风险也决意去做,尽管他本可以过一种完全平静、不引人注目的生活。他召集起来的这个研经小组把天主教徒、浸信会信徒和东正教徒聚在了一起——在那个年代实属罕见——并逐渐发展成一个网络,这些年来全国各地有成千上万的年轻人从中经过。安全部门通过线人监视了他好几个月,才在黎明时分发起搜查,并没收了家中找到的所有宗教书籍。', next: 'andrey_scene2' },
        andrey_scene2: { text: '研经小组每两周聚一次,轮流在全城不同的公寓里进行,伪装成生日聚会或普通的朋友聚会——志强把整章整章的经文都背了下来,因为家里存放印刷副本,一旦搜查就是直接的罪证。到二十五岁时,他已经习惯了一种持续的感觉:身边任何一个新认识的人都可能是线人,家里的电话也被人窃听着。', next: 'andrey_choice1' },
        andrey_choice1: { text: '搜查之后的审讯中,调查员用相当公事公办的语气,向志强提出用签署一份正式的组织退出声明来换取立即释放——只需在一份现成的文本上签个字,就能免去多年的劳改营刑期。', choices: [
          { label: '拒绝签字,不论后果如何', effects: { faith: 10 }, next: 'andrey_bridgeA' },
          { label: '签字,认定自由比原则更重要', effects: { faith: -10 }, next: 'andrey_bridgeB' },
        ] },
        andrey_bridgeA: { text: '志强拒绝在任何东西上签字。他被判了九年——一座囚犯们私下称之为"死亡营"的特殊制度劳改营。劳改营之后是流放。释放之后,是持续的监视。在营地里,他好几次以绝食抗议关押条件,其中一次断断续续加起来将近两年——只为了一个要求:允许他在牢房里留一本圣经和祈祷书。他还悄悄召集其他囚犯一起祷告,要求所有人从铺位上站起来,因为他说,在神面前应当站着,而不是躺着——他不顾一切谨慎的常理,继续着同样安静的信仰对话,只是如今对象换成了牢房里的其他囚犯。', next: 'andrey_choice2' },
        andrey_bridgeB: { text: '志强签署了退出声明,当天就凭一份保证书重获自由,但那种觉得自己不仅背叛了组织和同伴、更背叛了自己的感觉,比整个刑期本身还要长久地留在他心里。后来他常常后悔的不是当时得到的自由,而是那场他始终没有发起的绝食——本可能至少为他换回一本圣经的那场绝食,可他这辈子再也没敢第二次尝试。', next: 'andrey_choice2' },
        andrey_choice2: { text: '获释后,通过信得过的人,志强得到了一个选择:秘密离开这个必将在下一个机会重新迫害他的国家,或者留下来,继续帮助像他曾经那样身陷营地的人。', choices: [
          { label: '留下来,继续为如今身陷营地的人而战', effects: { faith: 15 }, next: 'andrey_endLight' },
          { label: '离开,把这场斗争抛在身后,换取平静的生活', effects: { faith: -15 }, next: 'andrey_endDark' },
        ] },
        andrey_endLight: { text: '志强留了下来,把接下来的几十年都献给了帮助像他一样经历过劳改营的人——公开地为全国各地身心俱损的良心犯筹集援助,并推动官方正式承认那个曾夺走他九年人生的体制所犯下的罪行。他最终获释,靠的是西方各国领导人对苏联当局的直接外交施压——那种他在单人牢房里从未见过、却原来全世界都知道的国际关注。志强的故事,到此结束。', next: null, choices: [] },
        andrey_endDark: { text: '志强秘密离开了这个国家,选择了个人的安宁,而不是继续这场危险的斗争。在新的地方,他确实获得了安宁,但也一同带来了一个他终生都未曾诚实问过自己的问题:为了自己的自由,他还会愿意再签多少次任何东西。一想到那同样的国际压力最终无论如何都会让像他这样的人获释,根本不需要任何一份退出声明的签字,这个念头每次在新闻里看到那些年份被提起时都会缠上他。志强的故事,到此结束。', next: null, choices: [] },
      },
    },
    gleb: {
      start: 'gleb_intro',
      scenes: {
        gleb_intro: { text: '立群是一支名声大噪的摇滚乐队的吉他手,正处在世界声誉的巅峰——白金唱片,多个大洲座无虚席的体育场,全球数百万忠实歌迷,以及没有固定剂量就无法走上舞台的冰毒。那些年他写下了乐队最脍炙人口的一些即兴段落,而演出前吸一剂,和调音一样,已经成了准备工作里再平常不过的一步——外人只看得见舞台上耀眼的辉煌,永远看不见后台那不为人知的另一面。', next: 'gleb_scene2' },
        gleb_scene2: { text: '巡演之间,立群见到与前妻所生的女儿,最多也就每隔几个月一次,通常还挤在采访和试音之间——每一次,他都发现她又长大了一些,变得更加陌生,而他自己,在化妆间的玻璃后面,对她而言也变得越来越像一个陌生人。他记忆里她还是个学步的孩子,如今照片里却是个几乎认不出来的小学生,他说不清那个跨越到底发生在哪一刻。', next: 'gleb_choice1' },
        gleb_choice1: { text: '那个他很少见到的女儿,有一次在电话里用完全孩子气、毫无防备的声音问他:"爸爸,你还爱我吗?"——这个简单的问题瞬间击穿了立群多年巡演生活中一点点筑起的铠甲,让他一时说不出话来。', choices: [
          { label: '第一次诚实地寻求帮助,而不是独自硬撑', effects: { faith: 10 }, next: 'gleb_bridgeA' },
          { label: '不当回事,把女儿的问题归结为孩子的焦虑', effects: { faith: -10 }, next: 'gleb_bridgeB' },
        ] },
        gleb_bridgeA: { text: '立群就在酒店房间里跪下,一生中第一次认真地向神祷告——如果神真的存在——求祂把这瘾彻底拿走,而他感受到的变化如此真实、如此立竿见影,以至于第二天他就彻底戒掉了所有毒品,没有一丝戒断反应,这是任何医生、心理师或昂贵的戒毒所都从未做到的事。那一夜他睡不着,反而通宵读着房间里那本圣经,如饥似渴,仿佛它就是专门为他一个人写的——尽管他这辈子从没完整读完过其中一章,更别说读到天亮。就在那一夜,一个简单的念头在文字中一再出现,格外击中了他:他仍然是一个蒙爱的儿子,而不是一个还得靠多年循规蹈矩来赢得宽恕的欠债人——而这正是他自己曾经爱自己小女儿的方式,不求任何回报,无论她那天做了什么。', next: 'gleb_choice2' },
        gleb_bridgeB: { text: '立群不耐烦地把这个问题搁在一边,若无其事地回去参加下一场演出,尽管女儿那孩子气的声音,每次他在上台前伸手去拿那一剂毒品时,都会在脑海中回响。他曾独自一人、没告诉任何人,试着在特别重要的演出前减少剂量——但每次到巡演过半都会故态复萌,告诉自己这只是路上的压力,而不是承认自己早已不再掌控自己的生活,这个念头他连对自己都不愿承认。', next: 'gleb_choice2' },
        gleb_choice2: { text: '乐队正准备开始一次规模空前的世界巡演,将为所有成员带来更多的收入,却也必然意味着重新回到那种令人精疲力竭的巡演生活。立群必须当场决定,这一次是否还要跟他们一起去,没有太多时间犹豫。', choices: [
          { label: '为了女儿和新的生活离开乐队', effects: { faith: 15 }, next: 'gleb_endLight' },
          { label: '去巡演,告诉自己这一次会不一样', effects: { faith: -15 }, next: 'gleb_endDark' },
        ] },
        gleb_endLight: { text: '立群不顾经纪团队、唱片公司和全球数百万歌迷的反对,在乐队声望最高的时候,彻底离开了乐队。媒体和部分乐评人称这是一段大有前途的事业的终结,但对他的女儿而言,这却是比任何事业都更重要的开始——一个终于持续陪伴在身边、不再只是巡演间隙匆匆一见的父亲。立群的故事,到此结束。', next: null, choices: [] },
        gleb_endDark: { text: '立群还是去了巡演,告诉自己这一次能用不同的方式控制住毒瘾。巡演进行到一半,一切都回到了老样子——包括上台前的那一剂毒品,以及女儿电话里那个始终没有得到诚实回答的问题。专辑依旧卖出几百万张,体育场依旧座无虚席,而和女儿的通话却越来越短、越来越例行公事,最后几乎只剩经纪人打来电话间隙里一句敷衍的"学校怎么样"——那本圣经始终留在某个巡演行李箱的角落里,再没被打开过。立群的故事,到此结束。', next: null, choices: [] },
      },
    },
    oleg: {
      start: 'oleg_intro',
      scenes: {
        oleg_intro: { text: '皓然在一瞬间同时失去了三个人——妻子、年幼的女儿和自己的母亲——一名醉驾司机在对向车道撞上了载着他全家的汽车。皓然本人和幸存下来的孩子都身受重伤,但那辆载着一家四代人的汽车已经不复存在,他原本计划继续下去的那种生活,也不复存在了。', next: 'oleg_scene2' },
        oleg_scene2: { text: '车祸后最初的几周里,皓然拄着拐杖,身上还打着石膏,在屋子里走来走去——屋里塞满了那三位同时离世之人的物品:女儿的婴儿床,母亲放在餐桌上的圣经,妻子放在首饰盒里的首饰,他始终无法让自己打开那个盒子。朋友和同事已经不知道除了一句干巴巴的"挺住"之外还能对他说什么,渐渐地,来看他的人也越来越少。后来在法庭上才知道,对向车道那名司机此前就曾醉驾,并非人生中第一次——可这件事皓然是很久以后才知道的,当时他还躺在医院病床上,身边是幸存下来的孩子。', next: 'oleg_choice1' },
        oleg_choice1: { text: '一位相熟的心理医生温和地向皓然提出了一个简单、却让他在当时的状态下感到害怕的想法:如此规模的悲伤既不能被迅速克服,也无法被小心绕开——必须完全走进它里面,否则它只会在内心深处越长越大。', choices: [
          { label: '真正走进这份悲伤,不管它有多庞大', effects: { faith: 10 }, next: 'oleg_bridgeA' },
          { label: '把悲伤保持在距离之外,用琐事填满自己', effects: { faith: -10 }, next: 'oleg_bridgeB' },
        ] },
        oleg_bridgeA: { text: '皓然允许自己真正地悲伤,不给自己设定这一切该在何时结束的期限——他在幸存的孩子面前哭泣,不再掩饰眼泪,并渐渐开始把每天从这场巨大的失去中学到的东西记录下来,那些事先谁也无法向他解释清楚的东西。', next: 'oleg_choice2' },
        oleg_bridgeB: { text: '皓然一头扎进各种琐事——修车、整理文件、提前回去上班——用事情填满每一分钟的空闲时间,只求不要独自留在那片曾经同时回荡着三个亲人声音的寂静之中。', next: 'oleg_choice2' },
        oleg_choice2: { text: '车祸多年之后,皓然已经独自把幸存的孩子抚养长大,并完成了神学教育,这时有人邀请他写一本书,讲述自己经历过的一切——诚实地写,包括那些他确信喜乐再也不会以任何形式回到他生命中的月份,也包括他对那晚活下来的司机的愤怒。多年后,皓然在一所大学教神学,学生们不止一次票选他的课是整个求学生涯中最重要的一门课——尽管他自己坦承,自己讲过的任何一堂课,都始终没能真正解释清楚那场悲剧为什么非发生不可。', choices: [
          { label: '写这本书,不为了安慰读者而美化任何东西', effects: { faith: 15 }, next: 'oleg_endLight' },
          { label: '拒绝——这太私密了,不能公之于众', effects: { faith: -15 }, next: 'oleg_endDark' },
        ] },
        oleg_endLight: { text: '皓然如实写下了这本书,毫不粉饰,诚实地把那场车祸带来的悲伤,称之为一场同时降临在他家三代人身上的灾难,而不仅仅是一件需要默默"平静接受"的难事。他开始主张一件让许多读者感到意外的事:灵魂恰恰可以通过这样的失去而成长,而不仅仅是尽管经历了失去依然成长——这份坦白帮助成千上万经历过自己灾难的人,不再为悲伤不按时间表消退而感到羞愧。那名醉驾司机最终因为一个法律上的技术性问题被判无罪,而带着这个事实继续生活下去,几乎比车祸本身还要艰难。就是在那时,皓然在祷告中得出了一个他此后反复重申的结论:饶恕不是一次性的果断举动,而是一段漫长、有时痛苦而缓慢的过程,每当痛苦重新袭来,就必须重新走一遍。皓然的故事,到此结束。', next: null, choices: [] },
        oleg_endDark: { text: '皓然拒绝了写书的邀请,继续用琐事填满自己的日子,始终没有真正停下来面对所发生的一切。多年以后,孩子们注意到,父亲什么都能谈,唯独不谈那唯一真正决定了他们此后整个人生的那一天。那名最终因法律技术性问题被判无罪的醉驾司机,对皓然来说,始终是一道从未愈合、不断溃烂的伤口,他宁可从不靠近它,也不愿哪怕对自己诚实地谈论它。皓然的故事,到此结束。', next: null, choices: [] },
      },
    },
    kirill: {
      start: 'kirill_intro',
      scenes: {
        kirill_intro: { text: '启瑞是一位成功的商人,表面上有着无可挑剔的名声,还有一瓶没有它他连午饭都撑不到的酒。当酒精终于压倒了他的事业和家庭时,他跨越大洋去找当时最著名的一位精神科医生治疗,为此花去了将近一年的时间和一笔不小的家财。', next: 'kirill_scene2' },
        kirill_scene2: { text: '一年的治疗带来了暂时的缓解,可回国后没过几个月,启瑞又开始喝酒,比以前更严重,他第二次去找同一位医生,期待新的疗程或新的药物。可那位声名显赫的精神科医生,却对他说了一句他绝没料到会从一位科学家口中听到的话:医学已经用尽了办法,唯一剩下的机会,是一场真正的属灵转变——这种转变极其罕见地能彻底扭转像他这样绝望的病例。', next: 'kirill_choice1' },
        kirill_choice1: { text: '带着这位唯物主义医生给出的意外诊断回到家中,启瑞得知有一个小型的基督徒平信徒团体,人们在那里公开地、大声地、当着见证人的面,承认自己的罪和软弱,并努力在实际行动中弥补自己给亲近之人带来的伤害。这个团体坚持要求每个成员每天都用四条绝对标准来衡量自己的生活——完全的诚实、完全的纯洁、完全的无私和完全的爱——而不只是偶尔顺带想起信仰。', choices: [
          { label: '去参加一次团体聚会,尽管公开认罪令人害怕', effects: { faith: 10 }, next: 'kirill_bridgeA' },
          { label: '把这个想法当作可笑的业余闹剧一笑置之', effects: { faith: -10 }, next: 'kirill_bridgeB' },
        ] },
        kirill_bridgeA: { text: '启瑞去参加了团体的聚会,并完整地遵循了他们的程序——尽管这对他这种身份的人来说听起来十分怪异:他把自己的意志完全交托给神,大声承认自己无法独自应付;他写下了一份毫不留情、诚实彻底的自己罪过与软弱的清单,一样也不加以美化;他当着见证人的面把这份清单大声念了出来,而不只是独自在寂静中面对自己;他还开始一件一件地弥补自己在多年酗酒期间对具体某些人造成的伤害——用金钱、用道歉、用时间。正是通过这一切,而不仅仅是靠意志力,那折磨了他多年的酒瘾才一天天开始减弱。他后来把这称为一次真正的属灵转变——一次深刻、真实的改变,而不是又一轮治疗带来的暂时缓解。', next: 'kirill_choice2' },
        kirill_bridgeB: { text: '启瑞对这个提议不屑一顾,选择只相信科学和自己的意志力,可这两者从未帮他连续保持清醒超过短短几周。他时不时想起那位精神科医生关于灵性转变的话,但每次都说服自己,这种宗教性不过是迷信,配不上像他这样严肃理性的人,一旦真正陷入困境,他又会回头端起酒杯。', next: 'kirill_choice2' },
        kirill_choice2: { text: '在那次选择多年之后,启瑞过去生活里的一位相识联系上了他——同样是个成功的人,同样在暗中酗酒——直接向他提出一个问题:启瑞是否愿意专门向他一个人,公开地、当着见证人的面,讲述自己堕落的整个经过,以及究竟有没有什么真正帮到过他,一个细节都不加以美化。', choices: [
          { label: '如实讲出一切,不加粉饰,当面公开地讲', effects: { faith: 15 }, next: 'kirill_endLight' },
          { label: '用几句笼统的话敷衍过去,不去翻搅往事', effects: { faith: -15 }, next: 'kirill_endDark' },
        ] },
        kirill_endLight: { text: '启瑞如实讲出了一切,毫无粉饰,这次谈话成了这类坦诚对话链条中的一环——多年以后,正是这样一环接一环的坦诚交流,帮助奠定了一整场如今闻名世界的成瘾者互助运动的基础。启瑞的故事,到此结束。', next: null, choices: [] },
        kirill_endDark: { text: '启瑞用几句笼统的话敷衍了过去,始终没能鼓起勇气向那位相识讲出自己堕落的全部真相,也没讲出到底什么真正帮过他、什么根本没用。一个本可以帮到另一个人的机会就这样擦肩而过,最终只不过是一场办公室紧闭的门后的礼貌交谈。启瑞的故事,到此结束。', next: null, choices: [] },
      },
    },
    vlad: {
      start: 'vlad_intro',
      scenes: {
        vlad_intro: { text: '伟诚因一起他从未犯下的双重杀人案被判处死刑——检方唯一有分量的证据,是弹道专家声称犯罪现场的子弹是从他自己母亲衣柜里找到的一把旧左轮手枪中射出的,尽管那把左轮手枪已经多年没有开过火,早就坏了。审判之前,伟诚甚至通过了警方的测谎测试,证明自己无罪,但法官拒绝将结果纳入案卷,而公设辩护律师错误地以为请不起称职的弹道专家,雇了一个人,此人在法庭上自己都承认根本不会操作分析子弹所需的设备。', next: 'vlad_scene2' },
        vlad_scene2: { text: '伟诚在死囚牢房度过的最初三年里,几乎完全沉默,痛苦地窒息在对所有与他案件有关之人的憎恨中,也包括他自己——因为他未能证明那本该显而易见的事实。他听着走廊里的邻居一个接一个被处决,明白在文件上,自己和他们一样都是"死囚",尽管他完全无辜。', next: 'vlad_choice1' },
        vlad_choice1: { text: '服刑第四年,伟诚为自己下了决定:要么这份憎恨终将杀死他心里最后一丝活着的东西,要么他得在自己的意识内部找到活下去的办法,不再等待那些拖了多年、毫无进展的上诉结果。', choices: [
          { label: '让憎恨之外的东西,进入自己的牢房和心智', effects: { faith: 10 }, next: 'vlad_bridgeA' },
          { label: '把自己封闭在愤怒里,不与任何人分担', effects: { faith: -10 }, next: 'vlad_bridgeB' },
        ] },
        vlad_bridgeA: { text: '伟诚想起小时候母亲对他说过的话:"神无所不能,唯独不能失败。"——他开始每天晚上在牢房里祷告、读圣经,决定既然人间的法庭一次又一次说"不",他就要持守信心,相信他所爱的神不会让他因一件他没做过的事而死。在那之后,他才开始在傍晚隔着铁栏和死囚走廊里的邻居们说话,后来更成了他们许多人无声的依靠——为他们朗读,帮他们写家书,在他们真正的最后一夜里,在心里陪伴着他们,深知对他们来说那真的是最后一夜。他在自己所在的监区组织了一个读书会,有一天,一名死囚走廊里的白人邻居也报名加入了——此人是三K党一位头目的儿子,因残忍杀害一名黑人而被判刑——伟诚强迫自己去为这个人祷告、和他交谈,而不只是和那些容易去爱的人。在接下来的二十七年里,他送走了五十四个人,他们都在距他自己牢房仅几米的地方被处决。', next: 'vlad_choice2' },
        vlad_bridgeB: { text: '伟诚最终把自己彻底封闭在冰冷、沉闷的愤怒之中,拒绝与死囚走廊里的邻居们进行任何交谈。岁月流逝,他牢房附近被处决的人数不断增加,而每一次上诉被驳回,他内心的黑暗都变得更加浓重。', next: 'vlad_choice2' },
        vlad_choice2: { text: '在将近三十年的监禁之后,一支新的律师团队促成了用最先进的设备对弹道证据进行重新鉴定,结果具有决定性:犯罪现场的子弹在物理上根本不可能是从那把找到的左轮手枪中射出的。最高法院撤销了原判,检方在承认鉴定错误后,放弃了重新起诉。伟诚成了自八十年代初以来,全国第一百五十二位被平反、从死囚牢房中获释的人——但对他本人来说,这首先意味着三十年被夺走的岁月,任何统计数字都无法弥补。如今,伟诚真正有了一个选择:该如何面对这个白白夺走他将近三十年人生的司法体制。', choices: [
          { label: '宽恕,同时不停止要求体制改革', effects: { faith: 15 }, next: 'vlad_endLight' },
          { label: '把余生都用来向那些把他送进监狱的人复仇', effects: { faith: -15 }, next: 'vlad_endDark' },
        ] },
        vlad_endLight: { text: '伟诚重获自由,在聚集的记者们难掩惊讶的目光中,在法院外说,他原谅了那些让他为此付出三十年死囚岁月代价的鉴定专家——因为同一位神,正如他这些年来一直相信的那样,不会让他为别人的罪而死,如今,用他自己的话说,这位神让他别无选择,只能选择宽恕。他和帮他重获自由的律师们一起,写了一本讲述自己经历的书,这本书成了国际畅销书,还被全国最著名的电视主持人之一选入她的读书俱乐部,并促使全国重新审查了数十起类似的案件。伟诚的故事,到此结束。', next: null, choices: [] },
        vlad_endDark: { text: '伟诚重获自由,心中只有一个清晰的目标——让所有与他这桩冤案有关的人都付出代价。身体的自由,始终没能真正给他带来摆脱那股吞噬一切的愤怒的自由,而这份愤怒,如今毫无例外地主宰着他此后的每一天。伟诚的故事,到此结束。', next: null, choices: [] },
      },
    },
    kolya: {
      start: 'kolya_intro',
      scenes: {
        kolya_intro: { text: '承恩是一位前途光明的年轻遗传学家,深信宗教信仰不过是一根简单的心理拐杖,专为那些太过害怕、不敢诚实面对一个冷漠、毫无意义、没有神的宇宙的人所准备。在他实习的医院里,守在临终病人床边时,他越来越惊讶地发现,许多病人正是靠着他自己视为幼稚幻觉的那种信仰,才如此平静地面对死亡。', next: 'kolya_scene2' },
        kolya_scene2: { text: '承恩的整个科学生涯都建立在"不接受任何缺乏严格、可验证证据的说法"这一原则之上——他暗自为自己在诊所里最挑剔的怀疑论者的名声而自豪。一位年长的女病人得知他是无神论者后,毫无责备地问他:"医生,你有没有真正认真研究过哪怕一种宗教?还是你根本没弄清楚它们到底教的是什么,就把它们全都否定了?"这个问题让他措手不及,恰恰因为诚实回答就意味着承认:他从未认真研究过。', next: 'kolya_choice1' },
        kolya_choice1: { text: '一位当地牧师——承恩与其说是认真求教,不如说是抱着运动式的兴致去找他的——建议他不要一上来就读神学论著,而是先读一本薄薄的小书,作者曾是无神论者,后来成了基督徒——就当是把他用在自己实验室假设上的那种研究严谨态度,用到信仰这个问题上试试看。承恩从书架上取下那本书,更多是出于礼貌,预料里面无非是些可以预见的虔诚陈词滥调。', choices: [
          { label: '读这本书,以对待任何其他假设同样的严谨态度去研究这个问题', effects: { faith: 10 }, next: 'kolya_bridgeA' },
          { label: '拒绝——作为科学家,这个问题他早就已经有了定论', effects: { faith: -10 }, next: 'kolya_bridgeB' },
        ] },
        kolya_bridgeA: { text: '承恩一个晚上就读完了这本书,随后又反复重读了两遍,书中关于"每个人内心都有的道德律"这一论证的逻辑严密程度令他震惊——正是这个论证,曾让这本书的作者本人从无神论走向信仰。仅仅读到前三页,承恩就不得不勉强承认,自己以往反对信仰的种种理由,听起来更像一个调皮学生的狡辩,而不是一位严肃科学家的论证。接下来的几年里,承恩用业余时间研究科学哲学和历史原始文献,所用的严谨程度,和他发表遗传学论文时一模一样。', next: 'kolya_choice2' },
        kolya_bridgeB: { text: '承恩拒绝把时间花在这样的阅读上,继续做着自己一贯的科学工作,尽管那位年长病人的问题——他是否真正认真研究过哪怕一种宗教——总在实验室里最不合时宜的时刻,不请自来地浮现在他脑海中,尤其是在又一位临终病人的床边,那份平静的信仰,对承恩来说始终是一个无法解释的谜。', next: 'kolya_choice2' },
        kolya_choice2: { text: '一次登山途中,望着一道结冰的瀑布分成三股各自独立的冰流、又在底部重新汇成一股,承恩忽然感到自己多年来对这一切怀抱的抵触,一下子全部消退,只留下一种奇怪、无法解释的释然。他必须决定该如何面对这个突如其来的时刻——一个他自己都无法单纯归咎于长途攀登之疲惫的时刻。', choices: [
          { label: '把它当作一次真正归信的时刻接受下来', effects: { faith: 15 }, next: 'kolya_endLight' },
          { label: '把这份感受归咎于体力透支,若无其事地继续前行', effects: { faith: -15 }, next: 'kolya_endDark' },
        ] },
        kolya_endLight: { text: '承恩把瀑布边的那一刻当作真正归信的开端接受了下来,第二天一早,天刚亮,他就跪在沾满露水的草地上,大声说出自己如今所信的:"神就是神,基督是他的儿子,我把我的生命交给他。"多年后,正是这位昔日的怀疑论者,主持了一项国际人类基因组测序计划,并在科研之余写了一本书,以科学家兼基督徒的双重身份,解释严谨的科学与深沉的信仰为何并不矛盾,反而能在同一个探索的头脑中美好共存。这本书传到了全世界数量惊人的读者手中,而部分科学界人士至今都没有原谅他的这一坦白。承恩的故事,到此结束。', next: null, choices: [] },
        kolya_endDark: { text: '承恩把在山上的感受归咎于疲劳和高原眩晕,若无其事地继续做他的科学研究,小心翼翼地避免再谈起那一天,哪怕是对自己。那位年长病人的问题,此后多年都没有得到一个诚实的答案。承恩的故事,到此结束。', next: null, choices: [] },
      },
    },
    bogdan: {
      start: 'bogdan_intro',
      scenes: {
        bogdan_intro: { text: '天赐作为教会特使前往一个饱受战火摧残的国家——亲自去谈判释放被一个武装团伙扣押的人质——可抵达不到一天,他自己就成了这个他本要与之谈判的团伙的人质之一。他此前已经主持过类似的谈判,并成功促成过其他人质获释,所以这一次他几乎毫无惧色地出发,相信自己教会特使的身份能保护自己。', next: 'bogdan_scene2' },
        bogdan_scene2: { text: '接下来将近五年的大部分时间——其中大约四年——天赐都是在完全的单独监禁中度过的:被铁链锁在一间没有窗户的房间里,看守每次出现时都会蒙住他的眼睛。没有一次与其他囚犯的交谈,没有书,没有钟表,他只能靠稀少的进食次数来计算日子,还有好几次,看守把他拉出去搞假处决,事先从不让他知道那是真是假。', next: 'bogdan_choice1' },
        bogdan_choice1: { text: '在单独监禁的第二年,天赐注意到,自己习惯性地大声祈求的祷告——"把我弄出去"——每次说完之后,留下的只是更尖锐的被抛弃感,而不是宽慰。他必须决定该怎样继续下去:寻找另一种更能持久的方式,在内心守住信仰,还是向绝望彻底屈服。', choices: [
          { label: '在信仰中寻求的不是哀求,而是盼望的操练', effects: { faith: 10 }, next: 'bogdan_bridgeA' },
          { label: '陷入绝望,不再对任何事抱有希望', effects: { faith: -10 }, next: 'bogdan_bridgeB' },
        ] },
        bogdan_bridgeA: { text: '天赐不再向神哀求立刻获释,而是每天早晨在黑暗中,重新对自己重复同一个内心的誓言:身体可以被铁链锁住,心智可以被试图摧毁,但绑架者永远得不到他的灵魂。他持守这份信仰,不是把它当作安慰,而是当作一种需要每天重新付出努力的操练——他不再念求告式的祷告,而是开始在脑海中编织故事,再讲给自己听,好不让理智在黑暗和寂静中彻底溶解。这些故事中的一个,被铐着的那些年里只存在记忆中、一个字都没写下来,后来获释之后,他几乎原封不动地把它写在了纸上——它后来成了他那本关于囚禁经历的回忆录中的一章。', next: 'bogdan_choice2' },
        bogdan_bridgeB: { text: '天赐渐渐陷入深深的绝望,机械地数着日子,不再抱有任何真实的希望——既不指望外面有人来救援,也不再相信这场囚禁真的有一天会彻底结束。那间没有窗户的房间里的寂静,他从前还试着用一些话在心里填满它,如今却日复一日,始终空空如也。', next: 'bogdan_choice2' },
        bogdan_choice2: { text: '将近五年的囚禁、以及教会组织代他进行的长期谈判之后,天赐终于获释——形容枯槁,但还活着,时值十一月,距他被扣为人质、顶替了他本要解救的那些人的那一天,差不多整整五年。回国后,记者们在舷梯下直接问他,是否愿意有朝一日原谅那些把他锁在铁链和黑暗中这么多年的人,还是打算要求给他们最严厉的惩罚。', choices: [
          { label: '说宽恕比任何判决都更能带来自由', effects: { faith: 15 }, next: 'bogdan_endLight' },
          { label: '拒绝宽恕,要求严惩', effects: { faith: -15 }, next: 'bogdan_endDark' },
        ] },
        bogdan_endLight: { text: '天赐对记者说,宽恕比任何法庭判决都更能带来真正的自由——2012年,他亲自回到了那个国家,与曾经的绑架者见面,用他自己的话说,是为了终于埋葬过去的幽灵。获释后不久,他便开始领导一个帮助无家可归者的慈善机构——当时这个机构还只有一个中心,在他的带领下,接下来的几年里发展成了全国几十个社区——他说,那间没有窗户的房间教会了他,在每一个一无所有的人身上,看见曾试图从他身上夺走的那同一份尊严。天赐的故事,到此结束。', next: null, choices: [] },
        bogdan_endDark: { text: '天赐拒绝宽恕绑架者,多年来公开要求对他们施以最严厉的惩罚。他的身体获得了自由,但内心深处,他在很长一段时间里,仍然留在那间他早已在肉体上走出的、没有窗户的黑暗房间里,而那些他曾在黑暗中编出来、为了守住理智的故事,始终没能讲给任何人听。天赐的故事,到此结束。', next: null, choices: [] },
      },
    },
  };

  const data = { CHARACTERS, STORIES };
  if (typeof module !== 'undefined' && module.exports) module.exports = data;
  else { window.Content = window.Content || {}; window.Content.zh = data; }
})();
